out__nav\" aria-label=\"Footer\">{% for link in linklists.footer.links %}<a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"locales":{"en":{"general":{"cart":"Cart"}}},"package":{"author_name":"LetBuyy","compatibility_range":">=2026-06-liquid-sections","currency":"INR","description":"Routine-led personal care with named shades, supplied ingredients and directions.","name":"Dewdrop","price":0,"pricing_type":"free","release_status":"published","site_types":["store"],"slug":"letbuyy-aura","status":"active","version":"2.1.0","version_number":5},"renderer":{"assets":{},"engine":"liquid","liquid_ready":true,"renderer_version":"0.1.0"},"schema_version":"2026-06-liquid-sections","sections":{"404-page":{"path":"sections/404-page.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"404 Not Found","presets":[{"blocks":[],"name":"404 Not Found","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"dd-theme\"><section class=\"lb-404\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-404__code\">404</h1>\n  <p class=\"lb-404__message\">Page not found</p>\n  <a class=\"lb-404__home\" href=\"{{ routes.root_url }}\">Back to home</a>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"404 Not Found\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"404 Not Found\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"about-section":{"path":"sections/about-section.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabl