grid;place-items:center;min-height:150px;height:100%;padding:20px;text-align:center;background:var(--dd-soft);color:var(--dd-muted);font-size:.85rem}\n.dd-hero{display:grid;grid-template-columns:42% 58%;min-height:570px}.dd-hero-copy{padding:65px 42px 65px max(56px,calc((100vw - 1280px)/2));display:flex;flex-direction:column;align-items:start;justify-content:center}.dd-hero-copy h1{margin:20px 0}.dd-hero-copy p{max-width:380px;margin:0 0 27px}.dd-hero-media{min-width:0}.dd-hero-media img{width:100%;height:100%;min-height:570px;object-fit:cover;object-position:65% center}.dd-focus-left img{object-position:left center}.dd-focus-right img{object-position:right center}.dd-hero-empty{grid-template-columns:1fr}.dd-hero-empty .dd-hero-copy{max-width:900px;margin:auto;min-height:350px;padding:50px 28px}\n.dd-routine{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-block:1px solid var(--dd-line)}.dd-routine-item{display:flex;gap:20px;align-items:start;padding:25px 20px;border-inline-end:1px solid var(--dd-line)}.dd-routine-item:last-child{border:0}.dd-routine-item h3{margin:0}.dd-routine-item p{margin:10px 0}.dd-step{font-family:var(--font-display,Georgia,serif);font-size:2rem;color:var(--primary);flex-shrink:0}.dd-shelf{display:grid;grid-template-columns:200px minmax(0,1fr);gap:40px;padding-block:30px;border-bottom:1px solid var(--dd-line)}.dd-shelf-label{display:flex;align-items:start;gap:17px;flex-wrap:wrap}.dd-shelf-label h2{margin:0}.dd-shelf-label p{font-size:.85rem}.dd-shelf-products{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.dd-card{display:grid;grid-template-columns:145px minmax(0,1fr);gap:20px;min-width:0}.dd-card-media{display:block;aspect-ratio:4/5;background:var(--dd-soft);overflow:hidden;border-radius:10px}.dd-card-media img{width:100%;height:100%;object-fit:contain}.dd-card-copy{min-width:0;overflow-wrap:anywhere;padding-top:8px}.dd-card-copy .dd-eyebrow{font-size:.65rem;margin:0 0 9px}.dd-card-heading{display:flex;al