e:.85rem}.dd-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin-block:28px;border-block:1px solid var(--dd-line);padding-block:20px}.dd-filters label{display:grid;gap:8px;font-size:.85rem;max-width:100%}.dd-filters :where(input,select){border:1px solid var(--dd-line);border-radius:5px;padding:11px;background:var(--background);color:var(--foreground);font:inherit;min-height:46px;max-width:100%}.dd-filters input{width:170px}.dd-pagination{display:flex;justify-content:space-between;gap:25px;align-items:center;margin-block:24px}\n.dd-theme .lb-header{background:var(--background);border-bottom:1px solid var(--dd-line)}.dd-theme .lb-header__inner{width:min(1280px,calc(100% - 112px));margin:auto;padding-block:20px}.dd-theme .lb-header__brand{text-decoration:none;font-family:var(--font-display,Georgia,serif);font-size:2.5rem;font-weight:500;letter-spacing:-.04em}.dd-theme .lb-header__search-toggle{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border:0;background:transparent;padding:0;cursor:pointer}.dd-theme .lb-header__account{display:inline-flex;align-items:center;justify-content:center;min-width:44px;min-height:44px}.dd-theme .lb-header__nav-links{gap:28px}.dd-theme .lb-header__nav-links>a{display:inline-flex;align-items:center;min-height:44px}.dd-theme .lb-product-detail__accordion>summary{min-height:44px;display:flex;align-items:center;cursor:pointer}.dd-theme .lb-announcement-bar{background:var(--primary);color:var(--on-primary,#fff);text-align:center;padding:9px 18px;font-size:.8rem}.dd-theme .lb-announcement-bar__inner{justify-content:center}.dd-theme .lb-footer a{display:inline-flex;align-items:center;min-height:44px}.dd-theme .lb-product-detail__breadcrumb{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.dd-theme .lb-product-detail__breadcrumb a{display:inline-flex;align-items:center;min-height:44px;min-width:44px}.dd-theme .lb-footer{background:var(--dd-soft);border-top:1px solid var(--dd-line);padding:45px max(28px,calc((100vw - 1280px)/2))}.dd-theme .lb-product-detail{width:min(1280px,calc(100% - 112px));margin:auto;padding-block:35px 60px}.dd-theme .lb-product-detail__layout{display:grid;grid-template-columns:1.1fr 1fr;gap:70px}.dd-theme .lb-product-detail__info{min-width:0}.dd-theme .lb-product-detail__gallery-main{aspect-ratio:4/5;background:var(--dd-soft);border-radius:12px}.dd-theme .lb-product-detail__layout>.dd-placeholder{height:auto;min-height:250px;aspect-ratio:4/5;align-self:start}.dd-theme .lb-product-detail__gallery-image{width:100%;aspect-ratio:4/5;object-fit:contain;border-radius:12px;background:var(--dd-soft)}.dd-theme .lb-product-detail__variant-group{display:block;width:100%;min-width:0;border:0;padding:0;margin:22px 0}.dd-theme .lb-product-detail__variant-values{width:100%}.dd-theme .lb-product-detail__variant-group legend{font:inherit;font-weight:700;margin-bottom:10px}.dd-theme .lb-product-detail__variant-values{display:flex;gap:10px;flex-wrap:wrap}.dd-theme .lb-product-detail__variant-values button{display:flex;flex-direction:column;gap:7px;align-items:start;min-height:80px;min-width:120px;padding:13px;border:1px solid var(--dd-line);border-radius:7px;background:var(--background);color:var(--foreground);font:inherit}.dd-theme .lb-product-detail__variant-values button[aria-pressed=\"true\"]{outline:2px solid var(--primary);outline-offset:-3px}.dd-theme .lb-product-detail__variant-values button[aria-pressed=\"true\"]:after{content:'✓ Selected';font-size:.75rem}.dd-theme .lb-product-detail__variant-values button:focus-visible{outline:2px solid var(--dd-focus);outline-offset:4px}.dd-swatch{width:28px;height:28px;border:1px solid var(--dd-line);border-radius:50%}.dd-theme .lb-product-detail__variant-status{min-height:1.2em;margin:0;font-size:.85rem}.dd-shade-code{font-size:.75rem}.dd-facts{margin-block:25px;padding-block:18px;border-block:1px solid var(--dd-line)}.dd-facts h2{font-size:1.7rem}.dd-facts h3{font-size:1.35rem}.dd-facts p{font-siz