o{grid-template-columns:1fr}.dd-hero-copy{padding:38px 24px}.dd-hero-copy h1{font-size:3.2rem}.dd-hero-media img{min-height:0;height:345px}.dd-shelf{grid-template-columns:1fr;gap:20px;padding-block:27px}.dd-shelf-label{align-items:center}.dd-card{grid-template-columns:115px minmax(0,1fr);gap:18px}.dd-card-heading{display:block}.dd-card-heading h3 a{display:inline-flex;align-items:center;min-height:44px}.dd-card-heading h3{font-size:1.6rem}.dd-card-heading>span{display:block;margin-top:8px}.dd-card-copy p{font-size:.8rem}.dd-featured{grid-template-columns:1fr}.dd-featured .dd-card{display:grid}.dd-education{grid-template-columns:1fr}.dd-education>img{height:330px}.dd-education-copy{padding:30px 24px}.dd-services{grid-template-columns:1fr}.dd-services article{border-inline-end:0;border-bottom:1px solid var(--dd-line);padding-bottom:20px}.dd-filters{gap:13px}.dd-filters label{width:100%}.dd-filters :where(input,select){width:100%}.dd-theme .lb-product-detail{width:calc(100% - 40px)}.dd-theme .lb-product-detail__layout{grid-template-columns:1fr;gap:30px}.dd-theme .lb-header__inner{width:calc(100% - 32px)}.dd-theme .lb-header__inner{flex-wrap:wrap;gap:8px}.dd-theme .lb-header__brand{text-decoration:none;font-size:2rem;flex:1 0 6ch;min-width:0;max-width:calc(100% - 52px);overflow-wrap:anywhere}.dd-theme .lb-header__actions{margin-inline-start:auto;flex-wrap:wrap;max-width:100%;gap:8px}.dd-theme .lb-header__cart{font-size:.85rem}.dd-pagination{flex-wrap:wrap}.dd-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-addresses,.lb-customer-order-detail){width:calc(100% - 32px)}}\n@media(max-width:47.99em){.dd-theme .lb-mobile-nav:not([data-open=\"true\"]) .lb-header__nav{visibility:hidden}.dd-theme .lb-mobile-nav[data-open=\"true\"] .lb-header__nav{visibility:visible}}\n@media(prefers-reduced-motion:reduce){.dd-theme *{scroll-behavior:auto!important;animation:none!important;transition:none!important}}\n</style>\n</head>\n<body class=\"lb-theme lb-theme--letbuyy-core\">\n  <a class=\"lb-skip-link\" href=\"#MainContent\">Skip to content</a>\n  <header class=\"lb-layout__header\">\n    <a class=\"lb-layout__brand\" href=\"{{ routes.root_url }}\">{{ shop.name }}</a>\n    <nav class=\"lb-layout__nav\" aria-label=\"Primary\">\n      {% if linklists.main_menu.links.size > 0 %}{% for link in linklists.main_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}\n      {% else %}<a href=\"{{ routes.all_products_collection_url }}\">Products</a><a href=\"{{ routes.search_url }}\">Search</a><a href=\"{{ routes.cart_url }}\">Cart</a><a href=\"{{ routes.account_url }}\">Account</a>{% endif %}\n    </nav>\n  </header>\n  <main id=\"MainContent\">\n    {{ content_for_layout | raw }}\n  </main>\n  <footer class=\"lb-layout__footer\">\n    {% if linklists.footer.links.size > 0 %}<nav class=\"lb-layout__nav\" aria-label=\"Footer\">{% for link in linklists.footer.links %}<a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"locales":{"en":{"general":{"cart":"Cart"}}},"package":{"author_name":"LetBuyy","compatibility_range":">=2026-06-liquid-sections","currency":"INR","description":"Routine-led personal care with named shades, supplied ingredients and directions.","name":"Dewdrop","price":0,"pricing_type":"free","release_status":"published","site_types":["store"],"slug":"letbuyy-aura","status":"active","version":"2.1.0","version_number":5},"renderer":{"assets":{},"engine":"liquid","liquid_ready":true,"renderer_version":"0.1.0"},"schema_version":"2026-06-liquid-sections","sections":{"404-page":{"path":"sections/404-page.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"404 Not Found","presets":[{"blocks":[],