\",\n          \"id\": \"body\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Link label\",\n          \"default\": \"\",\n          \"id\": \"linkLabel\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link destination\",\n          \"default\": \"\",\n          \"id\": \"linkUrl\"\n        }\n      ]\n    },\n    {\n      \"type\": \"badge\",\n      \"name\": \"Badge\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"default\": \"New\",\n          \"id\": \"label\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Merchant service information\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"video-hero":{"path":"sections/video-hero.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Video Hero","presets":[{"blocks":[],"name":"Video Hero","settings":{}}],"settings":[{"default":"See the fit in motion","id":"heading","label":"Heading","type":"text"},{"default":"A quick look at how each drop moves, from the box to your feet.","id":"subheading","label":"Subheading","type":"textarea"},{"id":"videoUrl","info":"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.","label":"Video embed URL","type":"url"}],"tag":"section"},"source":"<div class=\"dd-theme\"><section class=\"lb-video-hero\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-video-hero__copy\">\n    <h2 class=\"lb-video-hero__heading\">{{ section.settings.heading }}</h2>\n    {% if section.settings.subheading %}<p class=\"lb-video-hero__subheading\">{{ section.settings.subheading }}</p>{% endif 