s":[{"default":"Made for daily buyers","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"}],"tag":"section"},"source":"<div class=\"dd-theme\"><section class=\"lb-first-party-spotlight\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.subheading }}</p>\n  <h2>{{ section.settings.heading }}</h2>\n  <div class=\"lb-first-party-spotlight__blocks\">\n    {% for block in section.blocks %}\n      {{ block.content | raw }}\n    {% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Spotlight\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Made for daily buyers\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subheading\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"badge\",\n      \"name\": \"Badge\",\n      \"settings\": []\n    },\n    {\n      \"type\": \"@app\",\n      \"name\": \"App block\",\n      \"settings\": []\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Spotlight\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"testimonials":{"path":"sections/testimonials.liquid","schema":{"blocks":[{"name":"Testimonial","settings":[{"id":"quote","label":"Quote","type":"textarea"},{"id":"author","label":"Author","type":"text"}],"type":"testimonial"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Testimonials","presets":[{"blocks":[],"name":"Testimonials","settings":{}}],"settings":[{"default":"What customers say","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"dd-theme\"><section class=\"lb-testimonials\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<div class=\"lb-testimonials__items\">{% for block in section.blocks %}<blockquote><p>{{ block.settings.quote }}</p><cite>{{ block.settings.author }}</cite>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</blockquote>{% endfor %}</div>\n  {% else %}<p class=\"lb-testimonials__empty\">Add customer reviews to build trust.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Testimonials\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"What customers say\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"testimonial\",\n      \"name\": \"Testimonial\",\n      \"settings\": [\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Quote\",\n          \"id\": \"quote\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Author\",\n          \"id\": \"author\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Testimonials\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"trust-badges":{"path":"sections/trust-badges.liquid","schema":{"blocks":[{"limit":6,"name":"Service information","settings":[{"default":"","id":"heading","label":"Heading","type":"text"},{"default":"","id":"body","label":"Merchant supplied information","type":"textarea"},{"default":"","id":"linkLabel","label":"Link label","type":"text"},{"default":"","id":"linkUrl","label":"Link destination","type":"url"}],"type":"service"},{"name":"Badge","settings":[{"default":"New","id":"label","label":"Label","type":"text"}],"type":"badge"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Merchant service information","presets":[{"blocks":[],"name":"Merchant service information","settings":{}}],"settings":[],"tag":"section"},"source":"<section class=\"dd-theme\" data-section-id=\"{{ section.id }}\">{% if section.blocks.size > 0 %}<div class=\"dd-wrap dd-services\">{% for block in section.blocks %}{% if block.type == 'badge' %}{{ block.content | raw }}{% else %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.heading }}</h3><p>{{ block.settings.body }}</p>{% if block.settings.linkLabel != blank and block.settings.linkUrl != blank %}<a class=\"dd-link\" href=\"{{ block.settings.linkUrl | store_url }}\">{{ block.settings.linkLabel }}</a>{% endif %}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endif %}{% endfor %}</div>{% endif %}</section>\n{% schema %}\n{\n  \"name\": \"Merchant service information\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [\n    {\n      \"type\": \"service\",\n      \"name\": \"Service information\",\n      \"limit\": 6,\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Heading\",\n          \"default\": \"\",\n          \"id\": \"heading\"\n        },\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Merchant supplied information\",\n          \"default\": \"\",\n          \"id\": \"body\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Link label\",\n          \"default\": \"\",\n          \"id\": \"linkLabel\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link destination\",\n          \"default\": \"\",\n          \"id\": \"linkUrl\"\n        }\n      ]\n    },\n    {\n      \"type\": \"badge\",\n      \"name\": \"Badge\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"default\": \"New\",\n          \"id\": \"label\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Merchant service information\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"video-hero":{"path":"sections/video-hero.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Video Hero","presets":[{"blocks":[],"name":"Video Hero","settings":{}}],"settings":[{"default":"See the fit in motion","id":"heading","label":"Heading","type":"text"},{"default":"A quick look at how each drop moves, from the box to your feet.","id":"subheading","label":"Subheading","type":"textarea"},{"id":"videoUrl","info":"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.","label":"Video embed URL","type":"url"}],"tag":"section"},"source":"<div class=\"dd-theme\"><section class=\"lb-video-hero\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-video-hero__copy\">\n    <h2 class=\"lb-video-hero__heading\">{{ section.settings.heading }}</h2>\n    {% if section.settings.subheading %}<p class=\"lb-video-hero__subheading\">{{ section.settings.subheading }}</p>{% endif %}\n  </div>\n  {% if section.settings.videoUrl != blank %}<div class=\"lb-video-hero__embed\"><iframe src=\"{{ section.settings.videoUrl | video_url }}\" title=\"{{ section.settings.heading }}\" loading=\"lazy\" sandbox=\"allow-scripts allow-same-origin allow-presentation\" allowfullscreen></iframe></div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Video Hero\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\":