ion.settings.heading }}</h2></div></a><div class=\"pf-bento-side\"><a class=\"pf-bento-small\" href=\"{{ section.settings.firstLink | store_url }}\">{% if section.settings.firstImage != blank %}<img src=\"{{ section.settings.firstImage | image_url }}\" alt=\"{{ section.settings.firstImageAlt }}\" loading=\"lazy\">{% endif %}<div><h3>{{ section.settings.firstTitle }}</h3><span>Explore activities →</span></div></a><a class=\"pf-bento-small\" href=\"{{ section.settings.secondLink | store_url }}\">{% if section.settings.secondImage != blank %}<img src=\"{{ section.settings.secondImage | image_url }}\" alt=\"{{ section.settings.secondImageAlt }}\" loading=\"lazy\">{% endif %}<div><h3>{{ section.settings.secondTitle }}</h3><span>Explore activities →</span></div></a></div></section>\n</div>\n{% schema %}\n{\n  \"name\": \"Activity bento\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Main heading\",\n      \"default\": \"A little pattern. A big possibility.\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Main eyebrow\",\n      \"default\": \"MAKE · ARRANGE · START AGAIN\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"image\",\n      \"label\": \"Main activity image\",\n      \"id\": \"image\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Main image description\",\n      \"default\": \"\",\n      \"id\": \"imageAlt\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Main destination\",\n      \"default\": \"/products\",\n      \"id\": \"link\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"First interest heading\",\n      \"default\": \"Art & making\",\n      \"id\": \"firstTitle\"\n    },\n    {\n      \"type\": \"image\",\n      \"label\": \"First interest image\",\n      \"id\": \"firstImage\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"First image description\",\n      \"default\": \"\",\n      \"id\": \"firstImageAlt\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"First interest destination\",\n      \"default\": \"/products\",\n      \"id\": \"firstLink\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Second interest heading\",\n      \"default\": \"Build a little world\",\n      \"id\": \"secondTitle\"\n    },\n    {\n      \"type\": \"image\",\n      \"label\": \"Second interest image\",\n      \"id\": \"secondImage\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Second image description\",\n      \"default\": \"\",\n      \"id\": \"secondImageAlt\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Second interest destination\",\n      \"default\": \"/products\",\n      \"id\": \"secondLink\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Activity bento\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"testimonials":{"path":"sections/testimonials.liquid","schema":{"blocks":[{"name":"Testimonial","settings":[{"id":"quote","label":"Quote","type":"textarea"},{"id":"author","label":"Author","type":"text"}],"type":"testimonial"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Testimonials","presets":[{"blocks":[],"name":"Testimonials","settings":{}}],"settings":[{"default":"What customers say","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"pf-theme\"><section class=\"lb-testimonials\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<div class=\"lb-testimonials__items\">{% for block in section.blocks %}<blockquote {{ block.editor_attributes | raw }}><p>{{ block.settings.quote }}</p><cite>{{ block.settings.author }}</cite>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</blockquote>{% endfor %}</div>\n  {% else %}<p class=\"lb-testimonials__empty\">Add customer reviews to build trust.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Testimonials\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"What customers say\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"testimonial\",\n      \"name\": \"Testimonial\",\n      \"settings\": [\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Quote\",\n          \"id\": \"quote\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Author\",\n          \"id\": \"author\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Testimonials\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"trust-badges":{"path":"sections/trust-badges.liquid","schema":{"blocks":[{"name":"Badge","settings":[{"default":"New","id":"label","label":"Label","type":"text"}],"type":"badge"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Choosing information","presets":[{"blocks":[],"name":"Choosing information","settings":{}}],"settings":[{"default":"","id":"contentsText","label":"Contents information","type":"text"},{"default":"","id":"materialsText","label":"Materials information","type":"text"},{"default":"","id":"helpText","label":"Merchant help information","type":"text"}],"tag":"section"},"source":"<div class=\"pf-theme\"><section class=\"pf-wrap pf-section\" data-section-id=\"{{ section.id }}\"><div clas