=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-playfield=\"2\">\n.pf-theme{--pf-muted:#655a43;--pf-line:#c9bfa9;--pf-essential:#7a6a4d;--pf-sage:#dde7d7;--pf-coral:#f1d4c5;--pf-focus:#005fcc;--font-display:var(--font-heading,Inter,Arial,sans-serif);--font-body:var(--font-main,Inter,Arial,sans-serif);--footer-bg:var(--surface);--footer-text:var(--foreground);--footer-text-muted:var(--pf-muted);background:var(--background,#fff9ee);color:var(--foreground,#29251d);font:1rem/1.55 var(--font-body)}\n.pf-theme *{box-sizing:border-box}.pf-theme :where(h1,h2,h3){font-family:var(--font-display);font-weight:700;letter-spacing:-.045em;line-height:1.12;overflow-wrap:anywhere}.pf-theme h1{font-size:clamp(2.2rem,4.6vw,4rem)}.pf-theme h2{font-size:clamp(1.75rem,2.7vw,2.3rem)}.pf-theme h3{font-size:1.4rem}.pf-theme :where(p,li,dd){overflow-wrap:anywhere}.pf-theme p{color:var(--pf-muted)}.pf-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--pf-focus);outline-offset:4px}.pf-theme :where(button,a){touch-action:manipulation}.pf-theme img{max-width:100%;height:auto}.pf-theme :where(input,select,button){font:inherit}.pf-wrap{width:min(1200px,calc(100% - 96px));margin-inline:auto}.pf-section{padding-block:54px}.pf-eyebrow{font-size:.75rem;font-weight:700;letter-spacing:.12em;color:var(--primary,#1d5c54)!important}.pf-note{font-size:.8rem;line-height:1.5}.pf-button{display:inline-flex;min-height:50px;align-items:center;justify-content:center;padding:13px 22px;background:var(--primary,#1d5c54);color:#fff!important;border:1px solid var(--primary,#1d5c54);border-radius:9px;text-decoration:none;font-weight:600;line-height:1.4}.pf-link{display:inline-flex;align-items:center;min-height:44px;color:var(--primary,#1d5c54);background:transparent;border:0;text-decoration:underline;text-underline-offset:5px;padding:4px 0;font:inherit;cursor:pointer}.pf-heading{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:28px}.pf-heading h2{margin:0}.pf-opening{display:grid;grid-template-columns:1.1fr 1fr;gap:72px;align-items:center;padding-block:48px 36px}.pf-opening h1{margin:12px 0 20px}.pf-finder{padding:28px;background:var(--surface,#f3e6c8);bo