 img{width:100%;aspect-ratio:1.3;object-fit:contain;border-radius:16px;background:var(--surface)}.pf-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;border-block:1px solid var(--pf-line)}\n.pf-theme .lb-announcement-bar{background:var(--primary,#1d5c54);color:#fff;text-align:center;padding:8px 20px;font-size:.8rem}.pf-theme .lb-announcement-bar__inner{justify-content:center}.pf-theme .lb-header{background:var(--background);border-bottom:1px solid var(--pf-line)}.pf-theme .lb-header__inner{width:min(1200px,calc(100% - 96px));margin:auto;padding:15px 0;min-height:84px;flex-wrap:wrap;gap:20px}.pf-theme .lb-header__brand{font-family:var(--font-display);font-size:1.9rem;font-weight:800;letter-spacing:-.07em}.pf-theme .lb-header__nav-links{gap:24px}.pf-theme .lb-header__nav-links>a{font-size:.85rem}.pf-theme .lb-footer{background:var(--surface);padding:48px max(24px,calc((100vw - 1200px)/2));border-top:1px solid var(--pf-line)}\n.pf-theme .lb-product-detail{width:min(1200px,calc(100% - 96px));margin:auto;padding-block:32px 60px}.pf-theme .lb-product-detail__layout{display:grid;grid-template-columns:1.15fr 1fr;gap:64px}.pf-theme .lb-product-detail__gallery-image{aspect-ratio:1;object-fit:contain;width:100%;border-radius:16px;background:var(--surface)}.pf-theme .lb-product-detail__gallery{min-width:0}.pf-theme .lb-product-detail__title{font-size:clamp(2rem,3.5vw,3rem)}.pf-theme .lb-product-detail__info{min-width:0}.pf-theme .lb-product-detail__cta{min-height:50px;border-radius:9px}.pf-theme .lb-product-detail__cta--primary{background:var(--primary);color:#fff}.pf-theme .lb-product-detail__variant-options{display:flex;flex-wrap:wrap;gap:8px}.pf-theme [data-lb-variant-option]{min-height:44px;border-radius:8px;border:1px solid var(--pf-essential);background:var(--background);padding:10px 14px}.pf-theme [data-lb-variant-option][aria-pressed=\"true\"]{background:var(--primary);color:#fff}.pf-theme [data-lb-variant-option]:disabled{opacity:.55}.pf-pro