"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n    {% for field in collection.discovery_query_fields %}{% unless field.key == 'page' or field.key == 'search' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}</form>\n  </lb-search>\n  {% if search.terms %}<p class=\"lb-search__terms\">Results for \"{{ search.terms }}\"</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Search\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Placeholder\",\n      \"default\": \"Search products\",\n      \"id\": \"placeholder\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Search\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"services-grid":{"path":"sections/services-grid.liquid","schema":{"blocks":[{"name":"Service","settings":[{"id":"title","label":"Title","type":"text"},{"id":"description","label":"Description","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"service"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Services Grid","presets":[{"blocks":[],"name":"Services Grid","settings":{}}],"settings":[{"default":"Services","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"pf-theme\"><section class=\"lb-services-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.setti