oundColor":"#FFFFFF","bodyFontFamily":"Source Sans Pro","borderRadius":6,"headingFontFamily":"Libre Baskerville","primaryColor":"#3E2723","secondaryColor":"#5D3B2E","surfaceColor":"#FFF8F0","textColor":"#2C1B12"},"Dawn":{"accentColor":"#C0832B","backgroundColor":"#FFFFFF","bodyFontFamily":"Source Sans Pro","borderRadius":4,"headingFontFamily":"Libre Baskerville","primaryColor":"#3B4F6B","secondaryColor":"#2C3E50","surfaceColor":"#FDF6EC","textColor":"#2C2C2C"},"Forge":{"accentColor":"#00B4D8","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":8,"headingFontFamily":"Inter","primaryColor":"#1E3A5F","secondaryColor":"#1E40AF","surfaceColor":"#F0F4F8","textColor":"#1A202C"},"Nova":{"accentColor":"#F59E0B","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#8B5CF6","secondaryColor":"#6D28D9","surfaceColor":"#F8FAFC","textColor":"#1A1A2E"},"Refresh":{"accentColor":"#F4A261","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#2D6A4F","secondaryColor":"#1B4332","surfaceColor":"#F8FFF4","textColor":"#1B2521"},"Ride":{"accentColor":"#FFD100","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":6,"headingFontFamily":"Inter","primaryColor":"#FF4D00","secondaryColor":"#1C1C1C","surfaceColor":"#F5F5F5","textColor":"#111111"},"Summit":{"accentColor":"#A4E500","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":12,"headingFontFamily":"Inter","primaryColor":"#00B3B3","secondaryColor":"#008080","surfaceColor":"#F9FAFB","textColor":"#1A1A2E"},"Threadline":{"accentColor":"#005FCC","backgroundColor":"#FAF7F2","bodyFontFamily":"Inter","borderRadius":4,"headingFontFamily":"Playfair Display","primaryColor":"#713F35","secondaryColor":"#65574C","surfaceColor":"#EFE7DC","textColor":"#241E1A"}}},"settings_schema":{"schema_version":"2026-05-json-contract","settings":{"appearance":{"description":"Layout tokens shared by every section.","fields":{"borderRadius":{"default":12,"label":"Corner radius","type":"number"}},"label":"Appearance"},"colors":{"description":"LetBuyy Core storefront color tokens.","fields":{"accentColor":{"default":"#005FCC","label":"Accent color","type":"color"},"backgroundColor":{"default":"#FFF9EE","label":"Background color","type":"color"},"primaryColor":{"default":"#1D5C54","label":"Primary color","type":"color"},"secondaryColor":{"default":"#DDE7D7","label":"Secondary color","type":"color"},"surfaceColor":{"default":"#F3E6C8","label":"Surface color","type":"color"},"textColor":{"default":"#29251D","label":"Text color","type":"color"}},"label":"Colors"},"seo":{"description":"Metadata rendered into <head> by the theme layout.","fields":{"faviconUrl":{"default":"","info":"Rendered as <link rel=\"icon\">. Left empty until the merchant uploads one.","label":"Favicon URL","type":"url"},"metaDescription":{"default":"","info":"Falls back to the shop description. Truncated to 160 characters on output.","label":"Meta description","maxLength":160,"type":"textarea"},"socialImageUrl":{"default":"","info":"Used for og:image and twitter:image. Left empty until the merchant uploads one.","label":"Social share image URL","type":"url"}},"label":"SEO and social"},"typography":{"description":"First-party type settings mirrored from the JSON-contract LetBuyy Core theme.","fields":{"bodyFontFamily":{"default":"Inter","label":"Body font","type":"text"},"headingFontFamily":{"default":"Inter","label":"Heading font","type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-playfield=\"2\">\n.pf-theme{--pf-muted:#655a43;--pf-line:#c9bfa9;--pf-essential:#7a6a4d;--pf-sage:#dde7d7;--pf-coral:#f1d4c5;--pf-focus:#005fcc;--font-display:var(--font-heading,Inter,Arial,sans-serif);--font-body:var(--font-main,Inter,Arial,sans-serif);--footer-bg:var(--surface);--footer-text:var(--foreground);--footer-text-muted:var(--pf-muted);background:var(--background,#fff9ee);color:var(--foreground,#29251d);font:1rem/1.55 var(--font-body)}\n.pf-theme *{box-sizing:border-box}.pf-theme :where(h1,h2,h3){font-family:var(--font-display);font-weight:700;letter-spacing:-.045em;line-height:1.12;overflow-wrap:anywhere}.pf-theme h1{font-size:clamp(2.2rem,4.6vw,4rem)}.pf-theme h2{font-size:clamp(1.75rem,2.7vw,2.3rem)}.pf-theme h3{font-size:1.4rem}.pf-theme :where(p,li,dd){overflow-wrap:anywhere}.pf-theme p{color:var(--pf-muted)}.pf-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--pf-focus);outline-offset:4px}.pf-theme :where(button,a){touch-action:manipulation}.pf-theme img{max-width:100%;height:auto}.pf-theme :where(input,select,button){font:inherit}.pf-wrap{width:min(1200px,calc(100% - 96px));margin-inline:auto}.pf-section{padding-block:54px}.pf-eyebrow{font-size:.75rem;font-weight:700;letter-spacing:.12em;color:var(--primary,#1d5c54)!important}.pf-note{font-size:.8rem;line-height:1.5}.pf-button{display:inline-flex;min-height:50px;align-items:center;justify-content:center;padding:13px 22px;background:var(--primary,#1d5c54);color:#fff!important;border:1px solid var(--primary,#1d5c54);border-radius:9px;text-decoration:none;font-weight:600;line-height:1.4}.pf-link{display:inline-flex;align-items:center;min-height:44px;color:var(--primary,#1d5c54);background:transparent;border:0;text-decoration:underline;text-underline-offset:5px;padding:4px 0;font:inherit;cursor:pointer}.pf-heading{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:28px}.pf-heading h2{margin:0}.pf-opening{display:grid;grid-template-columns:1.1fr 1fr;gap:72px;align-items:center;padding-block:48px 36px}.pf-opening h1{margin:12px 0 20px}.pf-finder{padding:28px;background:var(--surface,#f3e6c8);border-radius:16px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pf-finder label{font-weight:600;font-size:.85rem}.pf-theme :where(select,input[type=\"search\"]){display:block;width:100%;min-height:48px;margin-top:10px;border:1px solid var(--pf-essential);border-radius:7px;padding:10px;background:var(--background,#fff9ee);color:inherit}.pf-finder>.pf-button,.pf-finder>.pf-note{grid-column:1/-1;margin:0}.pf-bento{display:grid;grid-template-columns:1.65fr 1fr;gap:18px}.pf-bento a{text-decoration:none;color:inherit;min-width:0;border-radius:18px;overflow:hidden}.pf-bento-main{display:flex;flex-direction:column;background:var(--surface,#f3e6c8)}.pf-bento-main img{width:100%;aspect-ratio:1.8;object-fit:cover;display:block}.pf-bento-caption{padding:24px 28px}.pf-bento-caption h2{margin:8px 0}.pf-bento-side{display:grid;grid-template-rows:repeat(2,1fr);gap:18px}.pf-bento-small{display:grid;grid-template-columns:1fr 1fr;align-items:center;padding:12px;gap:12px;background:var(--pf-coral)}.pf-bento-small:last-child{background:var(--pf-sage)}.pf-bento-small img{width:100%;aspect-ratio:1;object-fit:contain;border-radius:10px}.pf-bento-small h3{margin:0 0 12px}.pf-bento-small span{font-size:.85rem}.pf-no-image{min-height:180px;display:grid;place-items:center;padding:24px;color:var(--pf-muted);background:var(--surface,#f3e6c8)}.pf-ages{display:grid;grid-template