iscover our latest products.","id":"text","label":"Message","type":"text"},{"default":"Shop now","id":"linkLabel","label":"Link label","type":"text"},{"default":"/products","id":"linkHref","label":"Link URL","type":"url"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-announcement-bar\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-announcement-bar__inner\">\n    <span>{{ section.settings.text }}</span>\n    {% if section.settings.linkLabel %}<a href=\"{{ section.settings.linkHref | store_url }}\">{{ section.settings.linkLabel }}</a>{% endif %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Announcement Bar\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Message\",\n      \"default\": \"Discover our latest products.\",\n      \"id\": \"text\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Link label\",\n      \"default\": \"Shop now\",\n      \"id\": \"linkLabel\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Link URL\",\n      \"default\": \"/products\",\n      \"id\": \"linkHref\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Announcement Bar\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"header\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"app-block-slot":{"path":"sections/app-block-slot.liquid","schema":{"blocks":[{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"App Block Slot","presets":[{"blocks":[],"name":"App Block Slot","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":"storefront.home.after-hero","id":"slot","label":"Slot","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\">