#1A1A2E"},"Refresh":{"accentColor":"#F4A261","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#2D6A4F","secondaryColor":"#1B4332","surfaceColor":"#F8FFF4","textColor":"#1B2521"},"Ride":{"accentColor":"#FFD100","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":6,"headingFontFamily":"Inter","primaryColor":"#FF4D00","secondaryColor":"#1C1C1C","surfaceColor":"#F5F5F5","textColor":"#111111"},"Summit":{"accentColor":"#A4E500","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":12,"headingFontFamily":"Inter","primaryColor":"#00B3B3","secondaryColor":"#008080","surfaceColor":"#F9FAFB","textColor":"#1A1A2E"},"Threadline":{"accentColor":"#005FCC","backgroundColor":"#FAF7F2","bodyFontFamily":"Inter","borderRadius":4,"headingFontFamily":"Playfair Display","primaryColor":"#713F35","secondaryColor":"#65574C","surfaceColor":"#EFE7DC","textColor":"#241E1A"}}},"settings_schema":{"schema_version":"2026-05-json-contract","settings":{"appearance":{"description":"Layout tokens shared by every section.","fields":{"borderRadius":{"default":12,"label":"Corner radius","type":"number"}},"label":"Appearance"},"colors":{"description":"LetBuyy Core storefront color tokens.","fields":{"accentColor":{"default":"#F59E0B","label":"Accent color","type":"color"},"backgroundColor":{"default":"#FFFFFF","label":"Background color","type":"color"},"primaryColor":{"default":"#8B5CF6","label":"Primary color","type":"color"},"secondaryColor":{"default":"#3B82F6","label":"Secondary color","type":"color"},"surfaceColor":{"default":"#F8FAFC","label":"Surface color","type":"color"},"textColor":{"default":"#1F2937","label":"Text color","type":"color"}},"label":"Colors"},"seo":{"description":"Metadata rendered into <head> by the theme layout.","fields":{"faviconUrl":{"default":"","info":"Rendered as <link rel=\"icon\">. Left empty until the merchant uploads one.","label":"Favicon URL","type":"url"},"metaDescription":{"default":"","info":"Falls back to the shop description. Truncated to 160 characters on output.","label":"Meta description","maxLength":160,"type":"textarea"},"socialImageUrl":{"default":"","info":"Used for og:image and twitter:image. Left empty until the merchant uploads one.","label":"Social share image URL","type":"url"}},"label":"SEO and social"},"typography":{"description":"First-party type settings mirrored from the JSON-contract LetBuyy Core theme.","fields":{"bodyFontFamily":{"default":"Inter","label":"Body font","type":"text"},"headingFontFamily":{"default":"Inter","label":"Heading font","type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-marginalia=\"2\">\n.mg-theme{--mg-muted:var(--mg-muted-color,#6b5c45);--mg-border:var(--mg-border-color,#b9ab90);--mg-control:var(--mg-control-color,#867354);--mg-focus:var(--mg-focus-color,#005fcc);--mg-label:var(--mg-action-label,#fff);--footer-bg:var(--surface);--footer-text:var(--foreground);--footer-text-muted:var(--mg-muted);font:17px/1.55 var(--font-body,'Source Sans 3',Arial,sans-serif);background:var(--background,#faf6ea);color:var(--foreground,#30291e);overflow-wrap:anywhere}\n.mg-theme *{box-sizing:border-box;min-width:0}.mg-theme img{max-width:100%;display:block}.mg-theme a{color:inherit;text-underline-offset:5px}.mg-theme :where(h1,h2,h3){font-family:var(--font-display,'Libre Baskerville',Georgia,serif);font-weight:400;line-height:1.3;letter-spacing:-.025em;overflow-wrap:anywhere}.mg-theme h1{font-size:clamp(2rem,3.6vw,3.25rem)}.mg-theme h2{font-size:clamp(1.6rem,2.4vw,2.1rem)}.mg-theme h3{font-size:1.35rem}.mg-theme p{color:var(--mg-muted)}.mg-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--mg-focus);outline-offset:4px}.mg-theme :where(button,input,select){font:inherit}.mg-theme :where(button,a,input,select,summary){overflow-wrap:anywhere}.mg-theme :where(input,select){max-width:100%;min-height:44px;color:var(--foreground);background:var(--background);border:1px solid var(--mg-control);border-radius:3px;padding:10px}.mg-theme :where(button,summary){cursor:pointer}.mg-wrap{width:min(1240px,calc(100% - 112px));margin-inline:auto}.mg-section{padding-block:48px}.mg-eyebrow{display:block;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mg-muted);margin-bottom:12px}.mg-intro{font-size:1.1rem;max-width:42ch}.mg-button{display:inline-flex;align-items:center;justify-content:center;gap:12px;background:var(--primary,#744a26);border:1px solid var(--primary,#744a26);border-radius:3px;color:var(--mg-label)!important;padding:12px 22px;min-height:48px;text-decoration:none;font-weight:600}.mg-link{display:inline-flex;align-items:center;gap:10px;min-height:44px;color:var(--primary,#744a26)!important;text-decoration:underline}.mg-heading{display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;align-items:end;margin-bottom:22px}.mg-heading h2{margin:0}.mg-price{font-variant-numeric:tabular-nums;font-size:1.2rem;overflow-wrap:anywhere}.mg-missing{display:grid;place-items:center;min-height:140px;padding:16px;background:var(--surface);color:var(--mg-muted);font-size:.9rem;text-align:center}.mg-empty{padding:32px 0;border-block:1px solid var(--mg-border)}\n.mg-theme .lb-header{background:var(--background);border-bottom:1px solid var(--mg-border);padding:18px 0}.mg-theme .lb-header__inner{width:min(1240px,calc(100% - 112px));max-width:none;padding:0;margin:auto;gap:30px;flex-wrap:wrap}.mg-theme .lb-header__brand{font:1.8rem/1.2 var(--font-display,Georgia,serif);letter-spacing:-.04em;overflow-wrap:anywhere}.mg-theme .lb-header__nav-links{gap:26px}.mg-theme .lb-header__nav-links>a{font-size:.9rem;min-width:44px;min-height:44px;display:inline-flex;align-items:center}.mg-theme .lb-announcement-bar{background:var(--surface);color:var(--foreground);font-size:.8rem;text-align:center}.mg-theme .lb-footer{background:var(--surface);border-top:1px solid var(--mg-border);padding:48px max(24px,calc((100vw - 1240px)/2))}.mg-theme .lb-footer :where(h2,h3){font-size:1.1rem}\n.mg-opening{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;padding-block:46px}.mg-opening h1{margin:0 0 18px}.mg-search{display:flex;align-items:stretch;border:1px solid var(--mg-control);border-radius:3px;background:var(--surface);padding:5px}.mg-search input{width:100%;border:0;background:transparent}.mg-search button{flex-shrink:0;border:0;background:transparent;padding:10px 16px;min-height:44px;color:var(--primary);font-weight:600}.mg-find label{display:block;margin-bottom:12px;font-weight:600}.mg-find p{font-size:.9rem}\n.mg-index-feature{display:grid;grid-template-columns:240px 1fr;gap:36px;border-block:1px solid var(--mg-border);padding-block:32px}.mg-subjects{border-right:1px solid var(--mg-border);padding-right:28px}.mg-subjects h2{font-size:1.5rem;margin:0 0 15px}.mg-subjects a{display:flex;align-items:center;justify-content:space-between;gap:15px;min-height:48px;border-bottom:1px solid var(--mg-border);text-decoration:none}.mg-feature{padding:32px;background:var(--surface);display:grid;grid-template-columns:minmax(100px,220px) 1fr;gap:36px;align-items:center}.mg-feature>.mg-cover img{width:220px;max-height:330px;object-fit:contain;margin:auto}.mg-feature h2{margin:0 0 12px}.mg-feature p{margin-block:10px}.mg-feature .mg-price{display:block;margin-top:20px}.mg-feature-empty{padding:30px;align-self:center;color:var(--mg-muted)}\n.mg-shelf{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:36px}.mg-shelf[data-columns=\"2\"]{grid-template-columns:repeat(2,minmax(0,1fr))}.mg-shelf[data-columns=\"4\"]{grid-template-columns:repeat(4,minmax(0,1fr))}.mg-shelf .mg-book-row{display:block;border:0;padding:0}.mg-shelf .mg-cover{display:flex;align-items:center;justify-content:center;background:var(--surface);padding:22px;margin-bottom:18px;min-height:240px}.mg-shelf .mg-cover img{height:250px;max-width:100%;width:auto;object-fit:contain}.mg-shelf .mg-bibliography h3{font-size:1.3rem}.mg-shelf .mg-row-end{text-align:left;display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between}.mg-shelf .mg-row-end .mg-link{margin:0}.mg-shelf [data-product-kind=\"stationery\"] .mg-cover img{aspect-ratio:1;object-fit:contain}\n.mg-book-row{display:grid;grid-template-columns:104px minmax(0,1fr) 150px;gap:28px;padding-block:28px;border-bottom:1px solid var(--mg-border);align-items:start}.mg-cover{text-decoration:none}.mg-cover img{width:104px;height:auto;aspect-ratio:2/3;object-fit:contain}.mg-bibliography h3{margin:0 0 8px}.mg-bibliography h3 a{text-decoration:none}.mg-bibliography p{margin:6px 0;font-size:.95rem}.mg-bibliography .mg-author{font-size:1rem}.mg-row-end{text-align:right}.mg-row-end .mg-link{font-size:.85rem;margin-top:24px}.mg-availability{color:var(--foreground)!important;font-weight:600}.mg-book-row[data-product-kind=\"stationery\"] .mg-cover img{aspect-ratio:1}.mg-discovery{padding-block:24px 0}.mg-filters,.mg-filter-fields{display:flex;align-items:end;gap:16px;flex-wrap:wrap}.mg-filters label{display:grid;gap:6px;font-size:.9rem;max-width:100%}.mg-filter-details{flex-basis:100%;border-block:1px solid var(--mg-border);padding:12px 0}.mg-filter-details summary{min-height:44px;align-content:center}.mg-filter-fields{padding-bottom:14px}.mg-filter-fields input{max-width:220px}.mg-pagination{display:flex;flex-wrap:wrap;gap:24px;justify-content:center;align-items:center;margin-top:30px}.mg-editorial{display:grid;grid-template-columns:1fr 1fr;gap:56px;background:var(--surface);padding:36px;align-items:center}.mg-editorial>img{width:100%;max-height:430px;object-fit:contain}.mg-editorial-empty{grid-template-columns:1fr}.mg-editorial p{white-space:pre-line}.mg-editorial .mg-link{margin-top:14px}\n.mg-theme .lb-product-detail{width:min(1240px,calc(100% - 112px));margin:auto;padding-block:24px 60px}.mg-theme .lb-product-detail__breadcrumb{flex-wrap:wrap;font-size:.85rem}.mg-theme .lb-product-detail__layout{display:grid;grid-template-columns:minmax(220px,.8fr) minmax(0,1.2fr);gap:70px;margin-top:24px}.mg-theme .lb-product-detail__gallery{max-width:380px;width:100%;margin-inline:auto}.mg-theme .lb-product-detail__gallery-main{background:var(--surface);padding:24px}.mg-theme .lb-product-detail__gallery-image{width:100%;max-height:560px;height:auto;aspect-ratio:2/3;object-fit:contain}.mg-theme .lb-product-detail[data-product-kind=\"stationery\"] .lb-product-detail__gallery-image{aspect-ratio:1}.mg-theme .lb-product-detail__gallery-thumb img{object-fit:contain}.mg-theme .lb-product-detail__info h1{font-size:clamp(1.9rem,3vw,2.8rem);margin-block:0 18px}.mg-theme .lb-product-detail__price-current{font-size:1.5rem}.mg-theme .lb-product-detail__variant-values{gap:10px;flex-wrap:wrap}.mg-theme .lb-product-detail__variant-values button{min-width:44px;min-height:44px;border:1px solid var(--mg-control);border-radius:3px;background:var(--background);color:var(--foreground);padding:10px 14px;white-space:normal}.mg-theme .lb-product-detail__variant-values button[aria-pressed=\"true\"]{background:var(--primary);color:var(--mg-label)}.mg-theme .lb-product-detail__cta{min-height:48px;border-radius:3px}.mg-theme .lb-product-detail__cta--primary{background:var(--primary);color:var(--mg-label)}.mg-theme .lb-product-detail__quantity{width:64px}.mg-theme .lb-product-detail__purchase lb-add-to-cart{display:flex;flex-wrap:wrap;gap:12px}.mg-theme [data-lb-add-to-cart-status]{flex-basis:100%}.mg-theme .lb-product-detail__accordion{border-color:var(--mg-border)}.mg-facts{border-top:1px solid var(--mg-border);margin-top:22px;padding-top:20px}.mg-facts h2{font-size:1.4rem}.mg-facts dl{margin:0}.mg-facts dl>div{display:grid;grid-template-columns:145px 1fr;gap:20px;border-bottom:1px solid var(--mg-border);padding:11px 0}.mg-facts dt{color:var(--mg-muted)}.mg-facts dd{margin:0;overflow-wrap:anywhere}.mg-editions{display:grid;gap:12px}.mg-edition{border:1px solid var(--mg-border);padding:16px}.mg-edition h3{font:600 1rem/1.5 var(--font-body,Arial,sans-serif);letter-spacing:0;margin:0 0 8px}.mg-reading{max-width:68ch;margin:56px auto;padding:32px 0;border-top:1px solid var(--mg-border)}.mg-reading h2{font-size:1.7rem}.mg-reading blockquote{font:1.12rem/1.9 var(--font-display,Georgia,serif);white-space:pre-line;margin:24px 0;overflow-wrap:anywhere}.mg-reading cite{font:inherit;color:var(--mg-muted)}\n.mg-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-order-detail,.lb-customer-settings,.lb-customer-addresses){width:min(1240px,calc(100% - 112px));margin-inline:auto}.mg-theme :where(.lb-cart__checkout,.lb-cart-drawer__checkout){background:var(--primary);color:var(--mg-label)}.mg-theme .lb-cart-item__image{object-fit:contain}.mg-theme :where(.lb-policy-content,.lb-page-content,.lb-article-content){max-width:70ch;margin-inline:auto;padding:40px 24px;overflow-wrap:anywhere}.mg-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-order-detail) :where(p,td,dd,strong,a){overflow-wrap:anywhere}\n@media(max-width:1000px){.mg-wrap{width:calc(100% - 64px)}.mg-opening{gap:35px}.mg-index-feature{grid-template-columns:190px 1fr;gap:24px}.mg-feature{gap:22px;padding:24px;grid-template-columns:minmax(90px,150px) 1fr}.mg-feature>.mg-cover img{max-height:240px}.mg-theme .lb-product-detail__layout{gap:36px}.mg-theme .lb-header__inner{width:calc(100% - 64px)}}\n@media(max-width:47.999em){.mg-theme .lb-mobile-nav:not([data-open=\"true\"]) .lb-header__nav{visibility:hidden;pointer-events:none}.mg-theme .lb-mobile-nav[data-open=\"true\"] .lb-header__nav{visibility:visible;pointer-events:auto}.mg-theme .lb-header__inner{gap:10px}.mg-theme .lb-header__nav{background:var(--background);color:var(--foreground)}}\n.mg-theme :where(.lb-header__brand,.lb-header__search-toggle,.lb-header__account,.lb-header__nav-close){min-height:44px;min-width:44px;display:inline-flex;align-items:center;justify-content:center}.mg-theme .lb-header__search-toggle{background:transparent;border:0;padding:10px}.mg-theme :where(.lb-product-detail__breadcrumb a,.mg-bibliography h3 a,.lb-product-detail__accordion a){display:inline-flex;align-items:center;min-height:44px;min-width:44px}\n@media(max-width:760px){.mg-shelf,.mg-shelf[data-columns=\"4\"]{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.mg-index-feature{grid-template-columns:1fr}.mg-subjects{border:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 20px}.mg-subjects h2{width:100%;margin-bottom:0}.mg-subjects a{font-size:.9rem}.mg-theme .lb-product-detail__layout{grid-template-columns:1fr}.mg-theme .lb-product-detail__gallery{max-width:300px}.mg-editorial{gap:28px;padding:26px}.mg-theme .lb-product-detail__gallery-image{max-height:400px}.mg-book-row{grid-template-columns:88px minmax(0,1fr);gap:20px}.mg-book-row>.mg-cover{grid-row:1/3}.mg-book-row>.mg-row-end{grid-column:2;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.mg-row-end .mg-link{margin-top:0}}\n@media(max-width:640px){.mg-wrap{width:calc(100% - 40px)}.mg-section{padding-block:34px}.mg-opening{grid-template-columns:1fr;gap:26px;padding-block:30px}.mg-opening h1{font-size:2.15rem}.mg-find label{font-size:.95rem}.mg-feature{padding:20px;gap:20px;grid-template-columns:100px 1fr}.mg-feature h2{font-size:1.4rem}.mg-feature p{font-size:.9rem}.mg-feature>.mg-cover img{max-height:180px}.mg-feature .mg-link{font-size:.9rem}.mg-shelf,.mg-shelf[data-columns=\"2\"],.mg-shelf[data-columns=\"4\"]{gap:24px 16px;grid-template-columns:repeat(2,minmax(0,1fr))}.mg-shelf .mg-cover{padding:12px;min-height:190px}.mg-shelf .mg-cover img{height:180px}.mg-shelf .mg-bibliography h3{font-size:1.1rem}.mg-shelf .mg-bibliography p{font-size:.85rem}.mg-book-row{grid-template-columns:80px minmax(0,1fr);gap:16px}.mg-bibliography h3{font-size:1.25rem}.mg-theme .lb-header__inner{width:calc(100% - 40px);gap:15px}.mg-theme .lb-header__brand{font-size:1.55rem}.mg-theme .lb-product-detail{width:calc(100% - 40px);padding-bottom:36px}.mg-theme .lb-product-detail__layout{gap:28px}.mg-theme .lb-product-detail__info h1{font-size:2rem}.mg-facts dl>div{grid-template-columns:minmax(90px,.8fr) minmax(0,1.2fr);gap:14px;font-size:.95rem}.mg-editorial{grid-template-columns:1fr;padding:24px;gap:24px}.mg-reading{margin-top:35px}.mg-reading blockquote{font-size:1rem;line-height:1.85}.mg-filters{gap:12px}.mg-filters>label:first-child{flex-basis:100%}.mg-filters input{width:100%}.mg-filter-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mg-filter-fields input{max-width:100%}.mg-theme :where(.lb-cart,.lb-customer-account,.lb-customer-orders,.lb-customer-order-detail,.lb-customer-settings,.lb-customer-addresses){width:calc(100% - 40px)}.mg-theme .lb-footer{padding:36px 20px}}\n@media(max-width:360px){.mg-wrap{width:calc(100% - 32px)}.mg-feature{grid-template-columns:80px 1fr;gap:14px;padding:16px}.mg-feature h2{font-size:1.2rem}.mg-shelf .mg-cover img{height:150px}.mg-shelf .mg-cover{min-height:160px}.mg-filter-fields{grid-template-columns:1fr}}\n@media(prefers-reduced-motion:reduce){.mg-theme *{scroll-behavior:auto!important;animation:none!important;transition:none!important}}\n</style>\n</head>\n<body class=\"lb-theme lb-theme--letbuyy-core\">\n  <a class=\"lb-skip-link\" href=\"#MainContent\">Skip to content</a>\n  <header class=\"lb-layout__header\">\n    <a class=\"lb-layout__brand\" href=\"{{ routes.root_url }}\">{{ shop.name }}</a>\n    <nav class=\"lb-layout__nav\" aria-label=\"Primary\">\n      {% if linklists.main_menu.links.size > 0 %}{% for link in linklists.main_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}\n      {% else %}<a href=\"{{ routes.all_products_collection_url }}\">Products</a><a href=\"{{ routes.search_url }}\">Search</a><a href=\"{{ routes.cart_url }}\">Cart</a><a href=\"{{ routes.account_url }}\">Account</a>{% endif %}\n    </nav>\n  </header>\n  <main id=\"MainContent\">\n    {{ content_for_layout | raw }}\n  </main>\n  <footer class=\"lb-layout__footer\">\n    {% if linklists.footer.links.size > 0 %}<nav class=\"lb-layout__nav\" aria-label=\"Footer\">{% for link in linklists.footer.links %}<a href=\"{{ link.url | store_url }}\">{{ link.title }}</a>{% endfor %}</nav>{% endif %}\n    <p class=\"lb-layout__legal\">&copy; {{ shop.name }}</p>\n  </footer>\n  {{ content_for_footer | raw }}\n</body>\n</html>"}},"locales":{"en":{"general":{"cart":"Cart"}}},"package":{"author_name":"LetBuyy","compatibility_range":">=2026-06-liquid-sections","currency":"INR","description":"A reading-led bookshop with a subject index, edition bibliography and clear stationery facts.","name":"Marginalia","price":0,"pricing_type":"free","release_status":"published","site_types":["store"],"slug":"letbuyy-dawn","status":"active","version":"2.1.0","version_number":5},"renderer":{"assets":{},"engine":"liquid","liquid_ready":true,"renderer_version":"0.1.0"},"schema_version":"2026-06-liquid-sections","sections":{"404-page":{"path":"sections/404-page.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"404 Not Found","presets":[{"blocks":[],"name":"404 Not Found","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-404\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-404__code\">404</h1>\n  <p class=\"lb-404__message\">Page not found</p>\n  <a class=\"lb-404__home\" href=\"{{ routes.root_url }}\">Back to home</a>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"404 Not Found\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"404 Not Found\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"about-section":{"path":"sections/about-section.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Paper and bookshop editorial","presets":[{"blocks":[],"name":"Paper and bookshop editorial","settings":{}}],"settings":[{"default":"ROOM FOR YOUR OWN WORDS","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Good paper. Fresh possibilities.","id":"title","label":"Heading","type":"text"},{"default":"","id":"content","label":"Merchant editorial text","type":"textarea"},{"id":"image","label":"Editorial image","type":"image"},{"default":"","id":"imageAlt","label":"Image description","type":"text"},{"default":"","id":"linkLabel","label":"Link label","type":"text"},{"default":"","id":"linkUrl","label":"Link destination","type":"url"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\">{% if section.settings.content != blank or section.settings.image != blank %}<div class=\"mg-wrap mg-section\"><div class=\"mg-editorial{% if section.settings.image == blank %} mg-editorial-empty{% endif %}\">{% if section.settings.image != blank %}<img src=\"{{ section.settings.image | image_url }}\" alt=\"{{ section.settings.imageAlt }}\" loading=\"lazy\" decoding=\"async\">{% endif %}<div><span class=\"mg-eyebrow\">{{ section.settings.eyebrow }}</span><h2>{{ section.settings.title }}</h2><p>{{ section.settings.content }}</p>{% if section.settings.linkLabel != blank and section.settings.linkUrl != blank %}<a class=\"mg-link\" href=\"{{ section.settings.linkUrl | store_url }}\">{{ section.settings.linkLabel }} →</a>{% endif %}</div></div></div>{% endif %}</section>\n{% schema %}\n{\n  \"name\": \"Paper and bookshop editorial\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Eyebrow\",\n      \"default\": \"ROOM FOR YOUR OWN WORDS\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Good paper. Fresh possibilities.\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"textarea\",\n      \"label\": \"Merchant editorial text\",\n      \"default\": \"\",\n      \"id\": \"content\"\n    },\n    {\n      \"type\": \"image\",\n      \"label\": \"Editorial image\",\n      \"id\": \"image\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Image description\",\n      \"default\": \"\",\n      \"id\": \"imageAlt\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Link label\",\n      \"default\": \"\",\n      \"id\": \"linkLabel\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Link destination\",\n      \"default\": \"\",\n      \"id\": \"linkUrl\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Paper and bookshop editorial\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"announcement-bar":{"path":"sections/announcement-bar.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["header"],"templates":["*"]},"name":"Announcement Bar","presets":[{"blocks":[],"name":"Announcement Bar","settings":{}}],"settings":[{"default":"Discover our latest products.","id":"text","label":"Message","type":"text"},{"default":"Shop now","id":"linkLabel","label":"Link label","type":"text"},{"default":"/products","id":"linkHref","label":"Link URL","type":"url"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-announcement-bar\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-announcement-bar__inner\">\n    <span>{{ section.settings.text }}</span>\n    {% if section.settings.linkLabel %}<a href=\"{{ section.settings.linkHref | store_url }}\">{{ section.settings.linkLabel }}</a>{% endif %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Announcement Bar\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Message\",\n      \"default\": \"Discover our latest products.\",\n      \"id\": \"text\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Link label\",\n      \"default\": \"Shop now\",\n      \"id\": \"linkLabel\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Link URL\",\n      \"default\": \"/products\",\n      \"id\": \"linkHref\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Announcement Bar\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"header\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"app-block-slot":{"path":"sections/app-block-slot.liquid","schema":{"blocks":[{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"App Block Slot","presets":[{"blocks":[],"name":"App Block Slot","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":"storefront.home.after-hero","id":"slot","label":"Slot","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-app-block-slot\" data-section-id=\"{{ section.id }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  {% for block in section.blocks %}{{ block.content | raw }}{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"App Block Slot\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Slot\",\n      \"default\": \"storefront.home.after-hero\",\n      \"id\": \"slot\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"@app\",\n      \"name\": \"App block\",\n      \"settings\": []\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"App Block Slot\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"article-content":{"path":"sections/article-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Article Content","presets":[{"blocks":[],"name":"Article Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-article\" data-section-id=\"{{ section.id }}\">\n  {% if article %}\n  <h1 class=\"lb-article__title\">{{ article.title }}</h1>\n  {% if article.published_at %}<time class=\"lb-article__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n  {% if article.image %}<img class=\"lb-article__image\" src=\"{{ article.image | image_url }}\" alt=\"{{ article.title }}\">{% endif %}\n  {% if article.body_html != blank %}<div class=\"lb-article__body\">{{ article.body_html | raw }}</div>{% endif %}\n  {% else %}\n  <p class=\"lb-article__missing\">Article not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Article Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Article Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"banner-carousel":{"path":"sections/banner-carousel.liquid","schema":{"blocks":[{"name":"Slide","settings":[{"id":"heading","label":"Heading","type":"text"},{"id":"image","label":"Image","type":"image"},{"id":"link","label":"Link","type":"url"}],"type":"slide"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Banner Carousel","presets":[{"blocks":[],"name":"Banner Carousel","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":true,"id":"autoplay","label":"Autoplay","type":"toggle"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-banner-carousel\" data-section-id=\"{{ section.id }}\" data-autoplay=\"{{ section.settings.autoplay }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  <div class=\"lb-banner-carousel__slides\">\n    {% for block in section.blocks %}<a href=\"{{ block.settings.link | store_url }}\">{% if block.settings.image %}<img src=\"{{ block.settings.image | image_url }}\" alt=\"{{ block.settings.heading }}\">{% endif %}<h3>{{ block.settings.heading }}</h3>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Banner Carousel\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Autoplay\",\n      \"default\": true,\n      \"id\": \"autoplay\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"slide\",\n      \"name\": \"Slide\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Heading\",\n          \"id\": \"heading\"\n        },\n        {\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"id\": \"image\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link\",\n          \"id\": \"link\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Banner Carousel\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"blog-listing":{"path":"sections/blog-listing.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Blog Listing","presets":[{"blocks":[],"name":"Blog Listing","settings":{}}],"settings":[{"default":"Our Blog","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-blog-listing\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-blog-listing__heading\">{{ section.settings.heading }}</h1>\n  {% if blog.articles and blog.articles.size > 0 %}\n  <div class=\"lb-blog-listing__articles\">\n    {% for article in blog.articles %}\n    <article class=\"lb-blog-article-card\">\n      <h2 class=\"lb-blog-article-card__title\"><a href=\"{{ routes.blog_url }}/{{ article.slug }}\">{{ article.title }}</a></h2>\n      {% if article.excerpt %}<p class=\"lb-blog-article-card__excerpt\">{{ article.excerpt }}</p>{% endif %}\n      {% if article.published_at %}<time class=\"lb-blog-article-card__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n    </article>\n    {% endfor %}\n  </div>\n  {% if blog.pages_count and blog.pages_count > 1 %}\n  <nav class=\"lb-blog-listing__pagination\" aria-label=\"Blog pagination\">\n    {% if blog.current_page and blog.current_page > 1 %}<a class=\"lb-blog-listing__prev\" href=\"{{ routes.blog_url }}?page={{ blog.current_page | minus: 1 }}\" rel=\"prev\">Previous</a>{% endif %}\n    {% assign next_page = blog.current_page | plus: 1 %}\n    {% if next_page <= blog.pages_count %}<a class=\"lb-blog-listing__next\" href=\"{{ routes.blog_url }}?page={{ next_page }}\" rel=\"next\">Next</a>{% endif %}\n  </nav>\n  {% endif %}\n  {% else %}\n  <p class=\"lb-blog-listing__empty\">No posts published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Blog Listing\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Our Blog\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Blog Listing\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"brand-marquee":{"path":"sections/brand-marquee.liquid","schema":{"blocks":[{"name":"Brand","settings":[{"id":"name","label":"Name","type":"text"}],"type":"brand"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Brand Marquee","presets":[{"blocks":[],"name":"Brand Marquee","settings":{}}],"settings":[{"default":"Featured brands","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-brand-marquee\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <div>{% for block in section.blocks %}<span>{{ block.settings.name }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>{% endfor %}</div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Brand Marquee\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Featured brands\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"brand\",\n      \"name\": \"Brand\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Name\",\n          \"id\": \"name\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Brand Marquee\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"cart-summary":{"path":"sections/cart-summary.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Cart","presets":[{"blocks":[],"name":"Cart","settings":{}}],"settings":[{"default":"Your cart","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-cart-page\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <lb-cart data-lb-island=\"cart\" data-base-path=\"/store/{{ shop.subdomain }}\">\n    {% if cart.item_count > 0 %}\n    <ul class=\"lb-cart__items\">{% for item in cart.items %}<li class=\"lb-cart__item\"><span class=\"lb-cart__title\">{{ item.title }}</span><span class=\"lb-cart__qty\">x{{ item.quantity }}</span><span class=\"lb-cart__line\">{{ item.line_price | money_with_currency: cart.currency }}</span></li>{% endfor %}</ul>\n    <div class=\"lb-liquid-cart__totals\">\n      {% if cart.subtotal %}<div class=\"lb-liquid-cart__row\"><span>Subtotal</span><span>{{ cart.subtotal | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.coupon_codes.size > 0 %}<div class=\"lb-liquid-cart__row\"><span>Coupons</span><span>{{ cart.coupon_codes | join: \", \" }}</span></div>{% endif %}\n      {% if cart.discount_total %}<div class=\"lb-liquid-cart__row\"><span>Discounts</span><span>{{ cart.discount_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.shipping_total %}<div class=\"lb-liquid-cart__row\"><span>Shipping</span><span>{{ cart.shipping_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.tax_total %}<div class=\"lb-liquid-cart__row\"><span>Tax (GST)</span><span>{{ cart.tax_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n    </div>\n    <p class=\"lb-cart__total\">Total: {{ cart.total_price | money_with_currency: cart.currency }}</p>\n    <a class=\"lb-cart__checkout\" href=\"{{ cart.checkout_url }}\">Checkout</a>\n    {% else %}<p class=\"lb-cart__empty\">Your cart is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>{% endif %}\n  </lb-cart>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Cart\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your cart\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Cart\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"category-grid":{"path":"sections/category-grid.liquid","schema":{"blocks":[{"limit":12,"name":"Subject link","settings":[{"default":"","id":"label","label":"Subject label","type":"text"},{"default":"","id":"href","label":"Subject destination","type":"url"}],"type":"subject"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Subject index and reading pick","presets":[{"blocks":[],"name":"Subject index and reading pick","settings":{}}],"settings":[{"default":"Browse the shelves","id":"title","label":"Subject index heading","type":"text"},{"default":"ON THE READING TABLE","id":"eyebrow","label":"Featured product label","type":"text"},{"id":"product1","label":"Featured book or stationery","type":"product"},{"default":true,"id":"requireSelection","label":"Only show selected products","type":"toggle"},{"default":"Select a product to introduce it here.","id":"emptyText","label":"Empty featured shelf","type":"text"},{"default":"View details","id":"linkLabel","label":"Product link","type":"text"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\"><div class=\"mg-wrap mg-index-feature\"><nav class=\"mg-subjects\" aria-label=\"{{ section.settings.title }}\"><h2>{{ section.settings.title }}</h2>{% if section.blocks.size > 0 %}{% for block in section.blocks %}{% if block.settings.label != blank and block.settings.href != blank %}<a href=\"{{ block.settings.href | store_url }}\" {{ block.editor_attributes | raw }}>{{ block.settings.label }} <span aria-hidden=\"true\">→</span>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endif %}{% endfor %}{% else %}{% for subject in collections limit: 8 %}<a href=\"{{ routes.collections_url }}/{{ subject.handle }}\">{{ subject.title }} <span aria-hidden=\"true\">→</span></a>{% endfor %}{% endif %}<a href=\"{{ routes.all_products_collection_url }}\">Explore all products <span aria-hidden=\"true\">→</span></a></nav>{% if section.products.size > 0 %}{% for item in section.products limit: 1 %}<article class=\"mg-feature\"><a class=\"mg-cover\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" width=\"220\" height=\"330\" fetchpriority=\"high\" decoding=\"async\">{% else %}<span class=\"mg-missing\">Image not supplied</span>{% endif %}</a><div><span class=\"mg-eyebrow\">{{ section.settings.eyebrow }}</span><h2>{{ item.title }}</h2>{% if item.books_display.authors != blank %}<p>{{ item.books_display.authors }}</p>{% elsif item.books.authors.size > 0 %}<p>{{ item.books.authors | join: ', ' }}</p>{% endif %}{% if item.books_display.multiple_editions or item.variants.size > 1 %}<p>Multiple editions — check language and format</p>{% else %}<p>{{ item.books_display.language | default: item.books.language }}{% if item.books.format != blank %} · {{ item.books_display.format | default: item.books.format | replace: '-', ' ' }}{% endif %}</p>{% endif %}<strong class=\"mg-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"mg-link\" href=\"{{ item.url }}\">{{ section.settings.linkLabel }} <span aria-hidden=\"true\">→</span></a></div></article>{% endfor %}{% else %}<p class=\"mg-feature-empty\">{{ section.settings.emptyText }}</p>{% endif %}</div></section>\n{% schema %}\n{\n  \"name\": \"Subject index and reading pick\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Subject index heading\",\n      \"default\": \"Browse the shelves\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Featured product label\",\n      \"default\": \"ON THE READING TABLE\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Featured book or stationery\",\n      \"id\": \"product1\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Only show selected products\",\n      \"default\": true,\n      \"id\": \"requireSelection\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Empty featured shelf\",\n      \"default\": \"Select a product to introduce it here.\",\n      \"id\": \"emptyText\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Product link\",\n      \"default\": \"View details\",\n      \"id\": \"linkLabel\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"subject\",\n      \"name\": \"Subject link\",\n      \"limit\": 12,\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Subject label\",\n          \"default\": \"\",\n          \"id\": \"label\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Subject destination\",\n          \"default\": \"\",\n          \"id\": \"href\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Subject index and reading pick\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-banner":{"path":"sections/collection-banner.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Collection Banner","presets":[{"blocks":[],"name":"Collection Banner","settings":{}}],"settings":[{"default":true,"id":"showDescription","label":"Show description","type":"toggle"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-collection-banner\" data-section-id=\"{{ section.id }}\">\n  {% if collection.image_url != blank %}<img class=\"lb-collection-banner__image\" src=\"{{ collection.image_url | image_url }}\" alt=\"{{ collection.title }}\">{% endif %}\n  <h1>{{ collection.title }}</h1>\n  {% if collection.products.size > 0 %}<p class=\"lb-collection-banner__count\">{{ collection.products.size }} products</p>{% endif %}\n  {% if section.settings.showDescription and collection.description %}<div class=\"lb-collection-banner__desc\">{{ collection.description }}</div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Collection Banner\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show description\",\n      \"default\": true,\n      \"id\": \"showDescription\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Collection Banner\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-filter":{"path":"sections/collection-filter.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Book and paper discovery","presets":[{"blocks":[],"name":"Book and paper discovery","settings":{}}],"settings":[],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\"><div class=\"mg-wrap mg-discovery\">\n{% assign mg_ruling_available = false %}{% assign mg_current_ruling_supplied = false %}\n{% if collection.capabilities.books_filters %}{% for facet in collection.discovery_facets %}{% if facet.key == 'books_ruling' and facet.count > 0 %}{% assign mg_ruling_available = true %}{% if facet.value == request.query.books_ruling %}{% assign mg_current_ruling_supplied = true %}{% endif %}{% endif %}{% endfor %}{% endif %}\n<form class=\"mg-filters\" method=\"get\" action=\"{{ request.path | store_url }}\">\n{% for field in collection.discovery_query_fields %}{% assign mg_controlled = false %}{% if field.key == 'search' or field.key == 'sort' or field.key == 'page' %}{% assign mg_controlled = true %}{% elsif collection.capabilities.books_filters %}{% if field.key == 'books_author' or field.key == 'books_subject' or field.key == 'books_language' or field.key == 'books_format' or field.key == 'books_kind' %}{% assign mg_controlled = true %}{% endif %}{% endif %}{% if field.key == 'books_ruling' and mg_ruling_available %}{% assign mg_controlled = true %}{% endif %}{% unless mg_controlled %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}\n<input type=\"hidden\" name=\"page\" value=\"1\"><label>Search<input name=\"search\" type=\"search\" maxlength=\"200\" value=\"{{ request.query.search }}\" placeholder=\"Title, author or keyword\"></label>\n{% if collection.capabilities.books_filters %}<details class=\"mg-filter-details\" open><summary>Book and paper filters</summary>\n<div class=\"mg-filter-fields\" role=\"group\" aria-label=\"Book editions\"><label>Author<input name=\"books_author\" maxlength=\"200\" value=\"{{ request.query.books_author }}\"></label><label>Subject<input name=\"books_subject\" maxlength=\"100\" value=\"{{ request.query.books_subject }}\"></label><label>Language<input name=\"books_language\" maxlength=\"80\" value=\"{{ request.query.books_language }}\"></label><label>Format<select name=\"books_format\"><option value=\"\">Any format</option>{% assign formats = 'paperback,hardback,board-book,spiral-bound,other' | split: ',' %}{% for format in formats %}<option value=\"{{ format }}\"{% if request.query.books_format == format %} selected{% endif %}>{{ format | replace: '-', ' ' }}</option>{% endfor %}</select></label></div>\n<label>Product type<select name=\"books_kind\"><option value=\"\">Books and stationery</option><option value=\"book\"{% if request.query.books_kind == 'book' %} selected{% endif %}>Books</option><option value=\"stationery\"{% if request.query.books_kind == 'stationery' %} selected{% endif %}>Stationery</option></select></label>\n{% if mg_ruling_available %}<div class=\"mg-filter-fields\" role=\"group\" aria-label=\"Stationery\"><label>Ruling<select name=\"books_ruling\"><option value=\"\">Any ruling</option>{% if request.query.books_ruling != blank and mg_current_ruling_supplied != true %}<option value=\"{{ request.query.books_ruling }}\" selected>Current ruling: {{ request.query.books_ruling }} (no supplied match)</option>{% endif %}{% for facet in collection.discovery_facets %}{% if facet.key == 'books_ruling' and facet.count > 0 %}<option value=\"{{ facet.value }}\"{% if facet.selected %} selected{% endif %}>{{ facet.label }} ({{ facet.count }})</option>{% endif %}{% endfor %}</select></label></div>{% endif %}\n</details>{% endif %}\n<label>Sort<select name=\"sort\"><option value=\"display_order\"{% if request.query.sort == 'display_order' %} selected{% endif %}>Featured</option><option value=\"name\"{% if request.query.sort == 'name' %} selected{% endif %}>Title</option><option value=\"price-asc\"{% if request.query.sort == 'price-asc' %} selected{% endif %}>Price: low to high</option><option value=\"price-desc\"{% if request.query.sort == 'price-desc' %} selected{% endif %}>Price: high to low</option><option value=\"newest\"{% if request.query.sort == 'newest' %} selected{% endif %}>Newest</option></select></label><button class=\"mg-button\" type=\"submit\">Apply</button></form>\n{% if collection.active_filters.size > 0 %}<nav class=\"mg-heading\" aria-label=\"Applied filters\">{% for filter in collection.active_filters %}<a class=\"mg-link\" href=\"{{ filter.clear_url }}\" aria-label=\"Remove {{ filter.label }}\">{{ filter.label }} <span aria-hidden=\"true\">×</span></a>{% endfor %}</nav>{% endif %}\n</div></section>\n{% schema %}\n{\n  \"name\": \"Book and paper discovery\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Book and paper discovery\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-product-list":{"path":"sections/collection-product-list.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Bibliography product list","presets":[{"blocks":[],"name":"Bibliography product list","settings":{}}],"settings":[{"default":"Books and paper","id":"title","label":"Fallback heading","type":"text"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\"><div class=\"mg-wrap mg-section\"><h1>{{ collection.title | default: section.settings.title }}</h1>{% if collection.total != nil %}<p>{{ collection.total }} products</p>{% endif %}{% if collection.products.size > 0 %}<div class=\"mg-catalog\">{% for item in collection.products %}<article class=\"mg-book-row\" data-product-kind=\"{{ item.books.kind }}\"><a class=\"mg-cover\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\" width=\"208\" height=\"312\">{% else %}<span class=\"mg-missing\">Image not supplied</span>{% endif %}</a><div class=\"mg-bibliography\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3>{% if item.books.kind == 'book' %}{% if item.books_display.authors != blank %}<p class=\"mg-author\">{{ item.books_display.authors }}</p>{% elsif item.books.authors.size > 0 %}<p class=\"mg-author\">{{ item.books.authors | join: ', ' }}</p>{% endif %}{% if item.books_display.multiple_editions or item.variants.size > 1 %}<p>Multiple editions — check language and format</p>{% else %}<p>{% if item.books_display.language != blank or item.books.language != blank %}{{ item.books_display.language | default: item.books.language }}{% endif %}{% if item.books_display.format != blank or item.books.format != blank %} · {{ item.books_display.format | default: item.books.format | replace: '-', ' ' }}{% endif %}{% if item.books_display.edition != blank or item.books.edition != blank %} · {{ item.books_display.edition | default: item.books.edition }}{% endif %}</p>{% endif %}{% elsif item.books.kind == 'stationery' %}<p>{% if item.books.paper_gsm %}{{ item.books.paper_gsm }} gsm{% endif %}{% if item.books_display.dimensions != blank %} · {{ item.books_display.dimensions }}{% elsif item.books.dimensions_mm %} · {{ item.books.dimensions_mm.width }} × {{ item.books.dimensions_mm.height }} mm{% endif %}</p><p>{% if item.books.page_count %}{{ item.books.page_count }} pages{% endif %}{% if item.books.sheet_count %} / {{ item.books.sheet_count }} sheets{% endif %}{% if item.books.ruling %} · {{ item.books.ruling }}{% endif %}</p>{% endif %}{% if item.available == false %}<p class=\"mg-availability\">Currently unavailable</p>{% endif %}</div><div class=\"mg-row-end\"><strong class=\"mg-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"mg-link\" href=\"{{ item.url }}\">{% if item.books.kind == 'book' and item.books_display.multiple_editions %}View editions{% elsif item.has_options or item.options.size > 0 %}View options{% else %}View details{% endif %} <span aria-hidden=\"true\">→</span></a></div></article>{% endfor %}</div><nav class=\"mg-pagination\" aria-label=\"Product pages\">{% if collection.pagination.previous_url != blank %}<a class=\"mg-link\" href=\"{{ collection.pagination.previous_url }}\">← Previous</a>{% endif %}{% if collection.pagination.page %}<span>Page {{ collection.pagination.page }}</span>{% endif %}{% if collection.pagination.next_url != blank %}<a class=\"mg-link\" href=\"{{ collection.pagination.next_url }}\">Next →</a>{% endif %}</nav>{% else %}<div class=\"mg-empty\"><p>No products found. Try another title, author or keyword.</p><a class=\"mg-link\" href=\"{{ routes.all_products_collection_url }}\">Explore all products</a></div>{% endif %}</div></section>\n{% schema %}\n{\n  \"name\": \"Bibliography product list\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Fallback heading\",\n      \"default\": \"Books and paper\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Bibliography product list\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"contact-form":{"path":"sections/contact-form.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Contact Form","presets":[{"blocks":[],"name":"Contact Form","settings":{}}],"settings":[{"default":"Contact us","id":"title","label":"Title","type":"text"},{"id":"subtitle","label":"Subtitle","type":"text"},{"default":true,"id":"showPhone","label":"Show phone field","type":"toggle"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-contact-form\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\"><input name=\"name\" aria-label=\"Name\"><input type=\"email\" name=\"email\" aria-label=\"Email\">{% if section.settings.showPhone %}<input name=\"phone\" aria-label=\"Phone\">{% endif %}<button type=\"submit\">Send</button></form>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Contact Form\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Contact us\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subtitle\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show phone field\",\n      \"default\": true,\n      \"id\": \"showPhone\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Contact Form\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"cta-section":{"path":"sections/cta-section.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Call to Action","presets":[{"blocks":[],"name":"Call to Action","settings":{}}],"settings":[{"default":"Ready to get started?","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"},{"default":"Shop now","id":"ctaText","label":"Button text","type":"text"},{"default":"/products","id":"ctaLink","label":"Button link","type":"url"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-cta-section\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.heading }}</h2>\n  <p>{{ section.settings.subheading }}</p>\n  <a href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }}</a>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Call to Action\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Ready to get started?\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subheading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Button text\",\n      \"default\": \"Shop now\",\n      \"id\": \"ctaText\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Button link\",\n      \"default\": \"/products\",\n      \"id\": \"ctaLink\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Call to Action\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-account":{"path":"sections/customer-account.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Account","presets":[{"blocks":[],"name":"Customer Account","settings":{}}],"settings":[{"default":"Your account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-account\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in to LetBuyy as {{ buyer.full_name | default: buyer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_url }}/loyalty\">Rewards</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><form method=\"post\" action=\"/api/buyer-auth/logout?return_to={{ routes.account_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out at this store</button></form></nav>\n  {% elsif buyer_unavailable %}<p class=\"lb-account__unavailable\" role=\"status\">We could not load your LetBuyy account right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in as {{ customer.name | default: customer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><lb-logout data-logout-url=\"{{ routes.account_logout_url }}\"><form method=\"post\" action=\"{{ routes.account_logout_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out</button></form></lb-logout></nav>\n  {% else %}\n  <p class=\"lb-account__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your account.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Customer Account\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your account\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Account\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-addresses":{"path":"sections/customer-addresses.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Addresses","presets":[{"blocks":[],"name":"Addresses","settings":{}}],"settings":[{"default":"Your addresses","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-addresses\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer %}\n  <lb-address-manager data-lb-island=\"address-manager\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-address-manager>\n  {% elsif buyer_unavailable %}<p class=\"lb-addresses__unavailable\" role=\"status\">We could not load your LetBuyy addresses right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  {% if customer.addresses and customer.addresses.size > 0 %}\n  <div class=\"lb-addresses__grid\">\n    {% for addr in customer.addresses %}<div class=\"lb-address-card{% if addr.is_default %} lb-address-card--default{% endif %}\"><span class=\"lb-address-card__label\">{{ addr.label | default: \"address\" }}</span>{% if addr.is_default %}<span class=\"lb-address-card__default-badge\">Default</span>{% endif %}<p class=\"lb-address-card__address\">{{ addr.address1 }}{% if addr.address2 %}, {{ addr.address2 }}{% endif %}</p><p class=\"lb-address-card__city\">{{ addr.city }}, {{ addr.province }} {{ addr.zip }}</p></div>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-addresses__empty\">No saved addresses.</p>\n  {% endif %}\n  <lb-address-manager\n    data-lb-island=\"address-manager\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-address-manager>\n  {% else %}\n  <p class=\"lb-addresses__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your addresses.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Addresses\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your addresses\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Addresses\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-login":{"path":"sections/customer-login.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Login","presets":[{"blocks":[],"name":"Customer Login","settings":{}}],"settings":[{"default":"Sign in","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-auth lb-auth--login\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if request.error %}<p class=\"lb-auth__error\" role=\"alert\">{% case request.error %}{% when \"missing_fields\" %}Please fill in all required fields.{% when \"invalid_credentials\" %}Incorrect email or password.{% when \"account_exists\" %}An account with this email already exists. Please sign in.{% when \"rate_limited\" %}Too many attempts. Please try again shortly.{% when \"bot_verification\" %}We could not verify you are not a robot. Please try again.{% else %}Something went wrong. Please try again.{% endcase %}</p>{% endif %}\n  <form class=\"lb-auth__form\" method=\"post\" action=\"/api/customer/login\">\n    <input type=\"hidden\" name=\"storeId\" value=\"{{ shop.id }}\">\n    <input type=\"hidden\" name=\"turnstileToken\" value=\"\">\n    <lb-turnstile data-lb-island=\"turnstile\"></lb-turnstile>\n    <label>Email<input type=\"email\" name=\"email\" autocomplete=\"email\" required></label>\n    <label>Password<input type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\">Sign in</button>\n  </form>\n  <a href=\"{{ routes.customer_register_url }}\">Create an account</a>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Continue with LetBuyy</a></p>\n  <p>Have an older store account? Connect it with your verified LetBuyy account.</p>\n  <form class=\"lb-auth__link-store\" method=\"post\" action=\"/api/buyer-auth/start\">\n    <input type=\"hidden\" name=\"intent\" value=\"link_store_customer\">\n    <input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_url }}\">\n    <button type=\"submit\">Connect my store account</button>\n  </form>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Customer Login\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Sign in\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Login\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-order-detail":{"path":"sections/customer-order-detail.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Order Detail","presets":[{"blocks":[],"name":"Order Detail","settings":{}}],"settings":[{"default":"Order","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-order-detail\" data-section-id=\"{{ section.id }}\">\n  {% if buyer_unavailable %}<p class=\"lb-order-detail__error\" role=\"alert\">This order is temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  {% if order %}\n  <h1>Order #{{ order.number }}</h1>\n  <p class=\"lb-order-detail__status\">Status: {{ order.status }}</p>\n  <ul class=\"lb-order-detail__items\">{% for item in order.line_items %}<li><span class=\"lb-order-detail__title\">{{ item.title }}</span><span class=\"lb-order-detail__qty\">{{ item.quantity }}</span><span class=\"lb-order-detail__line\">{{ item.line_price | money_with_currency: order.currency }}</span><!-- lb:niche-order-presentation:v1 -->{% if item.niche_facts_text != blank %}<details class=\"lb-order-facts\"><summary>Saved product details</summary><p class=\"lb-order-facts__text\">{{ item.niche_facts_text }}</p></details>{% else %}<p class=\"lb-order-facts__missing\">Product details were not recorded with this order.</p>{% endif %}</li>{% endfor %}</ul>\n  <p class=\"lb-order-detail__total\">Total: {{ order.total | money_with_currency: order.currency }}</p>\n  {% if order.gst_invoice_number != blank %}<p class=\"lb-order-detail__invoice\">GST Invoice: {{ order.gst_invoice_number }} (Tax: {{ order.tax_total | money_with_currency: order.currency }})</p>{% endif %}\n  <ol class=\"lb-order-detail__timeline\">{% for step in order.timeline %}<li class=\"lb-order-detail__step{% if step.reached %} is-reached{% endif %}\">{{ step.label }}</li>{% endfor %}</ol>\n  {% if order.tracking_number != blank %}<p class=\"lb-order-detail__tracking\">Tracking: {{ order.tracking_number }}{% if order.carrier != blank %} ({{ order.carrier }}){% endif %}</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__missing\">Order not found.</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view this order.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Order Detail\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Order\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Order Detail\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-orders":{"path":"sections/customer-orders.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Order History","presets":[{"blocks":[],"name":"Order History","settings":{}}],"settings":[{"default":"Your orders","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-orders\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer_unavailable %}<p class=\"lb-orders__error\" role=\"alert\">Orders are temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  <form class=\"lb-orders__claim\" method=\"post\" action=\"/api/buyer/orders\"><input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_orders_url }}\"><p>Find past orders from this store placed with your verified LetBuyy email.</p><button type=\"submit\">Find past orders</button></form>\n  {% if request.query.buyer_claim == \"complete\" %}<p role=\"status\" aria-live=\"polite\">The verified orders for this store have been checked and linked.</p>{% elsif request.query.buyer_claim == \"partial\" %}<p role=\"status\" aria-live=\"polite\">Some eligible orders could not be linked. Contact the store for help.</p>{% elsif request.query.buyer_claim == \"unverified\" %}<p role=\"status\" aria-live=\"polite\">Verify your LetBuyy email before claiming historical orders.</p>{% elsif request.query.buyer_claim == \"unavailable\" %}<p role=\"status\" aria-live=\"polite\">Historical orders could not be checked right now. Please try again.</p>{% elsif request.query.buyer_claim == \"unauthorized\" %}<p role=\"status\" aria-live=\"polite\">Sign in to LetBuyy before claiming past orders.</p>{% endif %}\n  {% if buyer.orders and buyer.orders.size > 0 %}\n  <ul class=\"lb-orders__list\">{% for order in buyer.orders %}<li class=\"lb-orders__row\"><a href=\"{{ routes.account_orders_url }}/{{ order.id }}\"><span class=\"lb-orders__num\">#{{ order.number }}</span><span class=\"lb-orders__status\">{{ order.status }}</span><span class=\"lb-orders__total\">{{ order.total | money_with_currency: order.currency }}</span></a></li>{% endfor %}</ul>\n  {% if buyer.has_more and buyer.next_cursor %}<a class=\"lb-orders__next\" href=\"{{ routes.account_orders_url }}?cursor={{ buyer.next_cursor }}\">Older orders</a>{% endif %}\n  {% else %}<p class=\"lb-orders__empty\">No orders yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-orders__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view your orders.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Order History\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your orders\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Order History\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-register":{"path":"sections/customer-register.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Register","presets":[{"blocks":[],"name":"Customer Register","settings":{}}],"settings":[{"default":"Create account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-auth lb-auth--register\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <p>Create one LetBuyy account to use across participating storefronts.</p>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Create or sign in with LetBuyy</a></p>\n  <p>Have an older store-only account? <a href=\"{{ routes.customer_login_url }}\">Sign in to connect it with your verified LetBuyy account</a>.</p>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Customer Register\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Create account\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Register\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-settings":{"path":"sections/customer-settings.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Account Settings","presets":[{"blocks":[],"name":"Account Settings","settings":{}}],"settings":[{"default":"Account settings","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-settings\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\"><p class=\"lb-settings__email\">{{ buyer.email }}</p>{% if buyer.full_name %}<p class=\"lb-settings__name\">{{ buyer.full_name }}</p>{% endif %}{% if buyer.phone %}<p class=\"lb-settings__phone\">{{ buyer.phone }}</p>{% endif %}</div>\n  <lb-customer-settings data-lb-island=\"customer-settings\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-customer-settings>\n  {% elsif buyer_unavailable %}<p class=\"lb-settings__unavailable\" role=\"status\">We could not load your LetBuyy profile right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\">\n    <p class=\"lb-settings__email\">{{ customer.email }}</p>\n    {% if customer.name %}<p class=\"lb-settings__name\">{{ customer.name }}</p>{% endif %}\n    {% if customer.phone %}<p class=\"lb-settings__phone\">{{ customer.phone }}</p>{% endif %}\n  </div>\n  <lb-customer-settings\n    data-lb-island=\"customer-settings\"\n    data-email=\"{{ customer.email | escape }}\"\n    data-name=\"{{ customer.name | default: \"\" | escape }}\"\n    data-phone=\"{{ customer.phone | default: \"\" | escape }}\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-customer-settings>\n  {% else %}\n  <p class=\"lb-settings__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your settings.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Account Settings\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Account settings\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Account Settings\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-wishlist":{"path":"sections/customer-wishlist.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Wishlist","presets":[{"blocks":[],"name":"Wishlist","settings":{}}],"settings":[{"default":"Your wishlist","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-wishlist\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}{% if customer.wishlist_products.size > 0 %} <span class=\"lb-wishlist__count\">({{ customer.wishlist_products.size }})</span>{% elsif buyer_wishlist.products.size > 0 %} <span class=\"lb-wishlist__count\">({{ buyer_wishlist.products.size }})</span>{% endif %}</h1>\n  {% if buyer_wishlist.authenticated %}\n    {% if buyer_wishlist.unavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">Your wishlist is temporarily unavailable. Please try again.</p>\n    {% elsif buyer_wishlist.storeAccountUnavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">This store account is unavailable. Contact the store for help.</p>\n    {% elsif buyer_wishlist.linked and buyer_wishlist.products.size > 0 %}\n      <div class=\"lb-product-grid__items\">{% for item in buyer_wishlist.products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"true\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}</div>\n    {% elsif buyer_wishlist.linked %}<p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n    {% else %}<p class=\"lb-wishlist__guest\">Connect your verified store account in <a href=\"{{ routes.account_settings_url }}\">account settings</a> to use this store wishlist.</p>{% endif %}\n  {% elsif customer.wishlist_products and customer.wishlist_products.size > 0 %}\n  <div class=\"lb-product-grid__items\">\n    {% for item in customer.wishlist_products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"store_customer\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}\n  </div>\n  {% elsif customer %}\n  <p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n  {% else %}\n  <p class=\"lb-wishlist__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your wishlist.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Wishlist\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your wishlist\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Wishlist\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"experience-timeline":{"path":"sections/experience-timeline.liquid","schema":{"blocks":[{"name":"Experience","settings":[{"id":"title","label":"Title","type":"text"},{"id":"company","label":"Company","type":"text"},{"id":"period","label":"Period","type":"text"}],"type":"experience"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Experience Timeline","presets":[{"blocks":[],"name":"Experience Timeline","settings":{}}],"settings":[{"default":"Experience","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-experience-timeline\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article><h3>{{ block.settings.title }}</h3><p>{{ block.settings.company }}</p><time>{{ block.settings.period }}</time>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Experience Timeline\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Experience\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"experience\",\n      \"name\": \"Experience\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"id\": \"title\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Company\",\n          \"id\": \"company\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Period\",\n          \"id\": \"period\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Experience Timeline\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"faq-accordion":{"path":"sections/faq-accordion.liquid","schema":{"blocks":[{"name":"FAQ item","settings":[{"id":"question","label":"Question","type":"text"},{"id":"answer","label":"Answer","type":"richtext"}],"type":"faq-item"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"FAQ Accordion","presets":[{"blocks":[],"name":"FAQ Accordion","settings":{}}],"settings":[{"default":"Frequently asked questions","id":"title","label":"Title","type":"text"},{"default":false,"id":"allowMultipleOpen","label":"Allow multiple open","type":"toggle"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-faq-accordion\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"lb-faq-accordion__items\">\n    {% for block in section.blocks %}<details class=\"lb-faq-accordion__item\"{% unless section.settings.allowMultipleOpen %} name=\"lb-faq-{{ section.id }}\"{% endunless %}><summary class=\"lb-faq-accordion__question\">{{ block.settings.question }}</summary><div class=\"lb-faq-accordion__answer\">{{ block.settings.answer }}</div>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</details>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-faq-accordion__empty\">No questions published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"FAQ Accordion\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Frequently asked questions\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Allow multiple open\",\n      \"default\": false,\n      \"id\": \"allowMultipleOpen\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"faq-item\",\n      \"name\": \"FAQ item\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Question\",\n          \"id\": \"question\"\n        },\n        {\n          \"type\": \"richtext\",\n          \"label\": \"Answer\",\n          \"id\": \"answer\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"FAQ Accordion\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"featured-products":{"path":"sections/featured-products.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Selected reading shelf","presets":[{"blocks":[],"name":"Selected reading shelf","settings":{}}],"settings":[{"default":"A little further along the shelf","id":"title","label":"Heading","type":"text"},{"default":"","id":"subtitle","label":"Description","type":"text"},{"default":3,"id":"columns","label":"Desktop columns","max":4,"min":2,"step":1,"type":"range"},{"default":6,"id":"productLimit","label":"Products to show","max":24,"min":1,"step":1,"type":"range"},{"id":"collectionId","label":"Collection","type":"collection"},{"id":"product1","label":"First selected product","type":"product"},{"id":"product2","label":"Second selected product","type":"product"},{"id":"product3","label":"Third selected product","type":"product"},{"default":true,"id":"requireSelection","label":"Only show selected products","type":"toggle"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\">{% if section.settings.requireSelection != true or section.products.size > 0 %}<div class=\"mg-wrap mg-section\"><div class=\"mg-heading\"><div><h2>{{ section.settings.title }}</h2>{% if section.settings.subtitle != blank %}<p>{{ section.settings.subtitle }}</p>{% endif %}</div></div>{% assign mg_products = section.products %}{% if section.settings.requireSelection != true and section.settings.collectionId == blank %}{% assign mg_products = section.products | default: collection.products %}{% endif %}{% if mg_products.size > 0 %}<div class=\"mg-shelf\" data-columns=\"{{ section.settings.columns }}\">{% for item in mg_products limit: section.settings.productLimit %}<article class=\"mg-book-row\" data-product-kind=\"{{ item.books.kind }}\"><a class=\"mg-cover\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\" width=\"208\" height=\"312\">{% else %}<span class=\"mg-missing\">Image not supplied</span>{% endif %}</a><div class=\"mg-bibliography\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3>{% if item.books.kind == 'book' %}{% if item.books_display.authors != blank %}<p class=\"mg-author\">{{ item.books_display.authors }}</p>{% elsif item.books.authors.size > 0 %}<p class=\"mg-author\">{{ item.books.authors | join: ', ' }}</p>{% endif %}{% if item.books_display.multiple_editions or item.variants.size > 1 %}<p>Multiple editions — check language and format</p>{% else %}<p>{% if item.books_display.language != blank or item.books.language != blank %}{{ item.books_display.language | default: item.books.language }}{% endif %}{% if item.books_display.format != blank or item.books.format != blank %} · {{ item.books_display.format | default: item.books.format | replace: '-', ' ' }}{% endif %}{% if item.books_display.edition != blank or item.books.edition != blank %} · {{ item.books_display.edition | default: item.books.edition }}{% endif %}</p>{% endif %}{% elsif item.books.kind == 'stationery' %}<p>{% if item.books.paper_gsm %}{{ item.books.paper_gsm }} gsm{% endif %}{% if item.books_display.dimensions != blank %} · {{ item.books_display.dimensions }}{% elsif item.books.dimensions_mm %} · {{ item.books.dimensions_mm.width }} × {{ item.books.dimensions_mm.height }} mm{% endif %}</p><p>{% if item.books.page_count %}{{ item.books.page_count }} pages{% endif %}{% if item.books.sheet_count %} / {{ item.books.sheet_count }} sheets{% endif %}{% if item.books.ruling %} · {{ item.books.ruling }}{% endif %}</p>{% endif %}{% if item.available == false %}<p class=\"mg-availability\">Currently unavailable</p>{% endif %}</div><div class=\"mg-row-end\"><strong class=\"mg-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"mg-link\" href=\"{{ item.url }}\">{% if item.books.kind == 'book' and item.books_display.multiple_editions %}View editions{% elsif item.has_options or item.options.size > 0 %}View options{% else %}View details{% endif %} <span aria-hidden=\"true\">→</span></a></div></article>{% endfor %}</div>{% else %}<p class=\"mg-empty\">Products added to this collection will appear here.</p>{% endif %}</div>{% endif %}</section>\n{% schema %}\n{\n  \"name\": \"Selected reading shelf\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"A little further along the shelf\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Desktop columns\",\n      \"default\": 3,\n      \"min\": 2,\n      \"max\": 4,\n      \"step\": 1,\n      \"id\": \"columns\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Products to show\",\n      \"default\": 6,\n      \"min\": 1,\n      \"max\": 24,\n      \"step\": 1,\n      \"id\": \"productLimit\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Collection\",\n      \"id\": \"collectionId\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"First selected product\",\n      \"id\": \"product1\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Second selected product\",\n      \"id\": \"product2\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Third selected product\",\n      \"id\": \"product3\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Only show selected products\",\n      \"default\": true,\n      \"id\": \"requireSelection\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Selected reading shelf\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"footer":{"path":"sections/footer.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["footer"],"templates":["*"]},"limit":1,"name":"Footer","presets":[{"blocks":[],"name":"Footer","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"id":"tagline","label":"Tagline","type":"text"},{"id":"contactEmail","label":"Contact email","type":"text"},{"id":"contactPhone","label":"Contact phone","type":"text"},{"id":"instagramUrl","label":"Instagram URL","type":"url"},{"id":"facebookUrl","label":"Facebook URL","type":"url"},{"id":"twitterUrl","label":"Twitter/X URL","type":"url"}],"tag":"section"},"source":"<div class=\"mg-theme\"><footer class=\"lb-footer\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-footer__grid\">\n    <div class=\"lb-footer__brand\">\n      <h3>{{ section.settings.storeName | default: shop.name }}</h3>\n      {% if section.settings.tagline %}<p>{{ section.settings.tagline }}</p>{% endif %}\n      {% if section.settings.instagramUrl != blank or section.settings.facebookUrl != blank or section.settings.twitterUrl != blank %}\n      <div class=\"lb-footer__social\">\n        {% if section.settings.instagramUrl != blank %}<a href=\"{{ section.settings.instagramUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"></circle></svg></a>{% endif %}\n        {% if section.settings.facebookUrl != blank %}<a href=\"{{ section.settings.facebookUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M15 4h-2a4 4 0 0 0-4 4v3H6v4h3v7h4v-7h3l1-4h-4V8a1 1 0 0 1 1-1h3z\"></path></svg></a>{% endif %}\n        {% if section.settings.twitterUrl != blank %}<a href=\"{{ section.settings.twitterUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Twitter/X\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"4\" y1=\"4\" x2=\"20\" y2=\"20\"></line><line x1=\"20\" y1=\"4\" x2=\"4\" y2=\"20\"></line></svg></a>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if section.blocks.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for block in section.blocks %}<a href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}</nav></div>\n    {% elsif linklists.footer_menu.links.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for link in linklists.footer_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}</nav></div>\n    {% endif %}\n    {% if shop.policies.size > 0 %}<div class=\"lb-footer__col\">\n      <h4>Policies</h4>\n      <nav>\n        {% if shop.policies contains 'privacy' %}<a href=\"{{ routes.root_url }}/privacy\">Privacy policy</a>{% endif %}\n        {% if shop.policies contains 'terms' %}<a href=\"{{ routes.root_url }}/terms\">Terms of service</a>{% endif %}\n        {% if shop.policies contains 'shipping' %}<a href=\"{{ routes.root_url }}/shipping\">Shipping policy</a>{% endif %}\n        {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}<a href=\"{{ routes.root_url }}/returns\">Returns policy</a>{% endif %}\n      </nav>\n    </div>{% endif %}\n    <div class=\"lb-footer__col\">\n      <h4>Contact</h4>\n      {% if section.settings.contactEmail != blank %}<p><a href=\"mailto:{{ section.settings.contactEmail }}\">{{ section.settings.contactEmail }}</a></p>{% endif %}\n      {% if section.settings.contactPhone != blank %}<p><a href=\"tel:{{ section.settings.contactPhone }}\">{{ section.settings.contactPhone }}</a></p>{% endif %}\n      <a href=\"{{ routes.contact_url }}\">Contact us</a>\n    </div>\n  </div>\n  <div class=\"lb-footer__bottom\">\n    <p>&copy; {{ shop.name }}. All rights reserved.</p>\n    <a class=\"lb-footer__watermark\" href=\"https://letbuyy.com\" target=\"_blank\" rel=\"noopener noreferrer\">Powered by LetBuyy</a>\n  </div>\n</footer>\n</div>\n{% schema %}\n{\n  \"name\": \"Footer\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Store name\",\n      \"id\": \"storeName\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Tagline\",\n      \"id\": \"tagline\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Contact email\",\n      \"id\": \"contactEmail\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Contact phone\",\n      \"id\": \"contactPhone\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Instagram URL\",\n      \"id\": \"instagramUrl\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Facebook URL\",\n      \"id\": \"facebookUrl\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Twitter/X URL\",\n      \"id\": \"twitterUrl\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"id\": \"label\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"URL\",\n          \"id\": \"href\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Footer\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"footer\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  },\n  \"limit\": 1\n}\n{% endschema %}"},"header":{"path":"sections/header.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["header"],"templates":["*"]},"limit":1,"name":"Header","presets":[{"blocks":[],"name":"Header","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"default":true,"id":"showSearch","label":"Show search","type":"toggle"},{"default":true,"id":"showCart","label":"Show cart","type":"toggle"},{"default":"sticky","id":"behavior","label":"Header behavior","options":["static","sticky"],"type":"select"},{"default":"main_menu","id":"menu","label":"Menu","options":["main_menu","footer_menu","policy_menu"],"type":"select"},{"default":"inline","id":"layout","label":"Layout","options":["inline","centered"],"type":"select"}],"tag":"section"},"source":"<div class=\"mg-theme\"><header class=\"lb-header\" data-section-id=\"{{ section.id }}\" data-sticky=\"{% if section.settings.behavior == 'sticky' %}true{% else %}false{% endif %}\" data-layout=\"{{ section.settings.layout | default: 'inline' }}\">\n  <div class=\"lb-header__inner\">\n    <lb-mobile-nav class=\"lb-mobile-nav\" data-lb-island=\"mobile-nav\">\n      <button type=\"button\" class=\"lb-header__toggle\" data-lb-nav-toggle aria-expanded=\"false\" aria-controls=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg><span class=\"lb-sr-only\">Menu</span></button>\n      <nav class=\"lb-header__nav\" data-lb-nav-panel id=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Primary\">\n        <div class=\"lb-header__nav-head\"><span class=\"lb-header__nav-head-brand\">{{ section.settings.storeName | default: shop.name }}</span><button type=\"button\" class=\"lb-header__nav-close\" data-lb-nav-close aria-label=\"Close menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close menu</span></button></div>\n        <div class=\"lb-header__nav-links\">\n        {% if section.blocks.size > 0 %}\n          {% for block in section.blocks %}<a href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n        {% else %}\n          {% assign lb_menu_handle = section.settings.menu | default: 'main_menu' %}\n          {% assign lb_nav_links = linklists[lb_menu_handle].links %}\n          {% for link in lb_nav_links %}\n            {% if link.links.size > 0 %}\n            <details class=\"lb-header__nav-item\" data-lb-nav-dropdown><summary{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\" class=\"lb-icon-chevron\"><path d=\"M6 9l6 6 6-6\"></path></svg></summary>\n              <div class=\"lb-header__nav-submenu\">{% for child in link.links %}<a href=\"{{ child.url | store_url }}\"{% if child.active %} aria-current=\"page\"{% endif %}>{{ child.title }}</a>{% endfor %}</div>\n            </details>\n            {% else %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endif %}\n          {% endfor %}\n        {% endif %}\n        </div>\n        <div class=\"lb-header__nav-foot\">\n          {% if customer %}<a href=\"{{ routes.account_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Account</span></a>{% else %}<a href=\"{{ routes.customer_login_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Log in</span></a>{% endif %}\n        </div>\n      </nav>\n      <div class=\"lb-header__scrim\" data-lb-nav-scrim></div>\n    </lb-mobile-nav>\n    <a class=\"lb-header__brand\" href=\"{{ routes.root_url }}\">\n      {% if shop.logo_url %}<img class=\"lb-header__logo\" src=\"{{ shop.logo_url | image_url }}\" alt=\"{{ section.settings.storeName | default: shop.name }}\">{% else %}{{ section.settings.storeName | default: shop.name }}{% endif %}\n    </a>\n    <div class=\"lb-header__actions\">\n      {% if section.settings.showSearch %}<button type=\"button\" class=\"lb-header__search-toggle\" data-lb-search-toggle aria-expanded=\"false\" aria-controls=\"lb-search-overlay-{{ section.id }}\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>{% endif %}\n      <a class=\"lb-header__account\" href=\"{% if customer %}{{ routes.account_url }}{% else %}{{ routes.customer_login_url }}{% endif %}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span class=\"lb-sr-only\">{% if customer %}Account{% else %}Log in{% endif %}</span></a>\n      {% if section.settings.showCart %}<a class=\"lb-header__cart\" href=\"{{ routes.cart_url }}\" data-lb-cart-trigger><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M3 4h2l2 12h11l2-8H6\"></path><circle cx=\"9\" cy=\"20\" r=\"1\"></circle><circle cx=\"17\" cy=\"20\" r=\"1\"></circle></svg><span class=\"lb-sr-only\">{{ \"general.cart\" | t }}</span> (<span data-lb-cart-count>{{ cart.item_count | default: 0 }}</span>)</a>{% endif %}\n    </div>\n  </div>\n  {% if section.settings.showSearch %}\n  <div class=\"lb-header__search-overlay\" id=\"lb-search-overlay-{{ section.id }}\" data-lb-search-overlay hidden>\n    <lb-predictive-search class=\"lb-predictive-search\" data-lb-island=\"predictive-search\" data-search-url=\"{{ routes.search_url }}\">\n      <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n        <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n        <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"Search products\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"false\" aria-controls=\"lb-search-results-{{ section.id }}\" aria-autocomplete=\"list\">\n        <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n        <button type=\"button\" data-lb-search-close aria-label=\"Close search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close search</span></button>\n      </form>\n      <div id=\"lb-search-results-{{ section.id }}\" class=\"lb-predictive-search__results\" data-lb-search-results role=\"listbox\" aria-live=\"polite\"></div>\n    </lb-predictive-search>\n  </div>\n  {% endif %}\n</header>\n</div>\n{% schema %}\n{\n  \"name\": \"Header\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Store name\",\n      \"id\": \"storeName\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show search\",\n      \"default\": true,\n      \"id\": \"showSearch\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show cart\",\n      \"default\": true,\n      \"id\": \"showCart\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Header behavior\",\n      \"default\": \"sticky\",\n      \"options\": [\n        \"static\",\n        \"sticky\"\n      ],\n      \"id\": \"behavior\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Menu\",\n      \"default\": \"main_menu\",\n      \"options\": [\n        \"main_menu\",\n        \"footer_menu\",\n        \"policy_menu\"\n      ],\n      \"id\": \"menu\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Layout\",\n      \"default\": \"inline\",\n      \"options\": [\n        \"inline\",\n        \"centered\"\n      ],\n      \"id\": \"layout\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"id\": \"label\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"URL\",\n          \"id\": \"href\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Header\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"header\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  },\n  \"limit\": 1\n}\n{% endschema %}"},"hero-banner":{"path":"sections/hero-banner.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Bookshop opening and search","presets":[{"blocks":[],"name":"Bookshop opening and search","settings":{}}],"settings":[{"default":"BOOKS & PAPER","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Find your next good read.","id":"heading","label":"Heading","type":"text"},{"default":"Books to spend time with. Paper for what comes next.","id":"subheading","label":"Description","type":"text"},{"default":"What would you like to read?","id":"searchLabel","label":"Search label","type":"text"},{"default":"Title, author or keyword","id":"searchPlaceholder","label":"Search placeholder","type":"text"},{"default":"Search","id":"searchButton","label":"Search button","type":"text"},{"default":"Browse the subject index, or search the catalog.","id":"searchHint","label":"Search help","type":"text"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\"><div class=\"mg-wrap mg-opening\"><div><span class=\"mg-eyebrow\">{{ section.settings.eyebrow }}</span><h1>{{ section.settings.heading }}</h1>{% if section.settings.subheading != blank %}<p class=\"mg-intro\">{{ section.settings.subheading }}</p>{% endif %}</div><div class=\"mg-find\"><label for=\"mg-search-{{ section.id }}\">{{ section.settings.searchLabel }}</label><form class=\"mg-search\" method=\"get\" action=\"{{ routes.search_url }}\"><input id=\"mg-search-{{ section.id }}\" name=\"search\" type=\"search\" maxlength=\"200\" placeholder=\"{{ section.settings.searchPlaceholder }}\"><button type=\"submit\">{{ section.settings.searchButton }}</button></form>{% if section.settings.searchHint != blank %}<p>{{ section.settings.searchHint }}</p>{% endif %}</div></div></section>\n{% schema %}\n{\n  \"name\": \"Bookshop opening and search\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Eyebrow\",\n      \"default\": \"BOOKS & PAPER\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Find your next good read.\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"Books to spend time with. Paper for what comes next.\",\n      \"id\": \"subheading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Search label\",\n      \"default\": \"What would you like to read?\",\n      \"id\": \"searchLabel\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Search placeholder\",\n      \"default\": \"Title, author or keyword\",\n      \"id\": \"searchPlaceholder\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Search button\",\n      \"default\": \"Search\",\n      \"id\": \"searchButton\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Search help\",\n      \"default\": \"Browse the subject index, or search the catalog.\",\n      \"id\": \"searchHint\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Bookshop opening and search\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"marquee":{"path":"sections/marquee.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Marquee","presets":[{"blocks":[],"name":"Marquee","settings":{}}],"settings":[{"default":"Featured announcement","id":"text","label":"Text","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-marquee\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.text }}</p>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Marquee\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Text\",\n      \"default\": \"Featured announcement\",\n      \"id\": \"text\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Marquee\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"newsletter-signup":{"path":"sections/newsletter-signup.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template","footer"],"templates":["*"]},"name":"Newsletter Signup","presets":[{"blocks":[],"name":"Newsletter Signup","settings":{}}],"settings":[{"default":"Get first access","id":"title","label":"Heading","type":"text"},{"id":"subtitle","label":"Subheading","type":"text"},{"default":"Sign up","id":"buttonLabel","label":"Button label","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-newsletter-signup\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\">\n    <input type=\"email\" name=\"email\" aria-label=\"Email\" required>\n    <button type=\"submit\">{{ section.settings.buttonLabel }}</button>\n  </form>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Newsletter Signup\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Get first access\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Button label\",\n      \"default\": \"Sign up\",\n      \"id\": \"buttonLabel\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Newsletter Signup\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\",\n      \"footer\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"page-content":{"path":"sections/page-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Page Content","presets":[{"blocks":[],"name":"Page Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-page\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-page__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-page__body\">{{ page.body_html | raw }}</div>\n  {% else %}<p class=\"lb-page__empty\">No content yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-page__missing\">Page not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Page Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Page Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"password-gate":{"path":"sections/password-gate.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Password Gate","presets":[{"blocks":[],"name":"Password Gate","settings":{}}],"settings":[{"default":"Coming Soon","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><!-- password gate rendering requires proxy routing update (Phase F) -->\n<section class=\"lb-password-gate\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-password-gate__heading\">{{ shop.name }}</h1>\n  <p class=\"lb-password-gate__message\">{{ section.settings.heading }}</p>\n  <p class=\"lb-password-gate__info\">This store is password protected.</p>\n  <form class=\"lb-password-gate__form\" method=\"post\" action=\"/store-access/password\">\n    <label class=\"lb-password-gate__label\">Enter password<input class=\"lb-password-gate__input\" type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\" class=\"lb-password-gate__btn\">Enter</button>\n  </form>\n  {% if shop.access_message and shop.access_message != blank %}<p class=\"lb-password-gate__access-message\">{{ shop.access_message }}</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Password Gate\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Coming Soon\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Password Gate\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"policy-content":{"path":"sections/policy-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Policy Content","presets":[{"blocks":[],"name":"Policy Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-policy\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-policy__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-policy__body\">{{ page.body_html | raw }}</div>\n  {% elsif page.content != blank %}<div class=\"lb-policy__body\">{{ page.content | raw }}</div>{% endif %}\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Policy Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Policy Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"portfolio-grid":{"path":"sections/portfolio-grid.liquid","schema":{"blocks":[{"name":"Project","settings":[{"id":"title","label":"Title","type":"text"},{"id":"summary","label":"Summary","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"project"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Portfolio Grid","presets":[{"blocks":[],"name":"Portfolio Grid","settings":{}}],"settings":[{"default":"Portfolio","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-portfolio-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article><h3>{{ block.settings.title }}</h3><p>{{ block.settings.summary }}</p><a href=\"{{ block.settings.link | store_url }}\">View</a>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Portfolio Grid\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Portfolio\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"project\",\n      \"name\": \"Project\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"id\": \"title\"\n        },\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Summary\",\n          \"id\": \"summary\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link\",\n          \"id\": \"link\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Portfolio Grid\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"product-detail":{"path":"sections/product-detail.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Product Detail","presets":[{"blocks":[],"name":"Product Detail","settings":{}}],"settings":[{"default":true,"id":"showGallery","label":"Show gallery","type":"toggle"},{"default":true,"id":"showDescription","label":"Show description","type":"toggle"},{"default":true,"id":"showReviews","label":"Show reviews","type":"toggle"},{"default":true,"id":"showBookFacts","label":"Show book and paper facts","type":"toggle"},{"default":true,"id":"showExcerpt","label":"Show permitted reading sample","type":"toggle"}],"tag":"section"},"source":"<div class=\"mg-theme\"><section class=\"lb-product-detail\" data-section-id=\"{{ section.id }}\" data-product-kind=\"{{ product.books.kind }}\">\n  <nav class=\"lb-product-detail__breadcrumb\" aria-label=\"Breadcrumb\">\n    <a href=\"{{ routes.root_url }}\">Home</a>\n    <a href=\"{{ routes.all_products_collection_url }}\">Shop</a>\n    <span aria-current=\"page\">{{ product.title }}</span>\n  </nav>\n  <div class=\"lb-product-detail__layout\">\n  {% if section.settings.showGallery and product.images.size > 0 %}\n  <lb-product-gallery class=\"lb-product-detail__gallery\" data-lb-island=\"product-gallery\">\n    <div class=\"lb-product-detail__gallery-main\">\n      {% for image in product.images %}<img class=\"lb-product-detail__gallery-image\" src=\"{{ image | image_url }}\" alt=\"{{ product.title }}\" data-lb-gallery-image data-index=\"{{ forloop.index0 }}\"{% unless forloop.first %} hidden{% endunless %} loading=\"{% if forloop.first %}eager{% else %}lazy{% endif %}\" decoding=\"async\">{% endfor %}\n    </div>\n    {% if product.images.size > 1 %}\n    <div class=\"lb-product-detail__gallery-thumbs\" role=\"tablist\" aria-label=\"Product images\">\n      {% for image in product.images %}<button type=\"button\" class=\"lb-product-detail__gallery-thumb\" data-lb-gallery-thumb data-index=\"{{ forloop.index0 }}\" role=\"tab\" aria-selected=\"{% if forloop.first %}true{% else %}false{% endif %}\" tabindex=\"{% if forloop.first %}0{% else %}-1{% endif %}\" aria-label=\"Image {{ forloop.index }} of {{ product.images.size }}\"><img src=\"{{ image | image_url }}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\" decoding=\"async\"></button>{% endfor %}\n    </div>\n    {% endif %}\n  </lb-product-gallery>\n  {% endif %}\n  <div class=\"lb-product-detail__info\">\n  <h1>{{ product.title }}</h1>{% if section.settings.showBookFacts and product.books.authors.size > 0 %}<p class=\"mg-author\">{{ product.books.authors | join: ', ' }}</p>{% endif %}\n  {% if product.review_count > 0 %}<p class=\"lb-product-detail__rating\" aria-label=\"Rated {{ product.rating }} out of 5\">★ {{ product.rating }} <span class=\"lb-product-detail__rating-count\">({{ product.review_count }})</span></p>{% endif %}\n  <div class=\"lb-product-detail__price\">\n    <span class=\"lb-product-detail__price-current\">{{ product.price | times: 100 | money_with_currency: product.currency }}</span>\n    {% if product.compare_at_price and product.compare_at_price > product.price %}\n    <s class=\"lb-product-detail__price-compare\">{{ product.compare_at_price | times: 100 | money_with_currency: product.currency }}</s>\n    <span class=\"lb-product-detail__price-save\">Save {{ product.compare_at_price | minus: product.price | times: 100.0 | divided_by: product.compare_at_price | round }}%</span>\n    {% endif %}\n  </div>\n  {% if product.options.size > 0 %}<lb-variant-picker data-lb-island=\"variant-picker\" data-product-id=\"{{ product.id }}\" data-variants=\"{{ product.variants | json }}\" class=\"lb-product-detail__variants\">{% for option in product.options %}<div class=\"lb-product-detail__variant-group\"><span class=\"lb-variant-option__name\">{{ option.name }}</span><div class=\"lb-product-detail__variant-values\">{% for value in option.values %}<button type=\"button\" data-lb-variant-option data-variant-name=\"{{ option.name }}\" data-variant-value=\"{{ value }}\" aria-pressed=\"false\">{{ value }}</button>{% endfor %}</div></div>{% endfor %}<p class=\"lb-product-detail__variant-status\" data-lb-variant-status role=\"status\"></p></lb-variant-picker>{% endif %}\n  <div class=\"lb-product-detail__purchase\">\n    <lb-add-to-cart data-lb-island=\"add-to-cart\" data-product-id=\"{{ product.id }}\" data-product-name=\"{{ product.title }}\" data-product-price=\"{{ product.price }}\" data-product-currency=\"{{ product.currency }}\" data-product-url=\"{{ product.url }}\">\n      <label class=\"lb-sr-only\" for=\"lb-quantity-{{ section.id }}\">Quantity</label>\n      <input type=\"number\" name=\"quantity\" id=\"lb-quantity-{{ section.id }}\" class=\"lb-product-detail__quantity\" value=\"1\" min=\"1\" inputmode=\"numeric\">\n      <button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--primary\" data-lb-add-to-cart{% if product.available == false %} disabled{% endif %}>{% if product.available == false %}Sold out{% else %}Add to cart{% endif %}</button>\n      <button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--secondary\" data-lb-buy-now{% if product.available == false %} disabled{% endif %}>Buy now</button>\n      <span data-lb-add-to-cart-status aria-live=\"polite\"></span>\n    </lb-add-to-cart>\n    <lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"{% if product.in_wishlist %}true{% endif %}\"{% if buyer_wishlist.authenticated %} data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"{% if buyer_wishlist.linked %}true{% endif %}\" data-buyer-unavailable=\"{% if buyer_wishlist.unavailable or buyer_wishlist.storeAccountUnavailable %}true{% endif %}\"{% elsif customer %} data-authenticated=\"true\" data-account-type=\"store_customer\"{% endif %} data-base-path=\"/store/{{ shop.subdomain }}\" aria-label=\"Add {{ product.title }} to wishlist\"></lb-wishlist-toggle>\n  </div>\n  {% if section.settings.showBookFacts %}<section class=\"mg-facts\" aria-label=\"Product facts\">{% if product.books.kind == 'book' %}<h2>About this book</h2><dl>{% if product.books.authors.size > 0 %}<div><dt>Author</dt><dd>{{ product.books.authors | join: ', ' }}</dd></div>{% endif %}{% if product.books.subjects.size > 0 %}<div><dt>Subjects</dt><dd>{{ product.books.subjects | join: ', ' }}</dd></div>{% endif %}{% if product.variants.size == 0 %}{% assign mg_facts = product.books %}{% assign mg_display = product.books_display %}{% if mg_facts.language != blank %}<div><dt>Language</dt><dd>{{ mg_facts.language }}</dd></div>{% endif %}{% if mg_facts.format != blank %}<div><dt>Format</dt><dd>{{ mg_facts.format | replace: '-', ' ' }}</dd></div>{% endif %}{% if mg_facts.edition != blank %}<div><dt>Edition</dt><dd>{{ mg_facts.edition }}</dd></div>{% endif %}{% if mg_facts.publisher != blank %}<div><dt>Publisher</dt><dd>{{ mg_facts.publisher }}</dd></div>{% endif %}{% if mg_facts.publication_year %}<div><dt>Publication year</dt><dd>{{ mg_facts.publication_year }}</dd></div>{% endif %}{% if mg_facts.pages %}<div><dt>Pages</dt><dd>{{ mg_facts.pages }}</dd></div>{% endif %}{% if mg_display.dimensions != blank %}<div><dt>Dimensions</dt><dd>{{ mg_display.dimensions }}</dd></div>{% elsif mg_facts.dimensions_mm %}<div><dt>Dimensions</dt><dd>{{ mg_facts.dimensions_mm.width }} × {{ mg_facts.dimensions_mm.height }} mm</dd></div>{% endif %}{% if mg_facts.isbn != blank %}<div><dt>ISBN</dt><dd>{{ mg_facts.isbn }}</dd></div>{% endif %}{% endif %}</dl>{% elsif product.books.kind == 'stationery' %}<h2>Paper and materials</h2>{% if product.variants.size == 0 %}{% assign mg_facts = product.books %}{% assign mg_display = product.books_display %}<dl>{% if mg_facts.paper_gsm %}<div><dt>Paper weight</dt><dd>{{ mg_facts.paper_gsm }} gsm</dd></div>{% endif %}{% if mg_display.dimensions != blank %}<div><dt>Dimensions</dt><dd>{{ mg_display.dimensions }}</dd></div>{% elsif mg_facts.dimensions_mm %}<div><dt>Dimensions</dt><dd>{{ mg_facts.dimensions_mm.width }} × {{ mg_facts.dimensions_mm.height }} mm</dd></div>{% endif %}{% if mg_facts.page_count %}<div><dt>Pages</dt><dd>{{ mg_facts.page_count }}</dd></div>{% endif %}{% if mg_facts.sheet_count %}<div><dt>Sheets</dt><dd>{{ mg_facts.sheet_count }}</dd></div>{% endif %}{% if mg_facts.ruling != blank %}<div><dt>Ruling</dt><dd>{{ mg_facts.ruling }}</dd></div>{% endif %}{% if mg_facts.binding != blank %}<div><dt>Binding</dt><dd>{{ mg_facts.binding }}</dd></div>{% endif %}{% if mg_facts.materials != blank %}<div><dt>Materials</dt><dd>{{ mg_facts.materials }}</dd></div>{% endif %}{% if mg_facts.included.size > 0 %}<div><dt>Included</dt><dd><ul>{% for part in mg_facts.included %}<li>{{ part }}</li>{% endfor %}</ul></dd></div>{% endif %}</dl>{% endif %}{% else %}<h2>Product information</h2><p>Detailed product facts have not been supplied.</p>{% endif %}{% if product.variants.size > 0 %}<h3>Options and edition details</h3><p>Check the language, format and availability for your chosen option above.</p><div class=\"mg-editions\">{% for edition in product.variants %}<article class=\"mg-edition\" data-variant-id=\"{{ edition.id }}\"><h3>{{ edition.name | default: 'Option' }}</h3>{% assign mg_facts = edition.books %}{% assign mg_display = edition.books_display %}{% if mg_facts.kind == 'book' %}<dl>{% if mg_facts.language != blank %}<div><dt>Language</dt><dd>{{ mg_facts.language }}</dd></div>{% endif %}{% if mg_facts.format != blank %}<div><dt>Format</dt><dd>{{ mg_facts.format | replace: '-', ' ' }}</dd></div>{% endif %}{% if mg_facts.edition != blank %}<div><dt>Edition</dt><dd>{{ mg_facts.edition }}</dd></div>{% endif %}{% if mg_facts.publisher != blank %}<div><dt>Publisher</dt><dd>{{ mg_facts.publisher }}</dd></div>{% endif %}{% if mg_facts.publication_year %}<div><dt>Publication year</dt><dd>{{ mg_facts.publication_year }}</dd></div>{% endif %}{% if mg_facts.pages %}<div><dt>Pages</dt><dd>{{ mg_facts.pages }}</dd></div>{% endif %}{% if mg_display.dimensions != blank %}<div><dt>Dimensions</dt><dd>{{ mg_display.dimensions }}</dd></div>{% elsif mg_facts.dimensions_mm %}<div><dt>Dimensions</dt><dd>{{ mg_facts.dimensions_mm.width }} × {{ mg_facts.dimensions_mm.height }} mm</dd></div>{% endif %}{% if mg_facts.isbn != blank %}<div><dt>ISBN</dt><dd>{{ mg_facts.isbn }}</dd></div>{% endif %}</dl>{% elsif mg_facts.kind == 'stationery' %}<dl>{% if mg_facts.paper_gsm %}<div><dt>Paper weight</dt><dd>{{ mg_facts.paper_gsm }} gsm</dd></div>{% endif %}{% if mg_display.dimensions != blank %}<div><dt>Dimensions</dt><dd>{{ mg_display.dimensions }}</dd></div>{% elsif mg_facts.dimensions_mm %}<div><dt>Dimensions</dt><dd>{{ mg_facts.dimensions_mm.width }} × {{ mg_facts.dimensions_mm.height }} mm</dd></div>{% endif %}{% if mg_facts.page_count %}<div><dt>Pages</dt><dd>{{ mg_facts.page_count }}</dd></div>{% endif %}{% if mg_facts.sheet_count %}<div><dt>Sheets</dt><dd>{{ mg_facts.sheet_count }}</dd></div>{% endif %}{% if mg_facts.ruling != blank %}<div><dt>Ruling</dt><dd>{{ mg_facts.ruling }}</dd></div>{% endif %}{% if mg_facts.binding != blank %}<div><dt>Binding</dt><dd>{{ mg_facts.binding }}</dd></div>{% endif %}{% if mg_facts.materials != blank %}<div><dt>Materials</dt><dd>{{ mg_facts.materials }}</dd></div>{% endif %}{% if mg_facts.included.size > 0 %}<div><dt>Included</dt><dd><ul>{% for part in mg_facts.included %}<li>{{ part }}</li>{% endfor %}</ul></dd></div>{% endif %}</dl>{% else %}<p>Details for this option have not been supplied.</p>{% endif %}{% if edition.stock == 0 %}<p>Currently unavailable</p>{% endif %}</article>{% endfor %}</div>{% endif %}</section>{% endif %}\n  {% if section.settings.showDescription and product.description != blank %}\n  <details class=\"lb-product-detail__accordion\"><summary>Description</summary><div class=\"lb-product-detail__accordion-body\">{{ product.description }}</div></details>\n  {% endif %}\n  {% if shop.policies contains 'shipping' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Shipping</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/shipping\">Read our shipping policy</a></div></details>\n  {% endif %}\n  {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Returns</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/returns\">Read our returns policy</a></div></details>\n  {% endif %}\n  </div>\n  </div>\n  {% assign mg_excerpt_allowed = false %}{% if product.books.excerpt.permission == 'merchant_owned' or product.books.excerpt.permission == 'licensed' or product.books.excerpt.permission == 'public_domain' %}{% assign mg_excerpt_allowed = true %}{% endif %}{% if mg_excerpt_allowed and section.settings.showExcerpt and product.books.kind == 'book' and product.books.excerpt.text != blank and product.books.excerpt.permission != blank and product.books.excerpt.attribution != blank %}<section class=\"mg-reading\" id=\"reading-sample\" aria-label=\"Reading sample\"><span class=\"mg-eyebrow\">A little before you begin</span><h2>Read a sample</h2><blockquote>{{ product.books.excerpt.text }}</blockquote><cite>{{ product.books.excerpt.attribution }}</cite></section>{% endif %}\n  {% if section.settings.showReviews and product.reviews.size > 0 %}<div class=\"lb-product-reviews\" data-section-id=\"{{ section.id }}-reviews\">\n    <h2 class=\"lb-product-reviews__title\">Customer reviews ({{ product.review_count }})</h2>\n    {% for review in product.reviews %}<article class=\"lb-product-review\">\n      <header class=\"lb-product-review__head\"><strong class=\"lb-product-review__author\">{{ review.author }}</strong><span class=\"lb-product-review__stars\" aria-label=\"Rated {{ review.rating }} out of 5\">★ {{ review.rating }}</span>{% if review.is_verified %}<span class=\"lb-product-review__verified\">Verified purchase</span>{% endif %}</header>\n      {% if review.title %}<h3 class=\"lb-product-review__heading\">{{ review.title }}</h3>{% endif %}\n      {% if review.body %}<p class=\"lb-product-review__body\">{{ review.body }}</p>{% endif %}\n      {% if review.helpful_count > 0 %}<footer class=\"lb-product-review__helpful\">{{ review.helpful_count }} found this helpful</footer>{% endif %}\n    </article>{% endfor %}\n  </div>{% endif %}\n  {% if section.settings.showReviews %}<lb-review-form data-lb-island=\"review-form\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\"></lb-review-form>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Product Detail\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show gallery\",\n      \"default\": true,\n      \"id\": \"showGallery\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show description\",\n      \"default\": true,\n      \"id\": \"showDescription\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show reviews\",\n      \"default\": true,\n      \"id\": \"showReviews\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show book and paper facts\",\n      \"default\": true,\n      \"id\": \"showBookFacts\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show permitted reading sample\",\n      \"default\": true,\n      \"id\": \"showExcerpt\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Product Detail\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"product-grid":{"path":"sections/product-grid.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Reading shelf","presets":[{"blocks":[],"name":"Reading shelf","settings":{}}],"settings":[{"default":"A little further along the shelf","id":"title","label":"Heading","type":"text"},{"default":"","id":"subtitle","label":"Description","type":"text"},{"default":3,"id":"columns","label":"Desktop columns","max":4,"min":2,"step":1,"type":"range"},{"default":6,"id":"productLimit","label":"Products to show","max":24,"min":1,"step":1,"type":"range"},{"id":"collectionId","label":"Collection","type":"collection"}],"tag":"section"},"source":"<section class=\"mg-theme\" data-section-id=\"{{ section.id }}\">{% if section.settings.requireSelection != true or section.products.size > 0 %}<div class=\"mg-wrap mg-section\"><div class=\"mg-heading\"><div><h2>{{ section.settings.title }}</h2>{% if section.settings.subtitle != blank %}<p>{{ section.settings.subtitle }}</p>{% endif %}</div></div>{% assign mg_products = section.products %}{% if section.settings.requireSelection != true and section.settings.collectionId == blank %}{% assign mg_products = section.products | default: collection.products %}{% endif %}{% if mg_products.size > 0 %}<div class=\"mg-shelf\" data-columns=\"{{ section.settings.columns }}\">{% for item in mg_products limit: section.settings.productLimit %}<article class=\"mg-book-row\" data-product-kind=\"{{ item.books.kind }}\"><a class=\"mg-cover\" href=\"{{ item.url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\" width=\"208\" height=\"312\">{% else %}<span class=\"mg-missing\">Image not supplied</span>{% endif %}</a><div class=\"mg-bibliography\"><h3><a href=\"{{ item.url }}\">{{ item.title }}</a></h3>{% if item.books.kind == 'book' %}{% if item.books_display.authors != blank %}<p class=\"mg-author\">{{ item.books_display.authors }}</p>{% elsif item.books.authors.size > 0 %}<p class=\"mg-author\">{{ item.books.authors | join: ', ' }}</p>{% endif %}{% if item.books_display.multiple_editions or item.variants.size > 1 %}<p>Multiple editions — check language and format</p>{% else %}<p>{% if item.books_display.language != blank or item.books.language != blank %}{{ item.books_display.language | default: item.books.language }}{% endif %}{% if item.books_display.format != blank or item.books.format != blank %} · {{ item.books_display.format | default: item.books.format | replace: '-', ' ' }}{% endif %}{% if item.books_display.edition != blank or item.books.edition != blank %} · {{ item.books_display.edition | default: item.books.edition }}{% endif %}</p>{% endif %}{% elsif item.books.kind == 'stationery' %}<p>{% if item.books.paper_gsm %}{{ item.books.paper_gsm }} gsm{% endif %}{% if item.books_display.dimensions != blank %} · {{ item.books_display.dimensions }}{% elsif item.books.dimensions_mm %} · {{ item.books.dimensions_mm.width }} × {{ item.books.dimensions_mm.height }} mm{% endif %}</p><p>{% if item.books.page_count %}{{ item.books.page_count }} pages{% endif %}{% if item.books.sheet_count %} / {{ item.books.sheet_count }} sheets{% endif %}{% if item.books.ruling %} · {{ item.books.ruling }}{% endif %}</p>{% endif %}{% if item.available == false %}<p class=\"mg-availability\">Currently unavailable</p>{% endif %}</div><div class=\"mg-row-end\"><strong class=\"mg-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"mg-link\" href=\"{{ item.url }}\">{% if item.books.kind == 'book' and item.books_display.multiple_editions %}View editions{% elsif item.has_options or item.options.size > 0 %}View options{% else %}View details{% endif %} <span aria-hidden=\"true\">→</span></a></div></article>{% endfor %}</div>{% else %}<p class=\"mg-empty\">Products added to this collection will appear here.</p>{% endif %}</div>{% endif %}</section>\n{% schema %}\n{\n  \"name\": \"Reading shelf\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"A little further along the shelf\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Desktop columns\",\n      \"default\": 3,\n      \"min\": 2,\n      \"max\": 4,\n      \"step\": 1,\n      \"id\": \"columns\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Products to show\",\n      \"default\": 6,\n      \"min\": 1,\n      \"max\": 24,\n      \"step\": 1,\n      \"id\": \"productLimit\"\n    },\n    {\n      \"type\": \