  }\n}\n{% endschema %}"},"about-section":{"path":"sections/about-section.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Connection education","presets":[{"blocks":[],"name":"Connection education","settings":{}}],"settings":[{"default":"Same connector. Different capabilities.","id":"title","label":"Heading","type":"text"},{"default":"Connector shape alone does not establish device compatibility.","id":"content","label":"Description","type":"text"},{"default":"Find the exact model","id":"stepTitle1","label":"Step 1 heading","type":"text"},{"default":"Use the complete device model identifier.","id":"stepText1","label":"Step 1 text","type":"text"},{"default":"Check the required feature","id":"stepTitle2","label":"Step 2 heading","type":"text"},{"default":"Display, data and power are separate capabilities.","id":"stepText2","label":"Step 2 text","type":"text"},{"default":"Read the reference","id":"stepTitle3","label":"Step 3 heading","type":"text"},{"default":"No model reference means compatibility is unconfirmed.","id":"stepText3","label":"Step 3 text","type":"text"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap ct-section\"><div class=\"ct-education\"><div><h2>{{ section.settings.title }}</h2><p>{{ section.settings.content }}</p></div><div class=\"ct-steps\"><article class=\"ct-step\"><span class=\"ct-eyebrow\">01</span><h3>{{ section.settings.stepTitle1 }}</h3><p>{{ section.settings.stepText1 }}</p></article><article class=\"ct-step\"><span class=\"ct-eyebrow\">02</span><h3>{{ section.settings.stepTitle2 }}</h3><p>{{ section.settings.stepText2 }}</p></article><article class=\"ct-step\"><span class=\"ct-eyebrow\">03</span><h3>{{ section.settings.stepTitle3 }}</h3><p>{{ section.settings.stepText3 }}</p></article></div></div></div></section>\n{% schema %}\n{\n  \"name\": \"Connection education\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Same connector. Different capabilities.\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"Connector shape alone does not establish device compatibility.\",\n      \"id\": \"content\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 1 heading\",\n      \"default\": \"Find the exact model\",\n      \"id\": \"stepTitle1\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 1 text\",\n      \"default\": \"Use the complete device model identifier.\",\n      \"id\": \"stepText1\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 2 heading\",\n      \"default\": \"Check the required feature\",\n      \"id\": \"stepTitle2\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 2 text\",\n      \"default\": \"Display, data and power are separate capabilities.\",\n      \"id\": \"stepText2\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 3 heading\",\n      \"default\": \"Read the reference\",\n      \"id\": \"stepTitle3\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Step 3 text\",\n      \"default\": \"No model reference means compatibility is unconfirmed.\",\n      \"id\": \"stepText3\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Connection education\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"announcement-bar":{"path":"sections/announcement-bar.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["header"],"templates":["*"]},"name":"Announcement Bar","presets":[{"blocks":[],"name":"Announcement Bar","settings":{}}],"settings":[{"default":"Discover our latest products.","id":"text","label":"Message","type":"text"},{"default":"Shop now","id":"linkLabel","label":"Link label","type":"text"},{"default":"/products","id":"linkHref","label":"Link URL","type":"url"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-announcement-bar\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-announcement-bar__inner\">\n    <span>{{ section.settings.text }}</span>\n    {% if section.settings.linkLabel != blank and section.settings.linkHref != blank %}<a href=\"{{ section.settings.linkHref | store_url }}\">{{ section.settings.linkLabel }}</a>{% endif %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Announcement Bar\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Message\",\n      \"default\": \"Discover our latest products.\",\n      \"id\": \"text\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Link label\",\n      \"default\": \"Shop now\",\n      \"id\": \"linkLabel\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Link URL\",\n      \"default\": \"/products\",\n      \"id\": \"linkHref\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Announcement Bar\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"header\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"app-block-slot":{"path":"sections/app-block-slot.liquid","schema":{"blocks":[{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"App Block Slot","presets":[{"blocks":[],"name":"App Block Slot","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":"storefront.home.after-hero","id":"slot","label":"Slot","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-app-block-slot\" data-section-id=\"{{ section.id }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  {% for block in section.blocks %}{{ block.content | raw }}{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"App Block Slot\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Slot\",\n      \"default\": \"storefront.home.after-hero\",\n      \"id\": \"slot\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"@app\",\n      \"name\": \"App block\",\n      \"settings\": []\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"App Block Slot\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"article-content":{"path":"sections/article-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Article Content","presets":[{"blocks":[],"name":"Article Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-article\" data-section-id=\"{{ section.id }}\">\n  {% if article %}\n  <h1 class=\"lb-article__title\">{{ article.title }}</h1>\n  {% if article.published_at %}<time class=\"lb-article__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n  {% if article.image %}<img class=\"lb-article__image\" src=\"{{ article.image | image_url }}\" alt=\"{{ article.title }}\">{% endif %}\n  {% if article.body_html != blank %}<div class=\"lb-article__body\">{{ article.body_html | raw }}</div>{% endif %}\n  {% else %}\n  <p class=\"lb-article__missing\">Article not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Article Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Article Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"banner-carousel":{"path":"sections/banner-carousel.liquid","schema":{"blocks":[{"name":"Slide","settings":[{"id":"heading","label":"Heading","type":"text"},{"id":"image","label":"Image","type":"image"},{"id":"link","label":"Link","type":"url"}],"type":"slide"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Banner Carousel","presets":[{"blocks":[],"name":"Banner Carousel","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"default":true,"id":"autoplay","label":"Autoplay","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-banner-carousel\" data-section-id=\"{{ section.id }}\" data-autoplay=\"{{ section.settings.autoplay }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  <div class=\"lb-banner-carousel__slides\">\n    {% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.link | store_url }}\">{% if block.settings.image %}<img src=\"{{ block.settings.image | image_url }}\" alt=\"{{ block.settings.heading }}\">{% endif %}<h3>{{ block.settings.heading }}</h3>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Banner Carousel\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Autoplay\",\n      \"default\": true,\n      \"id\": \"autoplay\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"slide\",\n      \"name\": \"Slide\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Heading\",\n          \"id\": \"heading\"\n        },\n        {\n          \"type\": \"image\",\n          \"label\": \"Image\",\n          \"id\": \"image\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link\",\n          \"id\": \"link\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Banner Carousel\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"blog-listing":{"path":"sections/blog-listing.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Blog Listing","presets":[{"blocks":[],"name":"Blog Listing","settings":{}}],"settings":[{"default":"Our Blog","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-blog-listing\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-blog-listing__heading\">{{ section.settings.heading }}</h1>\n  {% if blog.articles and blog.articles.size > 0 %}\n  <div class=\"lb-blog-listing__articles\">\n    {% for article in blog.articles %}\n    <article class=\"lb-blog-article-card\">\n      <h2 class=\"lb-blog-article-card__title\"><a href=\"{{ routes.blog_url }}/{{ article.slug }}\">{{ article.title }}</a></h2>\n      {% if article.excerpt %}<p class=\"lb-blog-article-card__excerpt\">{{ article.excerpt }}</p>{% endif %}\n      {% if article.published_at %}<time class=\"lb-blog-article-card__date\" datetime=\"{{ article.published_at }}\">{{ article.published_at | date: \"%B %-d, %Y\" }}</time>{% endif %}\n    </article>\n    {% endfor %}\n  </div>\n  {% if blog.pages_count and blog.pages_count > 1 %}\n  <nav class=\"lb-blog-listing__pagination\" aria-label=\"Blog pagination\">\n    {% if blog.current_page and blog.current_page > 1 %}<a class=\"lb-blog-listing__prev\" href=\"{{ routes.blog_url }}?page={{ blog.current_page | minus: 1 }}\" rel=\"prev\">Previous</a>{% endif %}\n    {% assign next_page = blog.current_page | plus: 1 %}\n    {% if next_page <= blog.pages_count %}<a class=\"lb-blog-listing__next\" href=\"{{ routes.blog_url }}?page={{ next_page }}\" rel=\"next\">Next</a>{% endif %}\n  </nav>\n  {% endif %}\n  {% else %}\n  <p class=\"lb-blog-listing__empty\">No posts published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Blog Listing\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Our Blog\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Blog Listing\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"brand-marquee":{"path":"sections/brand-marquee.liquid","schema":{"blocks":[{"name":"Brand","settings":[{"id":"name","label":"Name","type":"text"}],"type":"brand"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Brand Marquee","presets":[{"blocks":[],"name":"Brand Marquee","settings":{}}],"settings":[{"default":"Featured brands","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-brand-marquee\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <div>{% for block in section.blocks %}<span {{ block.editor_attributes | raw }}>{{ block.settings.name }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>{% endfor %}</div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Brand Marquee\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Featured brands\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"brand\",\n      \"name\": \"Brand\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Name\",\n          \"id\": \"name\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Brand Marquee\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"cart-summary":{"path":"sections/cart-summary.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Cart","presets":[{"blocks":[],"name":"Cart","settings":{}}],"settings":[{"default":"Your cart","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-cart-page\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <lb-cart data-lb-island=\"cart\" data-base-path=\"/store/{{ shop.subdomain }}\">\n    {% if cart.item_count > 0 %}\n    <ul class=\"lb-cart__items\">{% for item in cart.items %}<li class=\"lb-cart__item\"><span class=\"lb-cart__title\">{{ item.title }}</span><span class=\"lb-cart__qty\">x{{ item.quantity }}</span><span class=\"lb-cart__line\">{{ item.line_price | money_with_currency: cart.currency }}</span></li>{% endfor %}</ul>\n    <div class=\"lb-liquid-cart__totals\">\n      {% if cart.subtotal %}<div class=\"lb-liquid-cart__row\"><span>Subtotal</span><span>{{ cart.subtotal | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.coupon_codes.size > 0 %}<div class=\"lb-liquid-cart__row\"><span>Coupons</span><span>{{ cart.coupon_codes | join: \", \" }}</span></div>{% endif %}\n      {% if cart.discount_total %}<div class=\"lb-liquid-cart__row\"><span>Discounts</span><span>{{ cart.discount_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.shipping_total %}<div class=\"lb-liquid-cart__row\"><span>Shipping</span><span>{{ cart.shipping_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n      {% if cart.tax_total %}<div class=\"lb-liquid-cart__row\"><span>Tax (GST)</span><span>{{ cart.tax_total | money_with_currency: cart.currency }}</span></div>{% endif %}\n    </div>\n    <p class=\"lb-cart__total\">Total: {{ cart.total_price | money_with_currency: cart.currency }}</p>\n    <a class=\"lb-cart__checkout\" href=\"{{ cart.checkout_url }}\">Checkout</a>\n    {% else %}<p class=\"lb-cart__empty\">Your cart is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>{% endif %}\n  </lb-cart>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Cart\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your cart\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Cart\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"category-grid":{"path":"sections/category-grid.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Task and category discovery","presets":[{"blocks":[],"name":"Task and category discovery","settings":{}}],"settings":[{"default":"What do you need to connect?","id":"title","label":"Heading","type":"text"},{"default":"Start with the task. Finish with the right model.","id":"subtitle","label":"Description","type":"text"},{"default":"Charge","id":"label1","label":"Task label 1","type":"text"},{"id":"collection1","label":"Task collection 1","type":"collection"},{"default":"Connect","id":"label2","label":"Task label 2","type":"text"},{"id":"collection2","label":"Task collection 2","type":"collection"},{"default":"Listen","id":"label3","label":"Task label 3","type":"text"},{"id":"collection3","label":"Task collection 3","type":"collection"},{"default":"Work","id":"label4","label":"Task label 4","type":"text"},{"id":"collection4","label":"Task collection 4","type":"collection"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap ct-section\"><p class=\"ct-eyebrow\">Electronics, made legible</p><h1>{{ section.settings.title }}</h1>{% if section.settings.subtitle != blank %}<p>{{ section.settings.subtitle }}</p>{% endif %}<div class=\"ct-tasks\">{% if section.settings.collection1 != blank or section.settings.collection2 != blank or section.settings.collection3 != blank or section.settings.collection4 != blank %}{% if section.settings.collection1 != blank %}{% for item in collections limit: 100 %}{% if item.id == section.settings.collection1 %}<a class=\"ct-task\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><h3>{{ section.settings.label1 | default: item.title }}</h3><p>{{ item.title }} →</p></a>{% endif %}{% endfor %}{% endif %}{% if section.settings.collection2 != blank %}{% for item in collections limit: 100 %}{% if item.id == section.settings.collection2 %}<a class=\"ct-task\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><h3>{{ section.settings.label2 | default: item.title }}</h3><p>{{ item.title }} →</p></a>{% endif %}{% endfor %}{% endif %}{% if section.settings.collection3 != blank %}{% for item in collections limit: 100 %}{% if item.id == section.settings.collection3 %}<a class=\"ct-task\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><h3>{{ section.settings.label3 | default: item.title }}</h3><p>{{ item.title }} →</p></a>{% endif %}{% endfor %}{% endif %}{% if section.settings.collection4 != blank %}{% for item in collections limit: 100 %}{% if item.id == section.settings.collection4 %}<a class=\"ct-task\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><h3>{{ section.settings.label4 | default: item.title }}</h3><p>{{ item.title }} →</p></a>{% endif %}{% endfor %}{% endif %}{% else %}{% for item in collections limit: 8 %}<a class=\"ct-task\" href=\"{{ routes.collections_url }}/{{ item.handle }}\"><h3>{{ item.title }}</h3><p>Explore collection →</p></a>{% endfor %}{% endif %}</div>{% if collections.size == 0 %}<p>Collections added to this store will appear here.</p>{% endif %}</div></section>\n{% schema %}\n{\n  \"name\": \"Task and category discovery\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"What do you need to connect?\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"Start with the task. Finish with the right model.\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Task label 1\",\n      \"default\": \"Charge\",\n      \"id\": \"label1\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Task collection 1\",\n      \"id\": \"collection1\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Task label 2\",\n      \"default\": \"Connect\",\n      \"id\": \"label2\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Task collection 2\",\n      \"id\": \"collection2\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Task label 3\",\n      \"default\": \"Listen\",\n      \"id\": \"label3\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Task collection 3\",\n      \"id\": \"collection3\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Task label 4\",\n      \"default\": \"Work\",\n      \"id\": \"label4\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Task collection 4\",\n      \"id\": \"collection4\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Task and category discovery\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-banner":{"path":"sections/collection-banner.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Collection Banner","presets":[{"blocks":[],"name":"Collection Banner","settings":{}}],"settings":[{"default":true,"id":"showDescription","label":"Show description","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-collection-banner\" data-section-id=\"{{ section.id }}\">\n  {% if collection.image_url != blank %}<img class=\"lb-collection-banner__image\" src=\"{{ collection.image_url | image_url }}\" alt=\"{{ collection.title }}\">{% endif %}\n  <h1>{{ collection.title }}</h1>\n  {% if collection.products.size > 0 %}<p class=\"lb-collection-banner__count\">{{ collection.products.size }} products</p>{% endif %}\n  {% if section.settings.showDescription and collection.description %}<div class=\"lb-collection-banner__desc\">{{ collection.description }}</div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Collection Banner\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show description\",\n      \"default\": true,\n      \"id\": \"showDescription\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Collection Banner\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-filter":{"path":"sections/collection-filter.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Electronics discovery heading","presets":[{"blocks":[],"name":"Electronics discovery heading","settings":{}}],"settings":[{"default":"The connection desk","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Accessories","id":"title","label":"Heading","type":"text"},{"default":"Search products, models, connectors","id":"placeholder","label":"Search placeholder","type":"text"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap ct-section ct-intro\"><p class=\"ct-eyebrow\">{{ section.settings.eyebrow }}</p><h1>{{ collection.title | default: section.settings.title }}</h1>{% if collection.total != nil %}<p>{{ collection.total }} products</p>{% endif %}<form class=\"ct-search\" role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\">{% for field in collection.discovery_query_fields %}{% unless field.key == 'page' or field.key == 'search' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}<label class=\"lb-sr-only\" for=\"ct-search-{{ section.id }}\">Search products, models and connectors</label><input type=\"search\" id=\"ct-search-{{ section.id }}\" name=\"search\" maxlength=\"200\" value=\"{{ search.terms }}\" placeholder=\"{{ section.settings.placeholder }}\"><button class=\"ct-button\" type=\"submit\">Search</button></form>{% if search.terms != blank %}<p>Results for “{{ search.terms }}”</p>{% endif %}</div></section>\n{% schema %}\n{\n  \"name\": \"Electronics discovery heading\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Eyebrow\",\n      \"default\": \"The connection desk\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Accessories\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Search placeholder\",\n      \"default\": \"Search products, models, connectors\",\n      \"id\": \"placeholder\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Electronics discovery heading\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"collection-product-list":{"path":"sections/collection-product-list.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Electronics results with facets","presets":[{"blocks":[],"name":"Electronics results with facets","settings":{}}],"settings":[{"default":"","id":"title","label":"Heading","type":"text"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap ct-section ct-catalog-layout{% unless collection.capabilities.electronics_filters == true and collection.electronics_facets.size > 0 %} ct-no-facets{% endunless %}\">{% if collection.capabilities.electronics_filters == true and collection.electronics_facets.size > 0 %}<aside class=\"ct-desktop-facets\"><form class=\"ct-facets\" method=\"get\" action=\"{{ request.path | store_url }}\"><h2>Filter accessories</h2>{% for field in collection.discovery_query_fields %}{% assign ct_edited = false %}{% for facet in collection.electronics_facets %}{% if facet.key == field.key %}{% assign ct_edited = true %}{% endif %}{% endfor %}{% unless ct_edited or field.key == 'page' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}{% assign ct_keys = collection.electronics_facets | map: 'key' | uniq %}{% for key in ct_keys %}{% assign ct_choices = collection.electronics_facets | where: 'key', key %}<fieldset><legend>{{ ct_choices.first.group_label }}</legend>{% unless key == 'connector' %}{% assign ct_selected = false %}{% for choice in ct_choices %}{% if choice.selected %}{% assign ct_selected = true %}{% endif %}{% endfor %}<label><input type=\"radio\" name=\"{{ key }}\" value=\"\"{% unless ct_selected %} checked{% endunless %}>Any</label>{% endunless %}{% for facet in ct_choices %}<label><input type=\"{% if key == 'connector' %}checkbox{% else %}radio{% endif %}\" name=\"{{ key }}\" value=\"{{ facet.value }}\"{% if facet.selected %} checked{% endif %}>{{ facet.label }} {% if facet.count != nil %}<span aria-hidden=\"true\">{{ facet.count }}</span><span class=\"lb-sr-only\"> ({{ facet.count }} matching product{% unless facet.count == 1 %}s{% endunless %})</span>{% endif %}</label>{% endfor %}</fieldset>{% endfor %}<button class=\"ct-button\" type=\"submit\">Apply filters</button>{% if collection.clear_filters_url != blank %}<a class=\"ct-link\" href=\"{{ collection.clear_filters_url | store_url }}\">Clear filters</a>{% endif %}</form></aside>{% endif %}<div>{% if section.settings.title != blank %}<h2>{{ section.settings.title }}</h2>{% endif %}{% if collection.sort_options.size > 0 %}<form class=\"ct-sort\" method=\"get\" action=\"{{ request.path | store_url }}\">{% for field in collection.discovery_query_fields %}{% unless field.key == 'page' or field.key == 'sort' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}<label for=\"ct-sort-{{ section.id }}\">Sort by</label><select id=\"ct-sort-{{ section.id }}\" name=\"sort\">{% for option in collection.sort_options %}<option value=\"{{ option.value }}\"{% if option.selected %} selected{% endif %}>{{ option.label }}</option>{% endfor %}</select><button class=\"ct-button\" type=\"submit\">Sort</button></form>{% endif %}{% if collection.active_filters.size > 0 %}<nav class=\"ct-active-filters\" aria-label=\"Applied filters\">{% for filter in collection.active_filters %}<a class=\"ct-link\" href=\"{{ filter.clear_url | store_url }}\" aria-label=\"Remove {{ filter.label }}\">{{ filter.label }} ×</a>{% endfor %}</nav>{% endif %}{% if collection.capabilities.electronics_filters == true and collection.electronics_facets.size > 0 %}<details class=\"ct-mobile-facets\"><summary>Filter accessories</summary><form class=\"ct-facets\" method=\"get\" action=\"{{ request.path | store_url }}\"><h2>Filter accessories</h2>{% for field in collection.discovery_query_fields %}{% assign ct_edited = false %}{% for facet in collection.electronics_facets %}{% if facet.key == field.key %}{% assign ct_edited = true %}{% endif %}{% endfor %}{% unless ct_edited or field.key == 'page' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}{% assign ct_keys = collection.electronics_facets | map: 'key' | uniq %}{% for key in ct_keys %}{% assign ct_choices = collection.electronics_facets | where: 'key', key %}<fieldset><legend>{{ ct_choices.first.group_label }}</legend>{% unless key == 'connector' %}{% assign ct_selected = false %}{% for choice in ct_choices %}{% if choice.selected %}{% assign ct_selected = true %}{% endif %}{% endfor %}<label><input type=\"radio\" name=\"{{ key }}\" value=\"\"{% unless ct_selected %} checked{% endunless %}>Any</label>{% endunless %}{% for facet in ct_choices %}<label><input type=\"{% if key == 'connector' %}checkbox{% else %}radio{% endif %}\" name=\"{{ key }}\" value=\"{{ facet.value }}\"{% if facet.selected %} checked{% endif %}>{{ facet.label }} {% if facet.count != nil %}<span aria-hidden=\"true\">{{ facet.count }}</span><span class=\"lb-sr-only\"> ({{ facet.count }} matching product{% unless facet.count == 1 %}s{% endunless %})</span>{% endif %}</label>{% endfor %}</fieldset>{% endfor %}<button class=\"ct-button\" type=\"submit\">Apply filters</button>{% if collection.clear_filters_url != blank %}<a class=\"ct-link\" href=\"{{ collection.clear_filters_url | store_url }}\">Clear filters</a>{% endif %}</form></details>{% endif %}{% if collection.products.size > 0 %}<div class=\"ct-grid ct-collection-grid\">{% for item in collection.products %}<article class=\"ct-card\"><a class=\"ct-card-media\" href=\"{{ item.url | store_url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"ct-card-placeholder\">Product image not supplied</span>{% endif %}</a><div class=\"ct-card-body\">{% if item.electronics.manufacturer != blank or item.electronics.model != blank %}<p class=\"ct-card-model\">{{ item.electronics.manufacturer }}{% if item.electronics.model != blank %} · {{ item.electronics.model }}{% endif %}</p>{% endif %}<h3><a href=\"{{ item.url | store_url }}\">{{ item.title }}</a></h3>{% if item.electronics %}<dl class=\"ct-card-facts\">{% if item.electronics_video_summary != blank %}<div><dt>Video</dt><dd>{{ item.electronics_video_summary }}</dd></div>{% elsif item.electronics.video %}<div><dt>Video</dt><dd>{{ item.electronics.video.width_px }} × {{ item.electronics.video.height_px }} / {{ item.electronics.video.refresh_hz }} Hz</dd></div>{% elsif item.electronics.power_output_w %}<div><dt>Output maximum</dt><dd>{{ item.electronics.power_output_w }} W</dd></div>{% elsif item.electronics.power_capacity_w %}<div><dt>Cable power capacity</dt><dd>{{ item.electronics.power_capacity_w }} W</dd></div>{% elsif item.electronics.power_input_w %}<div><dt>Input maximum</dt><dd>{{ item.electronics.power_input_w }} W</dd></div>{% endif %}{% if item.electronics.data_rate_mbps %}<div><dt>USB data maximum</dt><dd>{{ item.electronics.data_rate_mbps }} Mb/s</dd></div>{% elsif item.electronics.length_mm %}<div><dt>Length</dt><dd>{{ item.electronics.length_mm }} mm</dd></div>{% elsif item.electronics_output_connector_summary != blank %}<div><dt>Power outputs</dt><dd>{{ item.electronics_output_connector_summary }}</dd></div>{% endif %}</dl>{% else %}<p class=\"ct-card-status\">Technical facts not supplied</p>{% endif %}<div class=\"ct-card-bottom\"><strong class=\"ct-card-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"ct-link\" href=\"{{ item.url | store_url }}\">{% if item.options.size > 0 %}Choose options{% else %}View product{% endif %} →</a></div>{% if item.available == false %}<p class=\"ct-card-status\">Unavailable</p>{% elsif item.available == true %}<p class=\"ct-card-status\">Available</p>{% endif %}</div></article>{% endfor %}</div>{% else %}<div class=\"ct-empty\"><h2>No products match this selection.</h2><p>Your query is kept above. Try another model or a broader category.</p><a class=\"ct-link\" href=\"{{ routes.all_products_collection_url | default: routes.search_url }}\">Explore all products</a></div>{% endif %}<nav class=\"ct-pagination\" aria-label=\"Product pages\">{% if collection.pagination.previous_url != blank %}<a class=\"ct-link\" href=\"{{ collection.pagination.previous_url | store_url }}\">← Previous</a>{% endif %}{% if collection.pagination.page != nil %}<span>Page {{ collection.pagination.page }}{% if collection.pagination.pages != nil %} of {{ collection.pagination.pages }}{% endif %}</span>{% endif %}{% if collection.pagination.next_url != blank %}<a class=\"ct-link\" href=\"{{ collection.pagination.next_url | store_url }}\">Next →</a>{% endif %}</nav></div></div></section>\n{% schema %}\n{\n  \"name\": \"Electronics results with facets\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Electronics results with facets\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"contact-form":{"path":"sections/contact-form.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Contact Form","presets":[{"blocks":[],"name":"Contact Form","settings":{}}],"settings":[{"default":"Contact us","id":"title","label":"Title","type":"text"},{"id":"subtitle","label":"Subtitle","type":"text"},{"default":true,"id":"showPhone","label":"Show phone field","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-contact-form\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\"><input name=\"name\" aria-label=\"Name\"><input type=\"email\" name=\"email\" aria-label=\"Email\">{% if section.settings.showPhone %}<input name=\"phone\" aria-label=\"Phone\">{% endif %}<button type=\"submit\">Send</button></form>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Contact Form\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Contact us\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subtitle\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show phone field\",\n      \"default\": true,\n      \"id\": \"showPhone\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Contact Form\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"cta-section":{"path":"sections/cta-section.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Call to Action","presets":[{"blocks":[],"name":"Call to Action","settings":{}}],"settings":[{"default":"Ready to get started?","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"},{"default":"Shop now","id":"ctaText","label":"Button text","type":"text"},{"default":"/products","id":"ctaLink","label":"Button link","type":"url"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-cta-section\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.heading }}</h2>\n  <p>{{ section.settings.subheading }}</p>\n  <a href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }}</a>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Call to Action\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Ready to get started?\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subheading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Button text\",\n      \"default\": \"Shop now\",\n      \"id\": \"ctaText\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Button link\",\n      \"default\": \"/products\",\n      \"id\": \"ctaLink\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Call to Action\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-account":{"path":"sections/customer-account.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Account","presets":[{"blocks":[],"name":"Customer Account","settings":{}}],"settings":[{"default":"Your account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-account\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in to LetBuyy as {{ buyer.full_name | default: buyer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_url }}/loyalty\">Rewards</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><form method=\"post\" action=\"/api/buyer-auth/logout?return_to={{ routes.account_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out at this store</button></form></nav>\n  {% elsif buyer_unavailable %}<p class=\"lb-account__unavailable\" role=\"status\">We could not load your LetBuyy account right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <p class=\"lb-account__hello\">Signed in as {{ customer.name | default: customer.email }}</p>\n  <nav class=\"lb-account__nav\"><a href=\"{{ routes.account_orders_url }}\">Orders</a><a href=\"{{ routes.account_addresses_url }}\">Addresses</a><a href=\"{{ routes.account_settings_url }}\">Settings</a><lb-logout data-logout-url=\"{{ routes.account_logout_url }}\"><form method=\"post\" action=\"{{ routes.account_logout_url }}\"><button type=\"submit\" class=\"lb-account__nav-link\">Sign out</button></form></lb-logout></nav>\n  {% else %}\n  <p class=\"lb-account__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your account.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Customer Account\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your account\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Account\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-addresses":{"path":"sections/customer-addresses.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Addresses","presets":[{"blocks":[],"name":"Addresses","settings":{}}],"settings":[{"default":"Your addresses","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-addresses\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer %}\n  <lb-address-manager data-lb-island=\"address-manager\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-address-manager>\n  {% elsif buyer_unavailable %}<p class=\"lb-addresses__unavailable\" role=\"status\">We could not load your LetBuyy addresses right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  {% if customer.addresses and customer.addresses.size > 0 %}\n  <div class=\"lb-addresses__grid\">\n    {% for addr in customer.addresses %}<div class=\"lb-address-card{% if addr.is_default %} lb-address-card--default{% endif %}\"><span class=\"lb-address-card__label\">{{ addr.label | default: \"address\" }}</span>{% if addr.is_default %}<span class=\"lb-address-card__default-badge\">Default</span>{% endif %}<p class=\"lb-address-card__address\">{{ addr.address1 }}{% if addr.address2 %}, {{ addr.address2 }}{% endif %}</p><p class=\"lb-address-card__city\">{{ addr.city }}, {{ addr.province }} {{ addr.zip }}</p></div>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-addresses__empty\">No saved addresses.</p>\n  {% endif %}\n  <lb-address-manager\n    data-lb-island=\"address-manager\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-address-manager>\n  {% else %}\n  <p class=\"lb-addresses__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your addresses.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Addresses\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your addresses\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Addresses\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-login":{"path":"sections/customer-login.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Login","presets":[{"blocks":[],"name":"Customer Login","settings":{}}],"settings":[{"default":"Sign in","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<section class=\"lb-auth lb-auth--login\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if request.error %}<p class=\"lb-auth__error\" role=\"alert\">{% case request.error %}{% when \"missing_fields\" %}Please fill in all required fields.{% when \"invalid_credentials\" %}Incorrect email or password.{% when \"account_exists\" %}An account with this email already exists. Please sign in.{% when \"rate_limited\" %}Too many attempts. Please try again shortly.{% when \"bot_verification\" %}We could not verify you are not a robot. Please try again.{% else %}Something went wrong. Please try again.{% endcase %}</p>{% endif %}\n  <form class=\"lb-auth__form\" method=\"post\" action=\"/api/customer/login\">\n    <input type=\"hidden\" name=\"storeId\" value=\"{{ shop.id }}\">\n    <input type=\"hidden\" name=\"turnstileToken\" value=\"\">\n    <lb-turnstile data-lb-island=\"turnstile\"></lb-turnstile>\n    <label>Email<input type=\"email\" name=\"email\" autocomplete=\"email\" required></label>\n    <label>Password<input type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\">Sign in</button>\n  </form>\n  <a href=\"{{ routes.customer_register_url }}\">Create an account</a>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Continue with LetBuyy</a></p>\n  <p>Have an older store account? Connect it with your verified LetBuyy account.</p>\n  <form class=\"lb-auth__link-store\" method=\"post\" action=\"/api/buyer-auth/start\">\n    <input type=\"hidden\" name=\"intent\" value=\"link_store_customer\">\n    <input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_url }}\">\n    <button type=\"submit\">Connect my store account</button>\n  </form>\n</section>\n{% schema %}\n{\n  \"name\": \"Customer Login\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Sign in\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Login\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-order-detail":{"path":"sections/customer-order-detail.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Order Detail","presets":[{"blocks":[],"name":"Order Detail","settings":{}}],"settings":[{"default":"Order","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-order-detail\" data-section-id=\"{{ section.id }}\">\n  {% if buyer_unavailable %}<p class=\"lb-order-detail__error\" role=\"alert\">This order is temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  {% if order %}\n  <h1>{{ section.settings.heading | strip | default: 'Order' }} #{{ order.number }}</h1>\n  <p class=\"lb-order-detail__status\">Status: {{ order.status }}</p>\n  <ul class=\"lb-order-detail__items\">{% for item in order.line_items %}<li><span class=\"lb-order-detail__title\">{{ item.title }}</span><span class=\"lb-order-detail__qty\">{{ item.quantity }}</span><span class=\"lb-order-detail__line\">{{ item.line_price | money_with_currency: order.currency }}</span><!-- lb:niche-order-presentation:v1 -->{% if item.niche_facts_text != blank %}<details class=\"lb-order-facts\"><summary>Saved product details</summary><p class=\"lb-order-facts__text\">{{ item.niche_facts_text }}</p></details>{% else %}<p class=\"lb-order-facts__missing\">Product details were not recorded with this order.</p>{% endif %}</li>{% endfor %}</ul>\n  <p class=\"lb-order-detail__total\">Total: {{ order.total | money_with_currency: order.currency }}</p>\n  {% if order.gst_invoice_number != blank %}<p class=\"lb-order-detail__invoice\">GST Invoice: {{ order.gst_invoice_number }} (Tax: {{ order.tax_total | money_with_currency: order.currency }})</p>{% endif %}\n  <ol class=\"lb-order-detail__timeline\">{% for step in order.timeline %}<li class=\"lb-order-detail__step{% if step.reached %} is-reached{% endif %}\">{{ step.label }}</li>{% endfor %}</ol>\n  {% if order.tracking_number != blank %}<p class=\"lb-order-detail__tracking\">Tracking: {{ order.tracking_number }}{% if order.carrier != blank %} ({{ order.carrier }}){% endif %}</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__missing\">Order not found.</p>{% endif %}\n  {% else %}<p class=\"lb-order-detail__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view this order.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Order Detail\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Order\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Order Detail\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-orders":{"path":"sections/customer-orders.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Order History","presets":[{"blocks":[],"name":"Order History","settings":{}}],"settings":[{"default":"Your orders","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-orders\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  {% if buyer_unavailable %}<p class=\"lb-orders__error\" role=\"alert\">Orders are temporarily unavailable. Please try again.</p>{% elsif buyer %}\n  <form class=\"lb-orders__claim\" method=\"post\" action=\"/api/buyer/orders\"><input type=\"hidden\" name=\"return_to\" value=\"{{ routes.account_orders_url }}\"><p>Find past orders from this store placed with your verified LetBuyy email.</p><button type=\"submit\">Find past orders</button></form>\n  {% if request.query.buyer_claim == \"complete\" %}<p role=\"status\" aria-live=\"polite\">The verified orders for this store have been checked and linked.</p>{% elsif request.query.buyer_claim == \"partial\" %}<p role=\"status\" aria-live=\"polite\">Some eligible orders could not be linked. Contact the store for help.</p>{% elsif request.query.buyer_claim == \"unverified\" %}<p role=\"status\" aria-live=\"polite\">Verify your LetBuyy email before claiming historical orders.</p>{% elsif request.query.buyer_claim == \"unavailable\" %}<p role=\"status\" aria-live=\"polite\">Historical orders could not be checked right now. Please try again.</p>{% elsif request.query.buyer_claim == \"unauthorized\" %}<p role=\"status\" aria-live=\"polite\">Sign in to LetBuyy before claiming past orders.</p>{% endif %}\n  {% if buyer.orders and buyer.orders.size > 0 %}\n  <ul class=\"lb-orders__list\">{% for order in buyer.orders %}<li class=\"lb-orders__row\"><a href=\"{{ routes.account_orders_url }}/{{ order.id }}\"><span class=\"lb-orders__num\">#{{ order.number }}</span><span class=\"lb-orders__status\">{{ order.status }}</span><span class=\"lb-orders__total\">{{ order.total | money_with_currency: order.currency }}</span></a></li>{% endfor %}</ul>\n  {% if buyer.has_more and buyer.next_cursor %}<a class=\"lb-orders__next\" href=\"{{ routes.account_orders_url }}?cursor={{ buyer.next_cursor }}\">Older orders</a>{% endif %}\n  {% else %}<p class=\"lb-orders__empty\">No orders yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-orders__guest\">Please <a href=\"/api/buyer-auth/start?return_to={{ routes.account_orders_url }}\">sign in with LetBuyy</a> to view your orders.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Order History\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your orders\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Order History\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-register":{"path":"sections/customer-register.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Customer Register","presets":[{"blocks":[],"name":"Customer Register","settings":{}}],"settings":[{"default":"Create account","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<section class=\"lb-auth lb-auth--register\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}</h1>\n  <p>Create one LetBuyy account to use across participating storefronts.</p>\n  <p class=\"lb-auth__letbuyy\"><a href=\"/api/buyer-auth/start?return_to={{ routes.account_url }}\">Create or sign in with LetBuyy</a></p>\n  <p>Have an older store-only account? <a href=\"{{ routes.customer_login_url }}\">Sign in to connect it with your verified LetBuyy account</a>.</p>\n</section>\n{% schema %}\n{\n  \"name\": \"Customer Register\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Create account\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Customer Register\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-settings":{"path":"sections/customer-settings.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Account Settings","presets":[{"blocks":[],"name":"Account Settings","settings":{}}],"settings":[{"default":"Account settings","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-settings\" data-section-id=\"{{ section.id }}\">\n  {% if buyer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\"><p class=\"lb-settings__email\">{{ buyer.email }}</p>{% if buyer.full_name %}<p class=\"lb-settings__name\">{{ buyer.full_name }}</p>{% endif %}{% if buyer.phone %}<p class=\"lb-settings__phone\">{{ buyer.phone }}</p>{% endif %}</div>\n  <lb-customer-settings data-lb-island=\"customer-settings\" data-account-type=\"buyer\" data-base-path=\"/store/{{ shop.subdomain }}\" data-authenticated=\"true\"></lb-customer-settings>\n  {% elsif buyer_unavailable %}<p class=\"lb-settings__unavailable\" role=\"status\">We could not load your LetBuyy profile right now. Please refresh and try again.</p>\n  {% elsif customer %}\n  <h1>{{ section.settings.heading }}</h1>\n  <div class=\"lb-settings__current\">\n    <p class=\"lb-settings__email\">{{ customer.email }}</p>\n    {% if customer.name %}<p class=\"lb-settings__name\">{{ customer.name }}</p>{% endif %}\n    {% if customer.phone %}<p class=\"lb-settings__phone\">{{ customer.phone }}</p>{% endif %}\n  </div>\n  <lb-customer-settings\n    data-lb-island=\"customer-settings\"\n    data-email=\"{{ customer.email | escape }}\"\n    data-name=\"{{ customer.name | default: \"\" | escape }}\"\n    data-phone=\"{{ customer.phone | default: \"\" | escape }}\"\n    data-base-path=\"/store/{{ shop.subdomain }}\"\n    data-authenticated=\"true\"\n  ></lb-customer-settings>\n  {% else %}\n  <p class=\"lb-settings__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to manage your settings.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Account Settings\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Account settings\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Account Settings\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"customer-wishlist":{"path":"sections/customer-wishlist.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Wishlist","presets":[{"blocks":[],"name":"Wishlist","settings":{}}],"settings":[{"default":"Your wishlist","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-wishlist\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.heading }}{% if customer.wishlist_products.size > 0 %} <span class=\"lb-wishlist__count\">({{ customer.wishlist_products.size }})</span>{% elsif buyer_wishlist.products.size > 0 %} <span class=\"lb-wishlist__count\">({{ buyer_wishlist.products.size }})</span>{% endif %}</h1>\n  {% if buyer_wishlist.authenticated %}\n    {% if buyer_wishlist.unavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">Your wishlist is temporarily unavailable. Please try again.</p>\n    {% elsif buyer_wishlist.storeAccountUnavailable %}<p class=\"lb-wishlist__unavailable\" role=\"status\">This store account is unavailable. Contact the store for help.</p>\n    {% elsif buyer_wishlist.linked and buyer_wishlist.products.size > 0 %}\n      <div class=\"lb-product-grid__items\">{% for item in buyer_wishlist.products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"true\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}</div>\n    {% elsif buyer_wishlist.linked %}<p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n    {% else %}<p class=\"lb-wishlist__guest\">Connect your verified store account in <a href=\"{{ routes.account_settings_url }}\">account settings</a> to use this store wishlist.</p>{% endif %}\n  {% elsif customer.wishlist_products and customer.wishlist_products.size > 0 %}\n  <div class=\"lb-product-grid__items\">\n    {% for item in customer.wishlist_products %}<article class=\"lb-product-card\"><a href=\"{{ item.url }}\"><strong>{{ item.title }}</strong><span>{{ item.price | times: 100 | money_with_currency: item.currency }}</span></a><lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ item.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"true\" data-authenticated=\"true\" data-account-type=\"store_customer\" data-base-path=\"/store/{{ shop.subdomain }}\"></lb-wishlist-toggle></article>{% endfor %}\n  </div>\n  {% elsif customer %}\n  <p class=\"lb-wishlist__empty\">Your wishlist is empty. <a href=\"{{ routes.all_products_collection_url }}\">Browse products</a></p>\n  {% else %}\n  <p class=\"lb-wishlist__guest\">Please <a href=\"{{ routes.customer_login_url }}\">sign in</a> to view your wishlist.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Wishlist\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Your wishlist\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Wishlist\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"experience-timeline":{"path":"sections/experience-timeline.liquid","schema":{"blocks":[{"name":"Experience","settings":[{"id":"title","label":"Title","type":"text"},{"id":"company","label":"Company","type":"text"},{"id":"period","label":"Period","type":"text"}],"type":"experience"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Experience Timeline","presets":[{"blocks":[],"name":"Experience Timeline","settings":{}}],"settings":[{"default":"Experience","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-experience-timeline\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.company }}</p><time>{{ block.settings.period }}</time>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Experience Timeline\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Experience\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"experience\",\n      \"name\": \"Experience\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"id\": \"title\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Company\",\n          \"id\": \"company\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Period\",\n          \"id\": \"period\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Experience Timeline\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"faq-accordion":{"path":"sections/faq-accordion.liquid","schema":{"blocks":[{"name":"FAQ item","settings":[{"id":"question","label":"Question","type":"text"},{"id":"answer","label":"Answer","type":"richtext"}],"type":"faq-item"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"FAQ Accordion","presets":[{"blocks":[],"name":"FAQ Accordion","settings":{}}],"settings":[{"default":"Frequently asked questions","id":"title","label":"Title","type":"text"},{"default":false,"id":"allowMultipleOpen","label":"Allow multiple open","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-faq-accordion\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}\n  <div class=\"lb-faq-accordion__items\">\n    {% for block in section.blocks %}<details {{ block.editor_attributes | raw }} class=\"lb-faq-accordion__item\"{% unless section.settings.allowMultipleOpen %} name=\"lb-faq-{{ section.id }}\"{% endunless %}><summary class=\"lb-faq-accordion__question\">{{ block.settings.question }}</summary><div class=\"lb-faq-accordion__answer\">{{ block.settings.answer }}</div>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</details>{% endfor %}\n  </div>\n  {% else %}\n  <p class=\"lb-faq-accordion__empty\">No questions published yet.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"FAQ Accordion\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Frequently asked questions\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Allow multiple open\",\n      \"default\": false,\n      \"id\": \"allowMultipleOpen\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"faq-item\",\n      \"name\": \"FAQ item\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Question\",\n          \"id\": \"question\"\n        },\n        {\n          \"type\": \"richtext\",\n          \"label\": \"Answer\",\n          \"id\": \"answer\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"FAQ Accordion\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"featured-products":{"path":"sections/featured-products.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Independently sold accessories","presets":[{"blocks":[],"name":"Independently sold accessories","settings":{}}],"settings":[{"default":"Useful additions. Separate purchases.","id":"title","label":"Heading","type":"text"},{"default":"Check each product’s own specifications and availability.","id":"subtitle","label":"Description","type":"text"},{"default":true,"id":"requireSelection","label":"Only show selected products","type":"toggle"},{"id":"product1","label":"Related product 1","type":"product"},{"id":"product2","label":"Related product 2","type":"product"},{"id":"product3","label":"Related product 3","type":"product"},{"default":3,"id":"productLimit","label":"Products to show","max":8,"min":1,"step":1,"type":"range"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\">{% if section.products.size > 0 %}<div class=\"ct-wrap ct-section\"><h2>{{ section.settings.title }}</h2><p>{{ section.settings.subtitle }}</p><div class=\"ct-grid\">{% for item in section.products limit: section.settings.productLimit %}<article class=\"ct-card\"><a class=\"ct-card-media\" href=\"{{ item.url | store_url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"ct-card-placeholder\">Product image not supplied</span>{% endif %}</a><div class=\"ct-card-body\">{% if item.electronics.manufacturer != blank or item.electronics.model != blank %}<p class=\"ct-card-model\">{{ item.electronics.manufacturer }}{% if item.electronics.model != blank %} · {{ item.electronics.model }}{% endif %}</p>{% endif %}<h3><a href=\"{{ item.url | store_url }}\">{{ item.title }}</a></h3>{% if item.electronics %}<dl class=\"ct-card-facts\">{% if item.electronics_video_summary != blank %}<div><dt>Video</dt><dd>{{ item.electronics_video_summary }}</dd></div>{% elsif item.electronics.video %}<div><dt>Video</dt><dd>{{ item.electronics.video.width_px }} × {{ item.electronics.video.height_px }} / {{ item.electronics.video.refresh_hz }} Hz</dd></div>{% elsif item.electronics.power_output_w %}<div><dt>Output maximum</dt><dd>{{ item.electronics.power_output_w }} W</dd></div>{% elsif item.electronics.power_capacity_w %}<div><dt>Cable power capacity</dt><dd>{{ item.electronics.power_capacity_w }} W</dd></div>{% elsif item.electronics.power_input_w %}<div><dt>Input maximum</dt><dd>{{ item.electronics.power_input_w }} W</dd></div>{% endif %}{% if item.electronics.data_rate_mbps %}<div><dt>USB data maximum</dt><dd>{{ item.electronics.data_rate_mbps }} Mb/s</dd></div>{% elsif item.electronics.length_mm %}<div><dt>Length</dt><dd>{{ item.electronics.length_mm }} mm</dd></div>{% elsif item.electronics_output_connector_summary != blank %}<div><dt>Power outputs</dt><dd>{{ item.electronics_output_connector_summary }}</dd></div>{% endif %}</dl>{% else %}<p class=\"ct-card-status\">Technical facts not supplied</p>{% endif %}<div class=\"ct-card-bottom\"><strong class=\"ct-card-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"ct-link\" href=\"{{ item.url | store_url }}\">{% if item.options.size > 0 %}Choose options{% else %}View product{% endif %} →</a></div>{% if item.available == false %}<p class=\"ct-card-status\">Unavailable</p>{% elsif item.available == true %}<p class=\"ct-card-status\">Available</p>{% endif %}</div></article>{% endfor %}</div></div>{% endif %}</section>\n{% schema %}\n{\n  \"name\": \"Independently sold accessories\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Useful additions. Separate purchases.\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"Check each product’s own specifications and availability.\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Only show selected products\",\n      \"default\": true,\n      \"id\": \"requireSelection\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Related product 1\",\n      \"id\": \"product1\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Related product 2\",\n      \"id\": \"product2\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Related product 3\",\n      \"id\": \"product3\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Products to show\",\n      \"default\": 3,\n      \"min\": 1,\n      \"max\": 8,\n      \"step\": 1,\n      \"id\": \"productLimit\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Independently sold accessories\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"footer":{"path":"sections/footer.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["footer"],"templates":["*"]},"limit":1,"name":"Footer","presets":[{"blocks":[],"name":"Footer","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"id":"tagline","label":"Tagline","type":"text"},{"id":"contactEmail","label":"Contact email","type":"text"},{"id":"contactPhone","label":"Contact phone","type":"text"},{"id":"instagramUrl","label":"Instagram URL","type":"url"},{"id":"facebookUrl","label":"Facebook URL","type":"url"},{"id":"twitterUrl","label":"Twitter/X URL","type":"url"}],"tag":"section"},"source":"<div class=\"ct-theme\"><footer class=\"lb-footer\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-footer__grid\">\n    <div class=\"lb-footer__brand\">\n      <h3>{{ section.settings.storeName | default: shop.name }}</h3>\n      {% if section.settings.tagline %}<p>{{ section.settings.tagline }}</p>{% endif %}\n      {% if section.settings.instagramUrl != blank or section.settings.facebookUrl != blank or section.settings.twitterUrl != blank %}\n      <div class=\"lb-footer__social\">\n        {% if section.settings.instagramUrl != blank %}<a href=\"{{ section.settings.instagramUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Instagram\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\" ry=\"5\"></rect><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><circle cx=\"17.5\" cy=\"6.5\" r=\"1\"></circle></svg></a>{% endif %}\n        {% if section.settings.facebookUrl != blank %}<a href=\"{{ section.settings.facebookUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Facebook\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M15 4h-2a4 4 0 0 0-4 4v3H6v4h3v7h4v-7h3l1-4h-4V8a1 1 0 0 1 1-1h3z\"></path></svg></a>{% endif %}\n        {% if section.settings.twitterUrl != blank %}<a href=\"{{ section.settings.twitterUrl }}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Twitter/X\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"4\" y1=\"4\" x2=\"20\" y2=\"20\"></line><line x1=\"20\" y1=\"4\" x2=\"4\" y2=\"20\"></line></svg></a>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if section.blocks.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}</nav></div>\n    {% elsif linklists.footer_menu.links.size > 0 %}\n    <div class=\"lb-footer__col\"><h4>Quick links</h4><nav>{% for link in linklists.footer_menu.links %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endfor %}</nav></div>\n    {% endif %}\n    {% if shop.policies.size > 0 %}<div class=\"lb-footer__col\">\n      <h4>Policies</h4>\n      <nav>\n        {% if shop.policies contains 'privacy' %}<a href=\"{{ routes.root_url }}/privacy\">Privacy policy</a>{% endif %}\n        {% if shop.policies contains 'terms' %}<a href=\"{{ routes.root_url }}/terms\">Terms of service</a>{% endif %}\n        {% if shop.policies contains 'shipping' %}<a href=\"{{ routes.root_url }}/shipping\">Shipping policy</a>{% endif %}\n        {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}<a href=\"{{ routes.root_url }}/returns\">Returns policy</a>{% endif %}\n      </nav>\n    </div>{% endif %}\n    <div class=\"lb-footer__col\">\n      <h4>Contact</h4>\n      {% if section.settings.contactEmail != blank %}<p><a href=\"mailto:{{ section.settings.contactEmail }}\">{{ section.settings.contactEmail }}</a></p>{% endif %}\n      {% if section.settings.contactPhone != blank %}<p><a href=\"tel:{{ section.settings.contactPhone }}\">{{ section.settings.contactPhone }}</a></p>{% endif %}\n      <a href=\"{{ routes.contact_url }}\">Contact us</a>\n    </div>\n  </div>\n  <div class=\"lb-footer__bottom\">\n    <p>&copy; {{ shop.name }}. All rights reserved.</p>\n    <a class=\"lb-footer__watermark\" href=\"https://letbuyy.com\" target=\"_blank\" rel=\"noopener noreferrer\">Powered by LetBuyy</a>\n  </div>\n</footer>\n</div>\n{% schema %}\n{\n  \"name\": \"Footer\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Store name\",\n      \"id\": \"storeName\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Tagline\",\n      \"id\": \"tagline\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Contact email\",\n      \"id\": \"contactEmail\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Contact phone\",\n      \"id\": \"contactPhone\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Instagram URL\",\n      \"id\": \"instagramUrl\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Facebook URL\",\n      \"id\": \"facebookUrl\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Twitter/X URL\",\n      \"id\": \"twitterUrl\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"id\": \"label\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"URL\",\n          \"id\": \"href\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Footer\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"footer\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  },\n  \"limit\": 1\n}\n{% endschema %}"},"header":{"path":"sections/header.liquid","schema":{"blocks":[{"name":"Link","settings":[{"id":"label","label":"Label","type":"text"},{"id":"href","label":"URL","type":"url"}],"type":"link"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["header"],"templates":["*"]},"limit":1,"name":"Header","presets":[{"blocks":[],"name":"Header","settings":{}}],"settings":[{"id":"storeName","label":"Store name","type":"text"},{"default":true,"id":"showSearch","label":"Show search","type":"toggle"},{"default":true,"id":"showCart","label":"Show cart","type":"toggle"},{"default":"sticky","id":"behavior","label":"Header behavior","options":["static","sticky"],"type":"select"},{"default":"main_menu","id":"menu","label":"Menu","options":["main_menu","footer_menu","policy_menu"],"type":"select"},{"default":"inline","id":"layout","label":"Layout","options":["inline","centered"],"type":"select"},{"default":true,"id":"showPersistentSearch","label":"Show persistent model search","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><header class=\"lb-header\" data-section-id=\"{{ section.id }}\" data-sticky=\"{% if section.settings.behavior == 'sticky' %}true{% else %}false{% endif %}\" data-layout=\"{{ section.settings.layout | default: 'inline' }}\">\n  <div class=\"lb-header__inner\">\n    <lb-mobile-nav class=\"lb-mobile-nav\" data-lb-island=\"mobile-nav\">\n      <button type=\"button\" class=\"lb-header__toggle\" data-lb-nav-toggle aria-expanded=\"false\" aria-controls=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg><span class=\"lb-sr-only\">Menu</span></button>\n      <nav class=\"lb-header__nav\" data-lb-nav-panel id=\"lb-nav-panel-{{ section.id }}\" aria-label=\"Primary\">\n        <div class=\"lb-header__nav-head\"><span class=\"lb-header__nav-head-brand\">{{ section.settings.storeName | default: shop.name }}</span><button type=\"button\" class=\"lb-header__nav-close\" data-lb-nav-close aria-label=\"Close menu\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close menu</span></button></div>\n        <div class=\"lb-header__nav-links\">\n        {% if section.blocks.size > 0 %}\n          {% for block in section.blocks %}<a {{ block.editor_attributes | raw }} href=\"{{ block.settings.href | store_url }}\">{{ block.settings.label }}{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</a>{% endfor %}\n        {% else %}\n          {% assign lb_menu_handle = section.settings.menu | default: 'main_menu' %}\n          {% assign lb_nav_links = linklists[lb_menu_handle].links %}\n          {% for link in lb_nav_links %}\n            {% if link.links.size > 0 %}\n            <details class=\"lb-header__nav-item\" data-lb-nav-dropdown><summary{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\" class=\"lb-icon-chevron\"><path d=\"M6 9l6 6 6-6\"></path></svg></summary>\n              <div class=\"lb-header__nav-submenu\">{% for child in link.links %}<a href=\"{{ child.url | store_url }}\"{% if child.active %} aria-current=\"page\"{% endif %}>{{ child.title }}</a>{% endfor %}</div>\n            </details>\n            {% else %}<a href=\"{{ link.url | store_url }}\"{% if link.active %} aria-current=\"page\"{% endif %}>{{ link.title }}</a>{% endif %}\n          {% endfor %}\n        {% endif %}\n        </div>\n        <div class=\"lb-header__nav-foot\">\n          {% if customer %}<a href=\"{{ routes.account_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Account</span></a>{% else %}<a href=\"{{ routes.customer_login_url }}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span>Log in</span></a>{% endif %}\n        </div>\n      </nav>\n      <div class=\"lb-header__scrim\" data-lb-nav-scrim></div>\n    </lb-mobile-nav>\n    <a class=\"lb-header__brand\" href=\"{{ routes.root_url }}\">\n      {% if shop.logo_url %}<img class=\"lb-header__logo\" src=\"{{ shop.logo_url | image_url }}\" alt=\"{{ section.settings.storeName | default: shop.name }}\">{% else %}{{ section.settings.storeName | default: shop.name }}{% endif %}\n    </a>\n{% if section.settings.showPersistentSearch %}<form class=\"ct-header-search\" role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\">{% for field in collection.discovery_query_fields %}{% unless field.key == 'page' or field.key == 'search' %}<input type=\"hidden\" name=\"{{ field.key }}\" value=\"{{ field.value }}\">{% endunless %}{% endfor %}<label class=\"lb-sr-only\" for=\"ct-header-search-{{ section.id }}\">Search products, models and connectors</label><input id=\"ct-header-search-{{ section.id }}\" type=\"search\" name=\"search\" value=\"{{ search.terms }}\" placeholder=\"Search products, models, connectors\" maxlength=\"200\"><button type=\"submit\">Search</button></form>{% endif %}\n    <div class=\"lb-header__actions\">\n      {% if section.settings.showSearch %}<button type=\"button\" class=\"lb-header__search-toggle\" data-lb-search-toggle aria-expanded=\"false\" aria-controls=\"lb-search-overlay-{{ section.id }}\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>{% endif %}\n      <a class=\"lb-header__account\" href=\"{% if customer %}{{ routes.account_url }}{% else %}{{ routes.customer_login_url }}{% endif %}\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 20c0-4 4-6 8-6s8 2 8 6\"></path></svg><span class=\"lb-sr-only\">{% if customer %}Account{% else %}Log in{% endif %}</span></a>\n      {% if section.settings.showCart %}<a class=\"lb-header__cart\" href=\"{{ routes.cart_url }}\" data-lb-cart-trigger><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M3 4h2l2 12h11l2-8H6\"></path><circle cx=\"9\" cy=\"20\" r=\"1\"></circle><circle cx=\"17\" cy=\"20\" r=\"1\"></circle></svg><span class=\"lb-sr-only\">{{ \"general.cart\" | t }}</span> (<span data-lb-cart-count>{{ cart.item_count | default: 0 }}</span>)</a>{% endif %}\n    </div>\n  </div>\n  {% if section.settings.showSearch %}\n  <div class=\"lb-header__search-overlay\" id=\"lb-search-overlay-{{ section.id }}\" data-lb-search-overlay hidden>\n    <lb-predictive-search class=\"lb-predictive-search\" data-lb-island=\"predictive-search\" data-search-url=\"{{ routes.search_url }}\">\n      <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n        <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n        <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"Search products\" autocomplete=\"off\" role=\"combobox\" aria-expanded=\"false\" aria-controls=\"lb-search-results-{{ section.id }}\" aria-autocomplete=\"list\">\n        <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n        <button type=\"button\" data-lb-search-close aria-label=\"Close search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><line x1=\"5\" y1=\"5\" x2=\"19\" y2=\"19\"></line><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"></line></svg><span class=\"lb-sr-only\">Close search</span></button>\n      </form>\n      <div id=\"lb-search-results-{{ section.id }}\" class=\"lb-predictive-search__results\" data-lb-search-results role=\"listbox\" aria-live=\"polite\"></div>\n    </lb-predictive-search>\n  </div>\n  {% endif %}\n</header>\n</div>\n{% schema %}\n{\n  \"name\": \"Header\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Store name\",\n      \"id\": \"storeName\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show search\",\n      \"default\": true,\n      \"id\": \"showSearch\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show cart\",\n      \"default\": true,\n      \"id\": \"showCart\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Header behavior\",\n      \"default\": \"sticky\",\n      \"options\": [\n        \"static\",\n        \"sticky\"\n      ],\n      \"id\": \"behavior\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Menu\",\n      \"default\": \"main_menu\",\n      \"options\": [\n        \"main_menu\",\n        \"footer_menu\",\n        \"policy_menu\"\n      ],\n      \"id\": \"menu\"\n    },\n    {\n      \"type\": \"select\",\n      \"label\": \"Layout\",\n      \"default\": \"inline\",\n      \"options\": [\n        \"inline\",\n        \"centered\"\n      ],\n      \"id\": \"layout\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show persistent model search\",\n      \"default\": true,\n      \"id\": \"showPersistentSearch\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"link\",\n      \"name\": \"Link\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Label\",\n          \"id\": \"label\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"URL\",\n          \"id\": \"href\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Header\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"header\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  },\n  \"limit\": 1\n}\n{% endschema %}"},"hero-banner":{"path":"sections/hero-banner.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Featured model","presets":[{"blocks":[],"name":"Featured model","settings":{}}],"settings":[{"default":"Featured model","id":"eyebrow","label":"Eyebrow","type":"text"},{"default":"Find the right connection.","id":"heading","label":"Heading","type":"text"},{"default":"Read the model, connector roles and required features before choosing.","id":"subheading","label":"Description","type":"text"},{"id":"image","label":"Featured model image","type":"image"},{"id":"product1","label":"Featured product","type":"product"},{"default":"Explore accessories","id":"ctaText","label":"Button text","type":"text"},{"default":"/products","id":"ctaLink","label":"Button destination","type":"url"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap\"><div class=\"ct-feature{% if section.settings.image == blank %} ct-feature-empty{% endif %}\"><div class=\"ct-feature-copy\"><p class=\"ct-eyebrow\">{{ section.settings.eyebrow }}</p><h2>{{ section.settings.heading }}</h2>{% if section.settings.subheading != blank %}<p>{{ section.settings.subheading }}</p>{% endif %}{% assign featured = section.products.first %}{% if featured %}<p>{{ featured.electronics.manufacturer }} {{ featured.electronics.model }} · {{ featured.price | times: 100 | money_with_currency: featured.currency }}</p><a class=\"ct-button\" href=\"{{ featured.url | store_url }}\">View model →</a>{% elsif section.settings.ctaText != blank and section.settings.ctaLink != blank %}<a class=\"ct-button\" href=\"{{ section.settings.ctaLink | store_url }}\">{{ section.settings.ctaText }}</a>{% endif %}</div>{% if section.settings.image != blank %}<div class=\"ct-feature-media\"><img src=\"{{ section.settings.image | image_url }}\" alt=\"{{ section.settings.heading }}\" fetchpriority=\"high\" decoding=\"async\"></div>{% endif %}</div></div></section>\n{% schema %}\n{\n  \"name\": \"Featured model\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Eyebrow\",\n      \"default\": \"Featured model\",\n      \"id\": \"eyebrow\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Find the right connection.\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"Read the model, connector roles and required features before choosing.\",\n      \"id\": \"subheading\"\n    },\n    {\n      \"type\": \"image\",\n      \"label\": \"Featured model image\",\n      \"id\": \"image\"\n    },\n    {\n      \"type\": \"product\",\n      \"label\": \"Featured product\",\n      \"id\": \"product1\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Button text\",\n      \"default\": \"Explore accessories\",\n      \"id\": \"ctaText\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Button destination\",\n      \"default\": \"/products\",\n      \"id\": \"ctaLink\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Featured model\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"marquee":{"path":"sections/marquee.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Marquee","presets":[{"blocks":[],"name":"Marquee","settings":{}}],"settings":[{"default":"Featured announcement","id":"text","label":"Text","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-marquee\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.text }}</p>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Marquee\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Text\",\n      \"default\": \"Featured announcement\",\n      \"id\": \"text\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Marquee\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"newsletter-signup":{"path":"sections/newsletter-signup.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template","footer"],"templates":["*"]},"name":"Newsletter Signup","presets":[{"blocks":[],"name":"Newsletter Signup","settings":{}}],"settings":[{"default":"Get first access","id":"title","label":"Heading","type":"text"},{"id":"subtitle","label":"Subheading","type":"text"},{"default":"Sign up","id":"buttonLabel","label":"Button label","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-newsletter-signup\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  <p>{{ section.settings.subtitle }}</p>\n  <form action=\"/contact\" method=\"post\">\n    <input type=\"email\" name=\"email\" aria-label=\"Email\" required>\n    <button type=\"submit\">{{ section.settings.buttonLabel }}</button>\n  </form>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Newsletter Signup\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Get first access\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Button label\",\n      \"default\": \"Sign up\",\n      \"id\": \"buttonLabel\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Newsletter Signup\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\",\n      \"footer\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"page-content":{"path":"sections/page-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Page Content","presets":[{"blocks":[],"name":"Page Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-page\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-page__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-page__body\">{{ page.body_html | raw }}</div>\n  {% else %}<p class=\"lb-page__empty\">No content yet.</p>{% endif %}\n  {% else %}\n  <p class=\"lb-page__missing\">Page not found.</p>\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Page Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Page Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"password-gate":{"path":"sections/password-gate.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Password Gate","presets":[{"blocks":[],"name":"Password Gate","settings":{}}],"settings":[{"default":"Coming Soon","id":"heading","label":"Heading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><!-- password gate rendering requires proxy routing update (Phase F) -->\n<section class=\"lb-password-gate\" data-section-id=\"{{ section.id }}\">\n  <h1 class=\"lb-password-gate__heading\">{{ shop.name }}</h1>\n  <p class=\"lb-password-gate__message\">{{ section.settings.heading }}</p>\n  <p class=\"lb-password-gate__info\">This store is password protected.</p>\n  <form class=\"lb-password-gate__form\" method=\"post\" action=\"/store-access/password\">\n    <label class=\"lb-password-gate__label\">Enter password<input class=\"lb-password-gate__input\" type=\"password\" name=\"password\" autocomplete=\"current-password\" required></label>\n    <button type=\"submit\" class=\"lb-password-gate__btn\">Enter</button>\n  </form>\n  {% if shop.access_message and shop.access_message != blank %}<p class=\"lb-password-gate__access-message\">{{ shop.access_message }}</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Password Gate\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Coming Soon\",\n      \"id\": \"heading\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Password Gate\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"policy-content":{"path":"sections/policy-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Policy Content","presets":[{"blocks":[],"name":"Policy Content","settings":{}}],"settings":[],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-policy\" data-section-id=\"{{ section.id }}\">\n  {% if page %}\n  <h1 class=\"lb-policy__title\">{{ page.title }}</h1>\n  {% if page.body_html != blank %}<div class=\"lb-policy__body\">{{ page.body_html | raw }}</div>\n  {% elsif page.content != blank %}<div class=\"lb-policy__body\">{{ page.content | raw }}</div>{% endif %}\n  {% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Policy Content\",\n  \"tag\": \"section\",\n  \"settings\": [],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Policy Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"portfolio-grid":{"path":"sections/portfolio-grid.liquid","schema":{"blocks":[{"name":"Project","settings":[{"id":"title","label":"Title","type":"text"},{"id":"summary","label":"Summary","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"project"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Portfolio Grid","presets":[{"blocks":[],"name":"Portfolio Grid","settings":{}}],"settings":[{"default":"Portfolio","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-portfolio-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.summary }}</p><a href=\"{{ block.settings.link | store_url }}\">View</a>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Portfolio Grid\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Portfolio\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"project\",\n      \"name\": \"Project\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"id\": \"title\"\n        },\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Summary\",\n          \"id\": \"summary\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link\",\n          \"id\": \"link\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Portfolio Grid\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"product-detail":{"path":"sections/product-detail.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Product Detail","presets":[{"blocks":[],"name":"Product Detail","settings":{}}],"settings":[{"default":true,"id":"showGallery","label":"Show gallery","type":"toggle"},{"default":true,"id":"showDescription","label":"Show description","type":"toggle"},{"default":true,"id":"showReviews","label":"Show reviews","type":"toggle"},{"default":true,"id":"showElectronicsFacts","label":"Show specifications and compatibility","type":"toggle"},{"default":false,"id":"showBuyNow","label":"Show buy now","type":"toggle"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-product-detail\" data-section-id=\"{{ section.id }}\">\n  <nav class=\"lb-product-detail__breadcrumb\" aria-label=\"Breadcrumb\">\n    <a href=\"{{ routes.root_url }}\">Home</a>\n    <a href=\"{{ routes.all_products_collection_url }}\">Shop</a>\n    <span aria-current=\"page\">{{ product.title }}</span>\n  </nav>\n  <div class=\"lb-product-detail__layout\">\n  {% if section.settings.showGallery and product.images.size > 0 %}\n  <lb-product-gallery class=\"lb-product-detail__gallery\" data-lb-island=\"product-gallery\">\n    <div class=\"lb-product-detail__gallery-main\">\n      {% for image in product.images %}<img class=\"lb-product-detail__gallery-image\" src=\"{{ image | image_url }}\" alt=\"{{ product.title }}\" data-lb-gallery-image data-index=\"{{ forloop.index0 }}\"{% unless forloop.first %} hidden{% endunless %} loading=\"{% if forloop.first %}eager{% else %}lazy{% endif %}\" decoding=\"async\">{% endfor %}\n    </div>\n    {% if product.images.size > 1 %}\n    <div class=\"lb-product-detail__gallery-thumbs\" role=\"tablist\" aria-label=\"Product images\">\n      {% for image in product.images %}<button type=\"button\" class=\"lb-product-detail__gallery-thumb\" data-lb-gallery-thumb data-index=\"{{ forloop.index0 }}\" role=\"tab\" aria-selected=\"{% if forloop.first %}true{% else %}false{% endif %}\" tabindex=\"{% if forloop.first %}0{% else %}-1{% endif %}\" aria-label=\"Image {{ forloop.index }} of {{ product.images.size }}\"><img src=\"{{ image | image_url }}\" alt=\"\" aria-hidden=\"true\" loading=\"lazy\" decoding=\"async\"></button>{% endfor %}\n    </div>\n    {% endif %}\n  </lb-product-gallery>\n  {% endif %}\n  <div class=\"lb-product-detail__info\">\n  <h1>{{ product.title }}</h1>\n  {% if product.review_count > 0 %}<p class=\"lb-product-detail__rating\" aria-label=\"Rated {{ product.rating }} out of 5\">★ {{ product.rating }} <span class=\"lb-product-detail__rating-count\">({{ product.review_count }})</span></p>{% endif %}\n  <div class=\"lb-product-detail__price\">\n    <span class=\"lb-product-detail__price-current\">{{ product.price | times: 100 | money_with_currency: product.currency }}</span>\n    {% if product.compare_at_price and product.compare_at_price > product.price %}\n    <s class=\"lb-product-detail__price-compare\">{{ product.compare_at_price | times: 100 | money_with_currency: product.currency }}</s>\n    <span class=\"lb-product-detail__price-save\">Save {{ product.compare_at_price | minus: product.price | times: 100.0 | divided_by: product.compare_at_price | round }}%</span>\n    {% endif %}\n  </div>\n  {% if product.options.size > 0 %}<lb-variant-picker data-lb-island=\"variant-picker\" data-product-id=\"{{ product.id }}\" data-variants=\"{{ product.variants | json }}\" class=\"lb-product-detail__variants\">{% for option in product.options %}<div class=\"lb-product-detail__variant-group\"><span class=\"lb-variant-option__name\">{{ option.name }}</span><div class=\"lb-product-detail__variant-values\">{% for value in option.values %}<button type=\"button\" data-lb-variant-option data-variant-name=\"{{ option.name }}\" data-variant-value=\"{{ value }}\" aria-pressed=\"false\">{{ value }}</button>{% endfor %}</div></div>{% endfor %}<p class=\"lb-product-detail__variant-status\" data-lb-variant-status role=\"status\"></p></lb-variant-picker>{% endif %}\n{% if section.settings.showElectronicsFacts %}<div class=\"ct-compatibility\"><h2>Device compatibility</h2>{% if product.electronics.compatible_devices.size > 0 %}<p>Merchant-referenced device models. Check the exact model and required features.</p><ul>{% for device in product.electronics.compatible_devices %}<li>{{ device.manufacturer }} · {{ device.model }}<br>Reference: {{ device.reference }} · {{ device.source_date }}</li>{% endfor %}</ul>{% else %}<p><strong>Unconfirmed.</strong> Check your exact device model and host requirements before choosing. A connector match alone does not establish compatibility.</p>{% endif %}<a class=\"ct-link\" href=\"#circuit-specifications\">Read specifications and requirements</a></div>{% endif %}\n  <div class=\"lb-product-detail__purchase\">\n    <lb-add-to-cart data-lb-island=\"add-to-cart\" data-product-id=\"{{ product.id }}\" data-product-name=\"{{ product.title }}\" data-product-price=\"{{ product.price }}\" data-product-currency=\"{{ product.currency }}\" data-product-url=\"{{ product.url }}\">\n      <label class=\"lb-sr-only\" for=\"lb-quantity-{{ section.id }}\">Quantity</label>\n      <input type=\"number\" name=\"quantity\" id=\"lb-quantity-{{ section.id }}\" class=\"lb-product-detail__quantity\" value=\"1\" min=\"1\" inputmode=\"numeric\">\n      <button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--primary\" data-lb-add-to-cart{% if product.available == false %} disabled{% endif %}>{% if product.available == false %}Sold out{% else %}Add to cart{% endif %}</button>\n      {% if section.settings.showBuyNow %}<button type=\"button\" class=\"lb-product-detail__cta lb-product-detail__cta--secondary\" data-lb-buy-now{% if product.available == false %} disabled{% endif %}>Buy now</button>{% endif %}\n      <span data-lb-add-to-cart-status aria-live=\"polite\"></span>\n    </lb-add-to-cart>\n    <lb-wishlist-toggle data-lb-island=\"wishlist-toggle\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\" data-in-wishlist=\"{% if product.in_wishlist %}true{% endif %}\"{% if buyer_wishlist.authenticated %} data-authenticated=\"true\" data-account-type=\"buyer\" data-buyer-id=\"{{ buyer_wishlist.buyerId }}\" data-buyer-linked=\"{% if buyer_wishlist.linked %}true{% endif %}\" data-buyer-unavailable=\"{% if buyer_wishlist.unavailable or buyer_wishlist.storeAccountUnavailable %}true{% endif %}\"{% elsif customer %} data-authenticated=\"true\" data-account-type=\"store_customer\"{% endif %} data-base-path=\"/store/{{ shop.subdomain }}\" aria-label=\"Add {{ product.title }} to wishlist\"></lb-wishlist-toggle>\n  </div>\n  {% if section.settings.showDescription and product.description %}\n  <details class=\"lb-product-detail__accordion\"><summary>Description</summary><div class=\"lb-product-detail__accordion-body\">{{ product.description }}</div></details>\n  {% endif %}\n  {% if shop.policies contains 'shipping' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Shipping</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/shipping\">Read our shipping policy</a></div></details>\n  {% endif %}\n  {% if shop.policies contains 'refund' or shop.policies contains 'returns' %}\n  <details class=\"lb-product-detail__accordion\"><summary>Returns</summary><div class=\"lb-product-detail__accordion-body\"><a href=\"{{ routes.root_url }}/returns\">Read our returns policy</a></div></details>\n  {% endif %}\n  </div>\n  </div>\n{% if section.settings.showElectronicsFacts %}<section class=\"ct-specs\" id=\"circuit-specifications\" aria-label=\"Electronics specifications\"><h2>Know the model. Read the limits.</h2>{% if product.electronics %}<table><caption>Merchant-stated specifications · normalized units</caption><tbody>{% if product.electronics.manufacturer != nil and product.electronics.manufacturer != blank %}<tr><th scope=\"row\">Manufacturer</th><td>{{ product.electronics.manufacturer }} </td></tr>{% endif %}{% if product.electronics.model != nil and product.electronics.model != blank %}<tr><th scope=\"row\">Model</th><td>{{ product.electronics.model }} </td></tr>{% endif %}{% if product.electronics.power_input_w != nil and product.electronics.power_input_w != blank %}<tr><th scope=\"row\">Power input maximum</th><td>{{ product.electronics.power_input_w }} W</td></tr>{% endif %}{% if product.electronics.power_output_w != nil and product.electronics.power_output_w != blank %}<tr><th scope=\"row\">Power output maximum</th><td>{{ product.electronics.power_output_w }} W</td></tr>{% endif %}{% if product.electronics.power_capacity_w != nil and product.electronics.power_capacity_w != blank %}<tr><th scope=\"row\">Cable power capacity maximum</th><td>{{ product.electronics.power_capacity_w }} W</td></tr>{% endif %}{% if product.electronics.pass_through_output_w != nil and product.electronics.pass_through_output_w != blank %}<tr><th scope=\"row\">Laptop pass-through maximum</th><td>{{ product.electronics.pass_through_output_w }} W</td></tr>{% endif %}{% if product.electronics.data_rate_mbps != nil and product.electronics.data_rate_mbps != blank %}<tr><th scope=\"row\">Data transfer maximum</th><td>{{ product.electronics.data_rate_mbps }} Mb/s</td></tr>{% endif %}{% if product.electronics.length_mm != nil and product.electronics.length_mm != blank %}<tr><th scope=\"row\">Cable length</th><td>{{ product.electronics.length_mm }} mm</td></tr>{% endif %}{% if product.electronics.video %}<tr><th scope=\"row\">Video output maximum</th><td>{{ product.electronics.video.width_px }} × {{ product.electronics.video.height_px }} at {{ product.electronics.video.refresh_hz }} Hz</td></tr>{% endif %}{% if product.electronics.dimensions_mm %}<tr><th scope=\"row\">Dimensions (L × W × H)</th><td>{{ product.electronics.dimensions_mm.length }} × {{ product.electronics.dimensions_mm.width }} × {{ product.electronics.dimensions_mm.height }} mm</td></tr>{% endif %}{% for connector in product.electronics.connectors %}<tr><th scope=\"row\">{{ connector.role }}</th><td>{{ connector.count }} × {{ connector.kind }}</td></tr>{% endfor %}</tbody></table>{% if product.electronics.fact_sheet %}<p class=\"ct-fact-note\">Product fact sheet: {{ product.electronics.fact_sheet.reference }} · {{ product.electronics.fact_sheet.source_date }}. This does not establish compatibility with an unnamed device.</p>{% endif %}<p class=\"ct-fact-note\">Power input and laptop pass-through are different measurements. Missing values are not inferred from another field. Maxima are merchant statements, not guaranteed simultaneous output.</p><div class=\"ct-fact-columns\"><div><h3>Host requirements</h3>{% if product.electronics.host_requirements.size > 0 %}<ul>{% for requirement in product.electronics.host_requirements %}<li>{{ requirement }}</li>{% endfor %}</ul>{% else %}<p>Host requirements not supplied.</p>{% endif %}</div><div><h3>What is included</h3>{% if product.electronics.box_contents.size > 0 %}<ul>{% for content in product.electronics.box_contents %}<li>{{ content.quantity }} × {{ content.label }}</li>{% endfor %}</ul>{% else %}<p>Box contents not supplied.</p>{% endif %}</div></div>{% if product.electronics.notes != blank %}<p>{{ product.electronics.notes }}</p>{% endif %}{% else %}<p>Technical facts have not been supplied. Device compatibility remains unconfirmed.</p>{% endif %}</section>{% endif %}\n  {% if section.settings.showReviews and product.reviews.size > 0 %}<div class=\"lb-product-reviews\" data-section-id=\"{{ section.id }}-reviews\">\n    <h2 class=\"lb-product-reviews__title\">Customer reviews ({{ product.review_count }})</h2>\n    {% for review in product.reviews %}<article class=\"lb-product-review\">\n      <header class=\"lb-product-review__head\"><strong class=\"lb-product-review__author\">{{ review.author }}</strong><span class=\"lb-product-review__stars\" aria-label=\"Rated {{ review.rating }} out of 5\">★ {{ review.rating }}</span>{% if review.is_verified %}<span class=\"lb-product-review__verified\">Verified purchase</span>{% endif %}</header>\n      {% if review.title %}<h3 class=\"lb-product-review__heading\">{{ review.title }}</h3>{% endif %}\n      {% if review.body %}<p class=\"lb-product-review__body\">{{ review.body }}</p>{% endif %}\n      {% if review.helpful_count > 0 %}<footer class=\"lb-product-review__helpful\">{{ review.helpful_count }} found this helpful</footer>{% endif %}\n    </article>{% endfor %}\n  </div>{% endif %}\n  {% if section.settings.showReviews %}<lb-review-form data-lb-island=\"review-form\" data-product-id=\"{{ product.id }}\" data-store-id=\"{{ shop.id }}\"></lb-review-form>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Product Detail\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show gallery\",\n      \"default\": true,\n      \"id\": \"showGallery\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show description\",\n      \"default\": true,\n      \"id\": \"showDescription\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show reviews\",\n      \"default\": true,\n      \"id\": \"showReviews\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show specifications and compatibility\",\n      \"default\": true,\n      \"id\": \"showElectronicsFacts\"\n    },\n    {\n      \"type\": \"toggle\",\n      \"label\": \"Show buy now\",\n      \"default\": false,\n      \"id\": \"showBuyNow\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Product Detail\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"product-grid":{"path":"sections/product-grid.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Technical product cards","presets":[{"blocks":[],"name":"Technical product cards","settings":{}}],"settings":[{"default":"Small details. Better decisions.","id":"title","label":"Heading","type":"text"},{"default":"","id":"subtitle","label":"Description","type":"text"},{"default":4,"id":"columns","label":"Desktop columns","max":4,"min":2,"step":1,"type":"range"},{"default":8,"id":"productLimit","label":"Products to show","max":24,"min":1,"step":1,"type":"range"},{"id":"collectionId","label":"Product collection","type":"collection"}],"tag":"section"},"source":"<section class=\"ct-theme\" data-section-id=\"{{ section.id }}\"><div class=\"ct-wrap ct-section\"><div class=\"ct-heading\"><div><h2>{{ section.settings.title }}</h2>{% if section.settings.subtitle != blank %}<p>{{ section.settings.subtitle }}</p>{% endif %}</div></div>{% assign products = section.products | default: collection.products %}{% if products.size > 0 %}<div class=\"ct-grid\" data-columns=\"{{ section.settings.columns }}\">{% for item in products limit: section.settings.productLimit %}<article class=\"ct-card\"><a class=\"ct-card-media\" href=\"{{ item.url | store_url }}\">{% if item.featured_image != blank %}<img src=\"{{ item.featured_image | image_url }}\" alt=\"{{ item.title }}\" loading=\"lazy\" decoding=\"async\">{% else %}<span class=\"ct-card-placeholder\">Product image not supplied</span>{% endif %}</a><div class=\"ct-card-body\">{% if item.electronics.manufacturer != blank or item.electronics.model != blank %}<p class=\"ct-card-model\">{{ item.electronics.manufacturer }}{% if item.electronics.model != blank %} · {{ item.electronics.model }}{% endif %}</p>{% endif %}<h3><a href=\"{{ item.url | store_url }}\">{{ item.title }}</a></h3>{% if item.electronics %}<dl class=\"ct-card-facts\">{% if item.electronics_video_summary != blank %}<div><dt>Video</dt><dd>{{ item.electronics_video_summary }}</dd></div>{% elsif item.electronics.video %}<div><dt>Video</dt><dd>{{ item.electronics.video.width_px }} × {{ item.electronics.video.height_px }} / {{ item.electronics.video.refresh_hz }} Hz</dd></div>{% elsif item.electronics.power_output_w %}<div><dt>Output maximum</dt><dd>{{ item.electronics.power_output_w }} W</dd></div>{% elsif item.electronics.power_capacity_w %}<div><dt>Cable power capacity</dt><dd>{{ item.electronics.power_capacity_w }} W</dd></div>{% elsif item.electronics.power_input_w %}<div><dt>Input maximum</dt><dd>{{ item.electronics.power_input_w }} W</dd></div>{% endif %}{% if item.electronics.data_rate_mbps %}<div><dt>USB data maximum</dt><dd>{{ item.electronics.data_rate_mbps }} Mb/s</dd></div>{% elsif item.electronics.length_mm %}<div><dt>Length</dt><dd>{{ item.electronics.length_mm }} mm</dd></div>{% elsif item.electronics_output_connector_summary != blank %}<div><dt>Power outputs</dt><dd>{{ item.electronics_output_connector_summary }}</dd></div>{% endif %}</dl>{% else %}<p class=\"ct-card-status\">Technical facts not supplied</p>{% endif %}<div class=\"ct-card-bottom\"><strong class=\"ct-card-price\">{{ item.price | times: 100 | money_with_currency: item.currency }}</strong><a class=\"ct-link\" href=\"{{ item.url | store_url }}\">{% if item.options.size > 0 %}Choose options{% else %}View product{% endif %} →</a></div>{% if item.available == false %}<p class=\"ct-card-status\">Unavailable</p>{% elsif item.available == true %}<p class=\"ct-card-status\">Available</p>{% endif %}</div></article>{% endfor %}</div>{% else %}<p class=\"ct-empty\">No products are available in this selection.</p>{% endif %}</div></section>\n{% schema %}\n{\n  \"name\": \"Technical product cards\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Small details. Better decisions.\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Description\",\n      \"default\": \"\",\n      \"id\": \"subtitle\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Desktop columns\",\n      \"default\": 4,\n      \"min\": 2,\n      \"max\": 4,\n      \"step\": 1,\n      \"id\": \"columns\"\n    },\n    {\n      \"type\": \"range\",\n      \"label\": \"Products to show\",\n      \"default\": 8,\n      \"min\": 1,\n      \"max\": 24,\n      \"step\": 1,\n      \"id\": \"productLimit\"\n    },\n    {\n      \"type\": \"collection\",\n      \"label\": \"Product collection\",\n      \"id\": \"collectionId\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Technical product cards\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"rich-content":{"path":"sections/rich-content.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Rich Content","presets":[{"blocks":[],"name":"Rich Content","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"},{"id":"body","label":"Body","type":"richtext"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-rich-content\" data-section-id=\"{{ section.id }}\">\n  <h1>{{ section.settings.title }}</h1>\n  <div>{{ section.settings.body }}</div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Rich Content\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"id\": \"title\"\n    },\n    {\n      \"type\": \"richtext\",\n      \"label\": \"Body\",\n      \"id\": \"body\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Rich Content\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"search-box":{"path":"sections/search-box.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Search","presets":[{"blocks":[],"name":"Search","settings":{}}],"settings":[{"default":"Search products","id":"placeholder","label":"Placeholder","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-search\" data-section-id=\"{{ section.id }}\">\n  <lb-search data-lb-island=\"search\" data-search-url=\"{{ routes.search_url }}\">\n    <form role=\"search\" method=\"get\" action=\"{{ routes.search_url }}\" data-lb-search-form>\n      <label class=\"lb-sr-only\" for=\"lb-search-input-{{ section.id }}\">Search products</label>\n      <input type=\"search\" name=\"search\" id=\"lb-search-input-{{ section.id }}\" data-lb-search-input placeholder=\"{{ section.settings.placeholder }}\" aria-label=\"Search products\" value=\"{{ search.terms }}\">\n      <button type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line></svg><span class=\"lb-sr-only\">Search</span></button>\n    </form>\n  </lb-search>\n  {% if search.terms %}<p class=\"lb-search__terms\">Results for \"{{ search.terms }}\"</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Search\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Placeholder\",\n      \"default\": \"Search products\",\n      \"id\": \"placeholder\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Search\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"services-grid":{"path":"sections/services-grid.liquid","schema":{"blocks":[{"name":"Service","settings":[{"id":"title","label":"Title","type":"text"},{"id":"description","label":"Description","type":"textarea"},{"id":"link","label":"Link","type":"url"}],"type":"service"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Services Grid","presets":[{"blocks":[],"name":"Services Grid","settings":{}}],"settings":[{"default":"Services","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-services-grid\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% for block in section.blocks %}<article {{ block.editor_attributes | raw }}><h3>{{ block.settings.title }}</h3><p>{{ block.settings.description }}</p><a href=\"{{ block.settings.link | store_url }}\">Learn more</a>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Services Grid\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Services\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"service\",\n      \"name\": \"Service\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Title\",\n          \"id\": \"title\"\n        },\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Description\",\n          \"id\": \"description\"\n        },\n        {\n          \"type\": \"url\",\n          \"label\": \"Link\",\n          \"id\": \"link\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Services Grid\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"skills-section":{"path":"sections/skills-section.liquid","schema":{"blocks":[{"name":"Skill","settings":[{"id":"name","label":"Skill","type":"text"},{"id":"level","label":"Level","max":100,"min":0,"step":5,"type":"range"}],"type":"skill"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Skills Section","presets":[{"blocks":[],"name":"Skills Section","settings":{}}],"settings":[{"default":"Skills","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-skills-section\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<h3>General</h3>{% endif %}\n  {% for block in section.blocks %}<span {{ block.editor_attributes | raw }} data-level=\"{{ block.settings.level }}\">{{ block.settings.name }} {{ block.settings.level }}%{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</span>{% endfor %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Skills Section\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"Skills\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"skill\",\n      \"name\": \"Skill\",\n      \"settings\": [\n        {\n          \"type\": \"text\",\n          \"label\": \"Skill\",\n          \"id\": \"name\"\n        },\n        {\n          \"type\": \"range\",\n          \"label\": \"Level\",\n          \"min\": 0,\n          \"max\": 100,\n          \"step\": 5,\n          \"id\": \"level\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Skills Section\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"spotlight":{"path":"sections/spotlight.liquid","schema":{"blocks":[{"name":"Badge","settings":[],"type":"badge"},{"name":"App block","settings":[],"type":"@app"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Spotlight","presets":[{"blocks":[],"name":"Spotlight","settings":{}}],"settings":[{"default":"Made for daily buyers","id":"heading","label":"Heading","type":"text"},{"id":"subheading","label":"Subheading","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-first-party-spotlight\" data-section-id=\"{{ section.id }}\">\n  <p>{{ section.settings.subheading }}</p>\n  <h2>{{ section.settings.heading }}</h2>\n  <div class=\"lb-first-party-spotlight__blocks\">\n    {% for block in section.blocks %}\n      {{ block.content | raw }}\n    {% endfor %}\n  </div>\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Spotlight\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"Made for daily buyers\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"text\",\n      \"label\": \"Subheading\",\n      \"id\": \"subheading\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"badge\",\n      \"name\": \"Badge\",\n      \"settings\": []\n    },\n    {\n      \"type\": \"@app\",\n      \"name\": \"App block\",\n      \"settings\": []\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Spotlight\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"testimonials":{"path":"sections/testimonials.liquid","schema":{"blocks":[{"name":"Testimonial","settings":[{"id":"quote","label":"Quote","type":"textarea"},{"id":"author","label":"Author","type":"text"}],"type":"testimonial"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Testimonials","presets":[{"blocks":[],"name":"Testimonials","settings":{}}],"settings":[{"default":"What customers say","id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-testimonials\" data-section-id=\"{{ section.id }}\">\n  <h2>{{ section.settings.title }}</h2>\n  {% if section.blocks.size > 0 %}<div class=\"lb-testimonials__items\">{% for block in section.blocks %}<blockquote {{ block.editor_attributes | raw }}><p>{{ block.settings.quote }}</p><cite>{{ block.settings.author }}</cite>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</blockquote>{% endfor %}</div>\n  {% else %}<p class=\"lb-testimonials__empty\">Add customer reviews to build trust.</p>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Testimonials\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"What customers say\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"testimonial\",\n      \"name\": \"Testimonial\",\n      \"settings\": [\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Quote\",\n          \"id\": \"quote\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Author\",\n          \"id\": \"author\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Testimonials\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"trust-badges":{"path":"sections/trust-badges.liquid","schema":{"blocks":[{"name":"Badge","settings":[{"default":"New","id":"label","label":"Label","type":"text"}],"type":"badge"}],"disabled_on":{"groups":[],"templa