 ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"video-hero":{"path":"sections/video-hero.liquid","schema":{"blocks":[],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Video Hero","presets":[{"blocks":[],"name":"Video Hero","settings":{}}],"settings":[{"default":"See the fit in motion","id":"heading","label":"Heading","type":"text"},{"default":"A quick look at how each drop moves, from the box to your feet.","id":"subheading","label":"Subheading","type":"textarea"},{"id":"videoUrl","info":"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.","label":"Video embed URL","type":"url"}],"tag":"section"},"source":"<div class=\"ct-theme\"><section class=\"lb-video-hero\" data-section-id=\"{{ section.id }}\">\n  <div class=\"lb-video-hero__copy\">\n    <h2 class=\"lb-video-hero__heading\">{{ section.settings.heading }}</h2>\n    {% if section.settings.subheading %}<p class=\"lb-video-hero__subheading\">{{ section.settings.subheading }}</p>{% endif %}\n  </div>\n  {% if section.settings.videoUrl != blank %}<div class=\"lb-video-hero__embed\"><iframe src=\"{{ section.settings.videoUrl | video_url }}\" title=\"{{ section.settings.heading }}\" loading=\"lazy\" sandbox=\"allow-scripts allow-same-origin allow-presentation\" allowfullscreen></iframe></div>{% endif %}\n</section>\n</div>\n{% schema %}\n{\n  \"name\": \"Video Hero\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Heading\",\n      \"default\": \"See the fit in motion\",\n      \"id\": \"heading\"\n    },\n    {\n      \"type\": \"textarea\",\n      \"label\": \"Subheading\",\n      \"default\": \"A quick look at how each drop moves, from the box to your feet.\",\n      \"id\": \"subheading\"\n    },\n    {\n      \"type\": \"url\",\n      \"label\": \"Video embed URL\",\n      \"info\": \"A YouTube or Vimeo embed URL (for example https://www.youtube.com/embed/VIDEO_ID). Leave blank to hide the video.\",\n      \"id\": \"videoUrl\"\n    }\n  ],\n  \"blocks\": [],\n  \"presets\": [\n    {\n      \"name\": \"Video Hero\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"}},"templates":{"article":{"layout":"theme","name":"Article","order":["article-content-default"],"sections":{"article-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"article-content"}}},"blog":{"layout":"theme","name":"Blog","order":["blog-listing-default"],"sections":{"blog-listing-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"heading":"Our Blog"},"type":"blog-listing"}}},"cart":{"layout":"theme","name":"LetBuyy Core cart","order":["cart-summary-default"],"sections":{"cart-summary-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"cart-summary"}}},"collection":{"layout":"theme","name":"Circuit collection","order":["forge-discovery-collection","forge-results-collection"],"sections":{"forge-discovery-collection":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"collection-filter"},"forge-results-collection":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"collection-product-list"}}},"contact":{"layout":"theme","name":"Contact","order":["contact-form-default"],"sections":{"contact-form-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"showPhone":true,"title":"Contact us"},"type":"contact-form"}}},"customers/account":{"layout":"theme","name":"Account","order":["customer-account-default"],"sections":{"customer-account-default":{"bl