ly":"Inter","borderRadius":4,"headingFontFamily":"Playfair Display","primaryColor":"#713F35","secondaryColor":"#65574C","surfaceColor":"#EFE7DC","textColor":"#241E1A"}}},"settings_schema":{"schema_version":"2026-05-json-contract","settings":{"appearance":{"description":"Layout tokens shared by every section.","fields":{"borderRadius":{"default":12,"label":"Corner radius","type":"number"}},"label":"Appearance"},"colors":{"description":"LetBuyy Core storefront color tokens.","fields":{"accentColor":{"default":"#F59E0B","label":"Accent color","type":"color"},"backgroundColor":{"default":"#FFFFFF","label":"Background color","type":"color"},"primaryColor":{"default":"#8B5CF6","label":"Primary color","type":"color"},"secondaryColor":{"default":"#3B82F6","label":"Secondary color","type":"color"},"surfaceColor":{"default":"#F8FAFC","label":"Surface color","type":"color"},"textColor":{"default":"#1F2937","label":"Text color","type":"color"}},"label":"Colors"},"seo":{"description":"Metadata rendered into <head> by the theme layout.","fields":{"faviconUrl":{"default":"","info":"Rendered as <link rel=\"icon\">. Left empty until the merchant uploads one.","label":"Favicon URL","type":"url"},"metaDescription":{"default":"","info":"Falls back to the shop description. Truncated to 160 characters on output.","label":"Meta description","maxLength":160,"type":"textarea"},"socialImageUrl":{"default":"","info":"Used for og:image and twitter:image. Left empty until the merchant uploads one.","label":"Social share image URL","type":"url"}},"label":"SEO and social"},"typography":{"description":"First-party type settings mirrored from the JSON-contract LetBuyy Core theme.","fields":{"bodyFontFamily":{"default":"Inter","label":"Body font","type":"text"},"headingFontFamily":{"default":"Inter","label":"Heading font","type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-circuit=\"2\">\n.ct-theme{color:var(--foreground,#142236);background:var(--background,#f5f7fa);font:1rem/1.5 var(--font-main,Inter,Arial,sans-serif);--ct-muted:var(--text-secondary,#4c5b70);--ct-line:var(--border-color,#67768b);--ct-surface:var(--surface,#fff)}\n.ct-theme *{box-sizing:border-box}.ct-theme img{max-width:100%;height:auto}.ct-theme :where(h1,h2,h3){font-family:var(--font-heading,Inter,Arial,sans-serif);line-height:1.18;letter-spacing:-.035em;overflow-wrap:anywhere}.ct-theme h1{font-size:clamp(2rem,3.3vw,3rem)}.ct-theme h2{font-size:clamp(1.5rem,2.4vw,2.1rem)}.ct-theme p{color:var(--ct-muted)}.ct-theme a{color:var(--primary,#17476e)}.ct-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--primary,#17476e);outline-offset:4px}.ct-wrap{width:min(1328px,calc(100% - 80px));margin-inline:auto}.ct-section{padding-block:40px}.ct-eyebrow{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em}.ct-button{display:inline-flex;justify-content:center;align-items:center;gap:10px;min-height:48px;padding:12px 20px;border:1px solid var(--primary,#17476e);border-radius:var(--radius,4px);background:var(--primary,#17476e);color:var(--primary-foreground,#fff)!important;font-weight:600;text-decoration:none}.ct-link{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:4px}.ct-heading{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:24px}.ct-heading h2{margin:0}.ct-theme button:disabled{cursor:not-allowed;opacity:.65}.ct-search{display:flex;gap:10px;max-width:760px;margin-block:24px}.ct-search input{flex:1;min-width:0;min-height:48px;padding:12px;border:1px solid var(--ct-line);background:var(--ct-surface);color:var(--foreground)}\n.ct-theme .lb-header{background:var(--foreground,#142236);color:var(--background,#f5f7fa);padding-block:14px}.ct-theme .lb-header__inner{max-width:1328px;width:calc(100% - 80px);margin:auto;gap:24px}.ct-theme .lb-header a,.ct-theme .lb-header button,.ct-theme .lb-header summary{color:inherit}.ct-theme .lb-header button{background:transparent}.ct-theme .lb-header__brand{font-weight:800;font-size:1.75rem;letter-spacing:-.06em}.ct-header-search{display:flex;flex:1;min-width:0;max-width:620px;gap:8px}.ct-header-search input{flex:1;min-width:0;min-height:44px;padding:10px 12px;color:var(--foreground);background:var(--background);border:1px solid var(--ct-line);border-radius:var(--radius,4px)}.ct-header-search button{min-height:44px;padding:8px 14px;border:1px solid currentColor;border-radius:var(--radius,4px)}.ct-theme .lb-header__nav-links{gap:22px}.ct-theme .lb-announcement-bar{background:var(--surface,#e7edf5);color:var(--foreground);text-align:center;font-size:.75rem}.ct-theme .lb-header__search-overlay{color:var(--foreground)}.ct-theme .lb-footer{background:var(--foreground,#142236);--footer-bg:var(--foreground,#142236);--footer-text:var(--background,#f5f7fa);--footer-text-muted:var(--background,#f5f7fa);color:var(--background,#f5f7fa);padding-inline:max(24px,calc((100vw - 1328px)/2))}.ct-theme .lb-footer :where(a,p,h2,h3){color:inherit}\n.ct-tasks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.ct-task{padding:24px;border:1px solid var(--ct-line);background:var(--ct-surface);text-decoration:none;min-width:0}.ct-task h3{font-size:1.1rem;margin:0 0 10px}.ct-task p{font-size:.875rem;margin:0}.ct-feature{display:grid;grid-template-columns:1fr 1fr;background:var(--surface,#e7edf5);border:1px solid var(--ct-line)}.ct-feature-copy{padding:40px;align-self:center;min-width:0}.ct-feature-copy h2{font-size:clamp(2rem,3.3vw,3rem);margin-block:14px 20px}.ct-feature-media{min-width:0;display:grid;place-items:center}.ct-feature-media img{width:100%;height:390px;object-fit:contain}.ct-feature-empty{grid-template-columns:1fr}.ct-feature-empty .ct-feature-copy{max-width:800px}.ct-empty{padding:28px;border:1px solid var(--ct-line);background:var(--ct-surface)}\n.ct-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.ct-grid[data-columns=\"2\"]{grid-template-columns:repeat(2,minmax(0,1fr))}.ct-grid[data-columns=\"3\"]{grid-template-columns:repeat(3,minmax(0,1fr))}.ct-card{border:1px solid var(--ct-line);background:var(--ct-surface);min-width:0}.ct-card-media{aspect-ratio:1;display:grid;place-items:center;background:var(--surface,#e7edf5)}.ct-card-media img{width:100%;height:100%;object-fit:contain}.ct-card-placeholder{padding:24px;text-align:center;font-size:.875rem}.ct-card-body{padding:18px;min-width:0}.ct-card h3{font-size:1.0625rem;line-height:1.4;margin:8px 0 14px}.ct-card h3 a{color:inherit;text-decoration:none}.ct-card-model{font-size:.75rem;overflow-wrap:anywhere}.ct-card-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;border-block:1px solid var(--ct-line);padding-block:12px;font-size:.875rem}.ct-card-facts>div{min-width:0;overflow-wrap:anywhere}.ct-card-facts dt{font-size:.75rem;color:var(--ct-muted);margin-bottom:5px}.ct-card-facts dd{margin:0}.ct-card-price{overflow-wrap:anywhere;font-variant-numeric:tabular-nums;font-size:1.125rem;font-weight:700}.ct-card-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px}.ct-card-status{font-size:.75rem}.ct-catalog-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px}.ct-catalog-layout.ct-no-facets{grid-template-columns:1fr}.ct-facets{padding:22px;border:1px solid var(--ct-line);background:var(--ct-surface);align-self:start}.ct-facets h2{font-size:1.125rem}.ct-facets fieldset{border:0;border-top:1px solid var(--ct-line);margin:22px 0;padding:18px 0 0}.ct-facets legend{font-size:.875rem;font-weight:600}.ct-facets label{display:flex;align-items:start;gap:8px;font-size:.875rem;margin:14px 0}.ct-facets input{width:18px;height:18px;flex-shrink:0;accent-color:var(--primary)}.ct-facets label span{margin-left:auto}.ct-pagination{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;margin-top:24px}.ct-sort{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:flex-end;margin-bottom:20px}.ct-sort select{min-height:44px;max-width:100%;padding:8px;border:1px solid var(--ct-line);background:var(--ct-surface);color:var(--foreground)}.ct-mobile-facets{display:none}\n.ct-education{display:grid;grid-template-columns:1fr 1.3fr;gap:32px;padding:36px;background:var(--surface,#e7edf5);border:1px solid var(--ct-line)}.ct-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.ct-step{border:1px solid var(--ct-line);padding:20px;min-width:0}.ct-step h3{font-size:1rem}.ct-step p{font-size:.875rem}.ct-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.ct-services article{border-top:2px solid var(--ct-line);padding-top:20px}.ct-services h3{font-size:1.1rem}.ct-services p{font-size:.875rem}\n.ct-theme .lb-product-detail{width:min(1328px,calc(100% - 80px));margin:auto;padding-block:28px 48px}.ct-theme .lb-product-detail__layout{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:48px}.ct-theme .lb-product-detail__info{min-width:0}.ct-theme .lb-product-detail__gallery-image{width:100%;aspect-ratio:1;object-fit:contain;background:var(--surface,#e7edf5)}.ct-theme .lb-product-detail__gallery-thumb 