blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"}},"templates":{"article":{"layout":"theme","name":"Article","order":["article-content-default"],"sections":{"article-content-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"article-content"}}},"blog":{"layout":"theme","name":"Blog","order":["blog-listing-default"],"sections":{"blog-listing-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"heading":"Our Blog"},"type":"blog-listing"}}},"cart":{"layout":"theme","name":"LetBuyy Core cart","order":["cart-summary-default"],"sections":{"cart-summary-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"cart-summary"}}},"collection":{"layout":"theme","name":"LetBuyy Core collection","order":["collection-filter-default","collection-products"],"sections":{"collection-filter-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"title":"Choose your base"},"type":"collection-filter"},"collection-products":{"block_order":[],"blocks":{},"disabled":false,"settings":{"columns":2,"productLimit":6,"subtitle":"Each product is sold separately.","title":"Choose your base"},"type":"collection-product-list"}}},"contact":{"layout":"theme","name":"Contact","order":["contact-form-default"],"sections":{"contact-form-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{"showPhone":true,"title":"Contact us"},"type":"contact-form"}}},"customers/account":{"layout":"theme","name":"Account","order":["customer-account-default"],"sections":{"customer-account-default":{"block_order":[],"blocks":{},"disabled":false,"settings":{},"type":"customer-account"}}},"customers/addresses":{"layout":"theme","name":"Addresses","order":["customer-addresses-default"],"sections":{"customer-addresses-default":{"block_order":[],"blocks":{}