ne":"liquid","liquid_ready":true,"renderer_version":"0.1.0"}},"schemaManifest":{"block_schemas":{"@app":{"fields":{"extension_handle":{"label":"Extension handle","maxLength":120,"type":"text"},"slot":{"label":"Slot","maxLength":160,"type":"text"}},"name":"App block"},"badge":{"fields":{"label":{"default":"New","label":"Label","type":"text"}},"name":"Badge","source_path":"blocks/badge.liquid"}},"layout_schema":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-madeyours=\"2\">.my-theme{--my-radius:{{ settings.borderRadius | default: 8 | plus: 0 | at_least: 0 | at_most: 32 }}px}\n.my-theme{--my-ink:var(--foreground,#23243e);--my-muted:var(--secondary,#595d7d);--my-action:var(--primary,#484b8b);--my-canvas:var(--background,#f5f6fc);--my-surface:var(--surface,#fff);--my-border:var(--secondary,#747999);--my-focus:var(--accent,#005fcc);background:var(--my-canvas);color:var(--my-ink);font:1rem/1.55 var(--font-body,Inter,Arial,sans-serif);overflow-wrap:anywhere}\n.my-theme *{box-sizing:border-box;min-width:0}.my-theme [hidden]{display:none!important}.my-theme :where(h1,h2,h3){font-family:var(--font-display,Inter,Arial,sans-serif);line-height:1.2;letter-spacing:-.025em;font-weight:600}.my-theme h1{font-size:clamp(2rem,3.6vw,3.4rem)}.my-theme h2{font-size:clamp(1.6rem,2.4vw,2.2rem)}.my-theme h3{font-size:1.2rem}.my-theme p{color:var(--my-muted)}.my-theme a{color:inherit;text-underline-offset:.2em}.my-theme img{max-width:100%;height:auto;display:block}.my-theme :where(button,input,select,textarea){font:inherit}.my-theme :where(a,button,input,select,summary):focus-visible{outline:3px solid var(--my-focus);outline-offset:3px}.my-theme :where(button,a,summary){touch-action:manipulation}.my-theme button{cursor:pointer}.my-theme button:disabled{cursor:default;opacity:.65}.my-wrap{width:min(76rem,calc(100% - 6rem));margin-inline:auto}.my-section{padding-block:3.5rem}.my-eyebrow{font-size:.75rem;letter-spacing:.12em;font-weight:700;color:var(--my-action)!important}.my-button,.my-theme .lb-product-detail__cta--primary{display:inline-flex;justify-content:center;align-items:center;min-height:3rem;padding:.8rem 1.3rem;background:var(--my-action);color:var(--lb-color-primary-cta-text,#fff);border:1px solid var(--my-action);border-radius:var(--my-radius,.5rem);text-decoration:none;font-weight:600;line-height:1.35}.my-link{display:inline-flex;align-items:center;min-height:2.75rem;font-weight:600;color:var(--my-action)!important}.my-theme label{display:grid;gap:.45rem;font-size:.9rem;font-weight:600}.my-theme :where(input,select,textarea){min-height:2.9rem;max-width:100%;padding:.7rem .8rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem);background:var(--my-surface);color:var(--my-ink)}\n.my-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:3rem;align-items:center;padding-block:3rem}.my-intro-copy{max-width:34rem}.my-intro-copy h1{margin:.8rem 0 1.2rem}.my-intro-copy p{max-width:31rem}.my-intro-media[data-focus=\"top\"] img{object-position:center top}.my-intro-media[data-focus=\"bottom\"] img{object-position:center bottom}.my-intro-media img{width:100%;aspect-ratio:4/3;object-fit:cover;bord