r","primaryColor":"#8B5CF6","secondaryColor":"#6D28D9","surfaceColor":"#F8FAFC","textColor":"#1A1A2E"},"Refresh":{"accentColor":"#F4A261","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#2D6A4F","secondaryColor":"#1B4332","surfaceColor":"#F8FFF4","textColor":"#1B2521"},"Ride":{"accentColor":"#FFD100","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":6,"headingFontFamily":"Inter","primaryColor":"#FF4D00","secondaryColor":"#1C1C1C","surfaceColor":"#F5F5F5","textColor":"#111111"},"Summit":{"accentColor":"#A4E500","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":12,"headingFontFamily":"Inter","primaryColor":"#00B3B3","secondaryColor":"#008080","surfaceColor":"#F9FAFB","textColor":"#1A1A2E"},"Threadline":{"accentColor":"#005FCC","backgroundColor":"#FAF7F2","bodyFontFamily":"Inter","borderRadius":4,"headingFontFamily":"Playfair Display","primaryColor":"#713F35","secondaryColor":"#65574C","surfaceColor":"#EFE7DC","textColor":"#241E1A"}}},"settings_schema":{"schema_version":"2026-05-json-contract","settings":{"appearance":{"description":"Layout tokens shared by every section.","fields":{"borderRadius":{"default":12,"label":"Corner radius","type":"number"}},"label":"Appearance"},"colors":{"description":"LetBuyy Core storefront color tokens.","fields":{"accentColor":{"default":"#F59E0B","label":"Accent color","type":"color"},"backgroundColor":{"default":"#FFFFFF","label":"Background color","type":"color"},"primaryColor":{"default":"#8B5CF6","label":"Primary color","type":"color"},"secondaryColor":{"default":"#3B82F6","label":"Secondary color","type":"color"},"surfaceColor":{"default":"#F8FAFC","label":"Surface color","type":"color"},"textColor":{"default":"#1F2937","label":"Text color","type":"color"}},"label":"Colors"},"seo":{"description":"Metadata rendered into <head> by the theme layout.","fields":{"faviconUrl":{"default":"","info":"Rendered as <link rel=\"icon\">. Left empty until the merchant uploads one.","label":"Favicon URL","type":"url"},"metaDescription":{"default":"","info":"Falls back to the shop description. Truncated to 160 characters on output.","label":"Meta description","maxLength":160,"type":"textarea"},"socialImageUrl":{"default":"","info":"Used for og:image and twitter:image. Left empty until the merchant uploads one.","label":"Social share image URL","type":"url"}},"label":"SEO and social"},"typography":{"description":"First-party type settings mirrored from the JSON-contract LetBuyy Core theme.","fields":{"bodyFontFamily":{"default":"Inter","label":"Body font","type":"text"},"headingFontFamily":{"default":"Inter","label":"Heading font","type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-madeyours=\"2\">.my-theme{--my-radius:{{ settings.borderRadius | default: 8 | plus: 0 | at_least: 0 | at_most: 32 }}px}\n.my-theme{--my-ink:var(--foreground,#23243e);--my-muted:var(--secondary,#595d7d);--my-action:var(--primary,#484b8b);--my-canvas:var(--background,#f5f6fc);--my-surface:var(--surface,#fff);--my-border:var(--secondary,#747999);--my-focus:var(--accent,#005fcc);background:var(--my-canvas);color:var(--my-ink);font:1rem/1.55 var(--font-body,Inter,Arial,sans-serif);overflow-wrap:anywhere}\n.my-theme *{box-sizing:border-box;min-width:0}.my-theme [hidden]{display:none!important}.my-theme :where(h1,h2,h3){font-family:var(--font-display,Inter,Arial,sans-serif);line-height:1.2;letter-spacing:-.025em;font-weight:600}.my-theme h1{font-size:clamp(2rem,3.6vw,3.4rem)}.my-theme h2{font-size:clamp(1.6rem,2.4vw,2.2rem)}.my-theme h3{font-size:1.2rem}.my-theme p{color:var(--my-muted)}.my-theme a{color:inherit;text-underline-offset:.2em}.my-theme img{max-width:100%;height:auto;display:block}.my-theme :where(button,input,select,textarea){font:inherit}.my-theme :where(a,button,input,select,summary):focus-visible{outline:3px solid var(--my-focus);outline-offset:3px}.my-theme :where(button,a,summary){touch-action:manipulation}.my-theme button{cursor:pointer}.my-theme button:disabled{cursor:default;opacity:.65}.my-wrap{width:min(76rem,calc(100% - 6rem));margin-inline:auto}.my-section{padding-block:3.5rem}.my-eyebrow{font-size:.75rem;letter-spacing:.12em;font-weight:700;color:var(--my-action)!important}.my-button,.my-theme .lb-product-detail__cta--primary{display:inline-flex;justify-content:center;align-items:center;min-height:3rem;padding:.8rem 1.3rem;background:var(--my-action);color:var(--lb-color-primary-cta-text,#fff);border:1px solid var(--my-action);border-radius:var(--my-radius,.5rem);text-decoration:none;font-weight:600;line-height:1.35}.my-link{display:inline-flex;align-items:center;min-height:2.75rem;font-weight:600;color:var(--my-action)!important}.my-theme label{display:grid;gap:.45rem;font-size:.9rem;font-weight:600}.my-theme :where(input,select,textarea){min-height:2.9rem;max-width:100%;padding:.7rem .8rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem);background:var(--my-surface);color:var(--my-ink)}\n.my-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:3rem;align-items:center;padding-block:3rem}.my-intro-copy{max-width:34rem}.my-intro-copy h1{margin:.8rem 0 1.2rem}.my-intro-copy p{max-width:31rem}.my-intro-media[data-focus=\"top\"] img{object-position:center top}.my-intro-media[data-focus=\"bottom\"] img{object-position:center bottom}.my-intro-media img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:var(--my-radius,1rem)}.my-process{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.5rem;border-block:1px solid var(--my-border);padding-block:1.5rem}.my-process article{display:grid;grid-template-columns:2.25rem 1fr;gap:.8rem}.my-step{display:grid;place-items:center;width:2.25rem;height:2.25rem;border:1px solid var(--my-action);border-radius:50%;color:var(--my-action);font-weight:600}.my-process h3{font-size:1rem;margin:0 0 .4rem}.my-process p{font-size:.875rem;margin:0}.my-heading{display:flex;justify-content:space-between;align-items:end;gap:1.5rem;margin-bottom:1.6rem}.my-heading h2{margin:0}.my-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}.my-grid[data-columns=\"3\"]{grid-template-columns:repeat(3,minmax(0,1fr))}.my-card{background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);overflow:hidden}.my-card-image{display:block;position:relative;background:var(--my-canvas);aspect-ratio:4/3}.my-card-image img{width:100%;height:100%;object-fit:contain}.my-card-body{padding:1.4rem}.my-card h3{margin:0}.my-card h3 a{text-decoration:none}.my-price{font-weight:600;color:var(--my-ink)!important;font-variant-numeric:tabular-nums}.my-capabilities{list-style:none;padding:0;font-size:.875rem;color:var(--my-muted)}.my-capabilities li{padding-block:.25rem}.my-unavailable{position:absolute;bottom:.75rem;left:.75rem;background:var(--my-surface);padding:.4rem .8rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem);font-size:.8rem}.my-empty-image{display:grid;place-items:center;height:100%;padding:2rem;text-align:center;color:var(--my-muted)}.my-collections{display:flex;flex-wrap:wrap;gap:.75rem}.my-collections a{border:1px solid var(--my-border);padding:.7rem 1.2rem;border-radius:3rem;background:var(--my-surface);min-height:2.75rem}.my-story{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}.my-story>img{width:100%;aspect-ratio:4/3;object-fit:contain;border-radius:var(--my-radius,.8rem)}.my-story-no-image{grid-template-columns:1fr;max-width:50rem}.my-filters{display:flex;flex-wrap:wrap;gap:1rem;align-items:end;margin-top:1.5rem}.my-filters label{flex:1;min-width:9rem}.my-filters input{width:100%}.my-pagination{display:flex;flex-wrap:wrap;gap:1.5rem;align-items:center;justify-content:center;margin-top:2rem}.my-empty{padding:2rem;border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);background:var(--my-surface)}\n.my-theme .lb-product-detail{width:min(76rem,calc(100% - 6rem));margin:auto;padding-block:2rem 3.5rem}.my-theme .lb-product-detail__layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:3rem;align-items:start}.my-theme .lb-product-detail__gallery{position:static}.my-theme .lb-product-detail__gallery-main{background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem)}.my-theme .lb-product-detail__gallery-image{width:100%;height:100%;object-fit:contain;aspect-ratio:1}.my-theme .lb-product-detail__gallery-thumbs{display:flex;gap:.7rem;flex-wrap:wrap;margin-top:1rem}.my-theme .lb-product-detail__gallery-thumb{width:4.5rem;height:4.5rem;padding:.3rem;border:1px solid var(--my-border);background:var(--my-surface)}.my-theme .lb-product-detail__gallery-thumb img{width:100%;height:100%;object-fit:contain}.my-theme .lb-product-detail__info h1{font-size:clamp(1.8rem,2.7vw,2.6rem);margin-block:0 1rem}.my-theme .lb-product-detail__price{font-size:1.3rem;font-weight:600}.my-theme .lb-product-detail__breadcrumb{display:flex;flex-wrap:wrap;gap:.7rem;font-size:.85rem;margin-bottom:1.5rem}.my-theme .lb-product-detail__variants{display:block;margin-block:1rem}.my-theme .lb-product-detail__variant-values{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:.5rem}.my-theme [data-lb-variant-option]{min-height:2.75rem;padding:.6rem .9rem;background:var(--my-surface);color:var(--my-ink);border:1px solid var(--my-border);border-radius:var(--my-radius,.4rem)}.my-theme [data-lb-variant-option][aria-pressed=\"true\"]{outline:1px solid var(--my-action);border-color:var(--my-action);background:var(--my-canvas)}.my-theme lb-add-to-cart{display:flex;flex-wrap:wrap;gap:1rem;align-items:center}.my-theme .lb-product-detail__quantity{width:5rem}.my-theme .lb-product-detail__accordion{padding-block:1rem;border-top:1px solid var(--my-border);margin-top:1rem}.my-theme .lb-product-detail__accordion summary{min-height:2.75rem;display:flex;align-items:center;cursor:pointer;font-weight:600}\n.my-config{flex-basis:100%;background:var(--my-surface);border:1px solid var(--my-border);border-radius:var(--my-radius,.8rem);padding:1.4rem}.my-config h2{font-size:1.2rem;margin:0 0 1rem}.my-config fieldset{margin:1rem 0;padding:0;border:0;display:grid;gap:1rem}.my-config legend{font-weight:600;margin-bottom:.5rem}.my-stages{list-style:none;padding:0;display:flex;gap:1rem;flex-wrap:wrap;font-size:.8rem;color:var(--my-muted)}.my-stages li[aria-current=\"step\"]{color:var(--my-action);font-weight:700}.my-config select,.my-config input{width:100%}.my-theme .my-note{font-size:.8rem}.my-error{color:var(--lb-color-error,#b42318)!important;border-inline-start:3px solid currentColor;padding-left:.7rem}.my-preview{padding:1rem;border:1px dashed var(--my-border);border-radius:var(--my-radius,.4rem)}.my-preview output{display:block;font-size:1.6rem;color:var(--my-ink);white-space:pre-wrap;overflow-wrap:anywhere}.my-summary{display:grid;grid-template-columns:minmax(6rem,1fr) minmax(0,2fr);gap:.7rem;margin:1rem 0}.my-summary dt{color:var(--my-muted)}.my-summary dd{margin:0;white-space:pre-wrap;font-weight:600}.my-theme :where(