}.my-theme button.my-link{background:transparent;border:0;padding-inline:0;min-width:44px}.my-theme .lb-footer{--footer-bg:var(--my-surface);--footer-text:var(--my-ink);--footer-text-muted:var(--my-muted)}.my-theme .lb-header__inner{flex-wrap:wrap;column-gap:1rem;row-gap:.5rem}.my-theme .lb-header__brand{display:inline-flex;align-items:center;min-height:44px;max-width:100%;overflow-wrap:anywhere}.my-theme .lb-header__actions{flex-wrap:wrap;margin-inline-start:auto;max-width:100%}.my-theme :where(.lb-header__toggle,.lb-header__search-toggle,.lb-header__account,.lb-header__cart,.lb-header__nav-close){min-width:44px;min-height:44px;flex-shrink:0}.my-theme .lb-header__nav-links{flex-wrap:wrap}.my-theme .lb-header__nav-links>a{display:flex;align-items:center;min-height:44px}.my-theme .my-card h3 a{display:inline-flex;align-items:center;min-height:44px}\n@media(max-width:47.999em){.my-theme .lb-mobile-nav:not([data-open=\"true\"]) .lb-header__nav{visibility:hidden;pointer-events:none}.my-theme .lb-mobile-nav[data-open=\"true\"] .lb-header__nav{visibility:visible;pointer-events:auto}.my-theme .lb-header__inner{column-gap:.75rem}.my-theme .lb-header__brand{max-width:calc(100% - 56px)}}\n.my-theme .lb-product-detail__breadcrumb{opacity:1;color:var(--my-muted)}\n.my-theme .lb-footer :where(h4,.lb-footer__bottom,.lb-footer__brand p,.lb-footer__col a),.my-theme .lb-product-detail__accordion-body{opacity:1}\n@media(prefers-reduced-motion:reduce){.my-theme *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}\n</style>\n</head>\n<body class=\"lb-theme lb-theme--letbuyy-core\">\n  <a class=\"lb-skip-link\" href=\"#MainContent\">Skip to content</a>\n  <header class=\"lb-layout__header\">\n    <a class=\"lb-layout__brand\" href=\"{{ routes.root_url }}\">{{ shop.name }}</a>\n    <nav class=\"lb-layout__nav\" aria-label=\"Primary\">\n      {% if linklists.main_menu.links.size > 0 %}{% for link in linklists.main_menu.links %}<a href=\"{{ link.url | store