  \"name\": \"Testimonials\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n      \"label\": \"Title\",\n      \"default\": \"What customers say\",\n      \"id\": \"title\"\n    }\n  ],\n  \"blocks\": [\n    {\n      \"type\": \"testimonial\",\n      \"name\": \"Testimonial\",\n      \"settings\": [\n        {\n          \"type\": \"textarea\",\n          \"label\": \"Quote\",\n          \"id\": \"quote\"\n        },\n        {\n          \"type\": \"text\",\n          \"label\": \"Author\",\n          \"id\": \"author\"\n        }\n      ]\n    }\n  ],\n  \"presets\": [\n    {\n      \"name\": \"Testimonials\",\n      \"settings\": {},\n      \"blocks\": []\n    }\n  ],\n  \"enabled_on\": {\n    \"templates\": [\n      \"*\"\n    ],\n    \"groups\": [\n      \"template\"\n    ]\n  },\n  \"disabled_on\": {\n    \"templates\": [],\n    \"groups\": []\n  }\n}\n{% endschema %}"},"trust-badges":{"path":"sections/trust-badges.liquid","schema":{"blocks":[{"name":"Badge","settings":[{"id":"label","label":"Label","type":"text"},{"id":"description","label":"Description","type":"text"}],"type":"badge"}],"disabled_on":{"groups":[],"templates":[]},"enabled_on":{"groups":["template"],"templates":["*"]},"name":"Trust Badges","presets":[{"blocks":[],"name":"Trust Badges","settings":{}}],"settings":[{"id":"title","label":"Title","type":"text"}],"tag":"section"},"source":"<div class=\"my-theme\"><section class=\"lb-trust-badges\" data-section-id=\"{{ section.id }}\">\n  {% if section.settings.title %}<h2>{{ section.settings.title }}</h2>{% endif %}\n  {% for block in section.blocks %}<article><h3>{{ block.settings.label }}</h3><span>{{ block.settings.description }}</span>{% for child in block.sub_blocks %}{% unless child.is_app_block %}{{ child.html | raw }}{% endunless %}{% endfor %}</article>{% endfor %}\n</section></div>\n{% schema %}\n{\n  \"name\": \"Trust Badges\",\n  \"tag\": \"section\",\n  \"settings\": [\n    {\n      \"type\": \"text\",\n 