centColor":"#D4AF7A","backgroundColor":"#FFFFFF","bodyFontFamily":"Lato","borderRadius":16,"headingFontFamily":"Cormorant Garamond","primaryColor":"#C2798B","secondaryColor":"#9E5A6F","surfaceColor":"#FFF8F9","textColor":"#2D1B22"},"Bloom":{"accentColor":"#4CAF73","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":14,"headingFontFamily":"Inter","primaryColor":"#E07B39","secondaryColor":"#B55E24","surfaceColor":"#FFF9F0","textColor":"#2C1A0A"},"Craft":{"accentColor":"#8D6E63","backgroundColor":"#FFFFFF","bodyFontFamily":"Source Sans Pro","borderRadius":6,"headingFontFamily":"Libre Baskerville","primaryColor":"#3E2723","secondaryColor":"#5D3B2E","surfaceColor":"#FFF8F0","textColor":"#2C1B12"},"Dawn":{"accentColor":"#C0832B","backgroundColor":"#FFFFFF","bodyFontFamily":"Source Sans Pro","borderRadius":4,"headingFontFamily":"Libre Baskerville","primaryColor":"#3B4F6B","secondaryColor":"#2C3E50","surfaceColor":"#FDF6EC","textColor":"#2C2C2C"},"Forge":{"accentColor":"#00B4D8","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":8,"headingFontFamily":"Inter","primaryColor":"#1E3A5F","secondaryColor":"#1E40AF","surfaceColor":"#F0F4F8","textColor":"#1A202C"},"Nova":{"accentColor":"#F59E0B","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#8B5CF6","secondaryColor":"#6D28D9","surfaceColor":"#F8FAFC","textColor":"#1A1A2E"},"Refresh":{"accentColor":"#F4A261","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":10,"headingFontFamily":"Inter","primaryColor":"#2D6A4F","secondaryColor":"#1B4332","surfaceColor":"#F8FFF4","textColor":"#1B2521"},"Ride":{"accentColor":"#FFD100","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":6,"headingFontFamily":"Inter","primaryColor":"#FF4D00","secondaryColor":"#1C1C1C","surfaceColor":"#F5F5F5","textColor":"#111111"},"Summit":{"accentColor":"#A4E500","backgroundColor":"#FFFFFF","bodyFontFamily":"Inter","borderRadius":12,"headingFontFamily":"Inter","primaryColor":"#00B3B3","secondaryColor":"#008080","surfaceColor":"#F9FAFB","textColor":"#1A1A2E"},"Threadline":{"accentColor":"#005FCC","backgroundColor":"#FAF7F2","bodyFontFamily":"Inter","borderRadius":4,"headingFontFamily":"Playfair Display","primaryColor":"#713F35","secondaryColor":"#65574C","surfaceColor":"#EFE7DC","textColor":"#241E1A"}}},"settings_schema":{"schema_version":"2026-05-json-contract","settings":{"appearance":{"description":"Layout tokens shared by every section.","fields":{"borderRadius":{"default":12,"label":"Corner radius","type":"number"}},"label":"Appearance"},"colors":{"description":"LetBuyy Core storefront color tokens.","fields":{"accentColor":{"default":"#F59E0B","label":"Accent color","type":"color"},"backgroundColor":{"default":"#FFFFFF","label":"Background color","type":"color"},"primaryColor":{"default":"#8B5CF6","label":"Primary color","type":"color"},"secondaryColor":{"default":"#3B82F6","label":"Secondary color","type":"color"},"surfaceColor":{"default":"#F8FAFC","label":"Surface color","type":"color"},"textColor":{"default":"#1F2937","label":"Text color","type":"color"}},"label":"Colors"},"seo":{"description":"Metadata rendered into <head> by the theme layout.","fields":{"faviconUrl":{"default":"","info":"Rendered as <link rel=\"icon\">. Left empty until the merchant uploads one.","label":"Favicon URL","type":"url"},"metaDescription":{"default":"","info":"Falls back to the shop description. Truncated to 160 characters on output.","label":"Meta description","maxLength":160,"type":"textarea"},"socialImageUrl":{"default":"","info":"Used for og:image and twitter:image. Left empty until the merchant uploads one.","label":"Social share image URL","type":"url"}},"label":"SEO and social"},"typography":{"description":"First-party type settings mirrored from the JSON-contract LetBuyy Core theme.","fields":{"bodyFontFamily":{"default":"Inter","label":"Body font","type":"text"},"headingFontFamily":{"default":"Inter","label":"Heading font","type":"text"}},"label":"Typography"}}}},"layout":{"theme":{"path":"layout/theme.liquid","source":"<!doctype html>\n<html lang=\"{{ request.locale | default: \"en\" }}\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  {% assign lb_page_title = shop.name %}\n  {% assign lb_meta_description = settings.metaDescription | default: shop.description | strip_html | truncate: 160 %}\n  <title>{{ lb_page_title }}</title>\n  {% if lb_meta_description != blank %}<meta name=\"description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  <meta name=\"twitter:card\" content=\"{% if settings.socialImageUrl != blank %}summary_large_image{% else %}summary{% endif %}\">\n  <meta name=\"twitter:title\" content=\"{{ lb_page_title }}\">\n  {% if lb_meta_description != blank %}<meta name=\"twitter:description\" content=\"{{ lb_meta_description }}\">{% endif %}\n  {% if settings.socialImageUrl != blank %}<meta name=\"twitter:image\" content=\"{{ settings.socialImageUrl | image_url }}\">{% endif %}\n  <style data-lb-layout=\"1\">\n    :root{--lb-focus-ring-width:2px;--lb-focus-ring-color:var(--accent,#2563eb);--lb-focus-offset:2px;--lb-space-sm:0.5rem;--lb-space-md:0.75rem;--lb-space-lg:1rem;--lb-radius-sm:0.375rem;--lb-layout-max:72rem;--lb-layout-gutter:1rem;--lb-layout-breakpoint:48em;}\n    .lb-theme :where(a,button,input,select,textarea,summary,details,[tabindex]):focus-visible{outline:var(--lb-focus-ring-width) solid var(--lb-focus-ring-color);outline-offset:var(--lb-focus-offset);}\n    .lb-skip-link{position:absolute;left:-9999px;top:0;z-index:100;padding:var(--lb-space-md) var(--lb-space-lg);border-radius:var(--lb-radius-sm);background:var(--surface,#f8fafc);color:var(--foreground,#1a1a2e);font-weight:600;}\n    .lb-skip-link:focus,.lb-skip-link:focus-visible{left:var(--lb-space-lg);top:var(--lb-space-lg);}\n    .lb-layout__header,.lb-layout__footer{display:flex;flex-direction:column;align-items:flex-start;gap:var(--lb-space-md);margin-inline:auto;max-width:min(var(--lb-layout-max),calc(100vw - var(--lb-layout-gutter) * 2));padding-block:var(--lb-space-lg);padding-inline:var(--lb-layout-gutter);}\n    .lb-layout__brand{font-family:var(--font-display,inherit);font-weight:700;}\n    .lb-layout__nav{display:flex;flex-wrap:wrap;gap:var(--lb-space-md);}\n    .lb-layout__legal{margin:0;font-size:0.875rem;}\n    @media (min-width:48em){.lb-layout__header,.lb-layout__footer{flex-direction:row;align-items:center;justify-content:space-between;}}\n  </style>\n  {{ content_for_header | raw }}\n<style data-niche-order-presentation=\"1\">.lb-order-facts{min-width:0;max-width:100%;margin-block:.75rem}.lb-order-facts>summary{min-height:44px;cursor:pointer;padding-block:.5rem}.lb-order-facts__text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.lb-order-facts__missing{font-size:.875em;overflow-wrap:anywhere}</style>\n<style data-pantry=\"2\">\n.pn-theme{--pn-muted:var(--pn-supporting-color,#5a624a);--pn-line:var(--pn-line-color,#d5d6c7);--pn-boundary:var(--pn-boundary-color,#707858);--pn-focus:var(--pn-focus-color,#005fcc);--pn-warning:#7a3e00;--pn-warning-surface:#fff4ce;--font-body:var(--font-main,Inter,Arial,sans-serif);--font-display:var(--font-heading,Inter,Arial,sans-serif);--footer-bg:var(--surface,#eee8d8);--footer-text:var(--foreground,#262a1d);--footer-text-muted:var(--pn-muted);background:var(--background,#fcf8ef);color:var(--foreground,#262a1d);font:16px/1.55 var(--font-body)}\n.pn-theme *{box-sizing:border-box;min-width:0}.pn-theme :where(img){max-width:100%}.pn-theme :where(a){color:inherit}.pn-theme :where(button,input,select,textarea){font:inherit;max-width:100%}.pn-theme :where(a,button,input,select,summary):focus-visible{outline:2px solid var(--pn-focus);outline-offset:4px}.pn-theme :where(h1,h2,h3){font-family:var(--font-display);font-weight:600;line-height:1.15;letter-spacing:-.035em;overflow-wrap:anywhere}.pn-theme h1{font-size:clamp(2rem,4vw,3rem)}.pn-theme h2{font-size:clamp(1.65rem,3vw,2rem)}.pn-theme h3{font-size:1.25rem}.pn-theme p{color:var(--pn-muted);overflow-wrap:anywhere}.pn-theme [hidden]{display:none!important}.pn-wrap{width:min(1240px,calc(100% - 96px));margin-inline:auto}.pn-section{padding-block:48px}.pn-eyebrow{text-transform:uppercase;font-size:.75rem;font-weight:600;letter-spacing:.14em}.pn-meta{font-size:.875rem}.pn-button{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:48px;padding:12px 22px;border:1px solid var(--primary,#36533d);background:var(--primary,#36533d);color:var(--pn-action-label,#fff)!important;border-radius:var(--radius,6px);font-weight:600;text-decoration:none;overflow-wrap:anywhere;max-width:100%}.pn-link{display:inline-flex;align-items:center;min-height:44px;text-decoration:underline;text-underline-offset:5px}.pn-heading{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:24px}.pn-heading h2{margin:0}.pn-empty{padding:26px;border:1px solid var(--pn-boundary);border-radius:6px}.pn-hero{display:grid;grid-template-columns:.9fr 1.1fr;background:var(--surface,#eee8d8);border-radius:8px;overflow:hidden}.pn-hero-copy{padding:44px}.pn-hero-copy h1{margin:14px 0 20px}.pn-hero-copy p{margin:0 0 24px}.pn-hero img{height:100%;width:100%;min-height:340px;object-fit:cover;object-position:var(--pn-hero-position,center)}.pn-hero img.pn-focal-left{object-position:left}.pn-hero img.pn-focal-center{object-position:center}.pn-hero img.pn-focal-right{object-position:right}.pn-hero--no-media{grid-template-columns:1fr}.pn-hero--no-media .pn-hero-copy{max-width:780px}.pn-shelves{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.pn-shelf{display:flex;justify-content:space-between;gap:15px;padding:20px;border:1px solid var(--pn-boundary);border-radius:6px;min-height:72px;text-decoration:none}.pn-shelf span{overflow-wrap:anywhere}.pn-product-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pn-card{display:grid;grid-template-columns:130px minmax(0,1fr);gap:20px;padding:18px;border:1px solid var(--pn-line);border-radius:6px;background:var(--pn-card-surface,#fff)}.pn-card-media{display:grid;place-items:center;background:var(--surface);min-height:150px;border-radius:4px;overflow:hidden}.pn-card-media img{width:130px;height:150px;object-fit:contain}.pn-card h3{margin:0 0 8px}.pn-card h3 a{text-decoration:none}.pn-card p{margin:5px 0}.pn-card-price{font-size:1.2rem;font-weight:600;font-variant-numeric:tabular-nums}.pn-card .pn-link{font-size:.875rem}.pn-card-placeholder{font-size:.8rem;padding:14px;text-align:center}.pn-card-net{font-size:.875rem}.pn-pairing{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:start}.pn-pairing .pn-product-list{grid-template-columns:1fr}.pn-feature{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}.pn-feature img{width:100%;height:360px;object-fit:contain;background:var(--surface)}.pn-feature--no-media{grid-template-columns:1fr}.pn-feature p{margin:16px 0}.pn-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;border-top:1px solid var(--pn-line)}.pn-services>div{padding-block:24px}.pn-services h3{margin:0 0 10px}.pn-filters{display:flex;flex-wrap:wrap;gap:14px;align-items:end;margin-top:22px}.pn-filters label{display:grid;gap:6px;font-size:.875rem}.pn-filters input,.pn-filters select{min-height:46px;border:1px solid var(--pn-boundary);border-radius:6px;background:var(--pn-card-surface,#fff);color:inherit;padding:10px 12px}.pn-pagination{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap;margin-top:28px}.pn-theme .pn-product-layout{display:grid;grid-template-columns:.95fr .9fr 1fr;gap:32px;align-items:start}.pn-theme .lb-product-detail{padding:24px 0 48px;width:min(1240px,calc(100% - 96px));margin-inline:auto}.pn-theme .lb-product-detail__breadcrumb{display:flex;gap:16px;flex-wrap:wrap;padding:0 0 26px;font-size:.875rem}.pn-theme .lb-product-detail__gallery{background:var(--surface);border-radius:6px;overflow:hidden}.pn-theme .lb-product-detail__gallery-main img{width:100%;aspect-ratio:1;object-fit:contain}.pn-theme .lb-product-detail__gallery-thumbs{display:flex;gap:8px;padding:10px;flex-wrap:wrap}.pn-theme .lb-product-detail__gallery-thumb{max-width:60px;min-height:44px}.pn-theme .lb-product-detail__gallery-thumb img{width:50px;height:55px;object-fit:contain}.pn-theme .lb-product-detail__info h1{font-size:2rem;margin:0 0 18px}.pn-theme .lb-product-detail__price-current{font-size:1.6rem;font-weight:600}.pn-theme .lb-product-detail__variant-group{margin:20px 0}.pn-theme .lb-product-detail__variant-values{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}.pn-theme .lb-product-detail__variant-values button{min-height:48px;min-width:44px;padding:10px 15px;border:1px solid var(--pn-boundary);background:transparent;border-radius:6px;color:inherit}.pn-theme .lb-product-detail__variant-values [aria-pressed=true]{background:var(--primary);color:var(--pn-action-label,#fff)}.pn-theme .lb-product-detail__quantity{min-height:48px;width:90px;padding:10px;border:1px solid var(--pn-boundary);border-radius:5px;background:var(--pn-card-surface,#fff);color:inherit}.pn-theme .lb-product-detail__purchase lb-add-to-cart{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.pn-theme .lb-product-detail__cta{min-height:48px;padding:12px 20px;border:1px solid var(--primary);border-radius:6px;background:var(--primary);color:var(--pn-action-label,#fff);font-weight:600}.pn-theme .lb-product-detail__accordion{border-bottom:1px solid var(--pn-line);padding-block:14px}.pn-theme .lb-product-detail__accordion summary{cursor:pointer;min-height:44px}.pn-food-facts h2{font-size:1.5rem;margin:0 0 22px}.pn-food-fact{padding-block:14px;border-bottom:1px solid var(--pn-line)}.pn-food-fact p{margin:7px 0;font-size:.875rem}.pn-food-unknown{padding:18px;background:var(--pn-warning-surface);color:var(--pn-warning);bor