ct-detail__layout{display:grid;grid-template-columns:1.08fr 1fr;gap:3.5rem}.kr-theme .lb-product-detail__gallery-main{background:var(--kr-surface);border-radius:.6rem}.kr-theme .lb-product-detail__gallery-image{width:100%;aspect-ratio:1/1;object-fit:contain}.kr-theme .lb-product-detail__gallery-thumbs{display:flex;gap:.8rem;margin-top:1rem}.kr-theme .lb-product-detail__gallery-thumb{width:6rem;height:5rem;border:1px solid var(--kr-border);background:var(--kr-canvas);padding:.3rem;border-radius:.4rem}.kr-theme .lb-product-detail__gallery-thumb img{width:100%;height:100%;object-fit:contain}.kr-theme .lb-product-detail__info{min-width:0}.kr-theme .lb-product-detail__info h1{font-size:clamp(2rem,3vw,2.7rem)}.kr-theme .lb-product-detail__price{font-size:1.5rem;font-weight:700;margin-block:1.2rem}.kr-theme .lb-product-detail__breadcrumb{display:flex;flex-wrap:wrap;gap:.8rem;margin-bottom:2rem;font-size:.85rem}.kr-theme .lb-product-detail__variants{display:block;margin-block:1.5rem}.kr-theme .lb-product-detail__variant-values{display:flex;flex-wrap:wrap;gap:.65rem;margin-top:.6rem}.kr-theme [data-lb-variant-option]{min-height:2.75rem;padding:.6rem .9rem;border:1px solid var(--kr-border);border-radius:.4rem;background:var(--kr-canvas);color:var(--kr-text)}.kr-theme [data-lb-variant-option][aria-pressed='true']{border:2px solid var(--kr-action);background:var(--kr-surface)}.kr-theme lb-add-to-cart{display:flex;flex-wrap:wrap;gap:1rem;align-items:center}.kr-theme .lb-product-detail__quantity{width:5rem}.kr-theme .lb-product-detail__accordion{padding-block:1rem;border-top:1px solid var(--kr-border);margin-top:1rem}.kr-theme .lb-product-detail__accordion summary{font-family:var(--font-heading,Georgia,serif);font-size:1.4rem;cursor:pointer}.kr-facts{border-top:1px solid var(--kr-border);padding-block:1.2rem}.kr-facts h2{font-size:1.5rem}.kr-facts ol{list-style:decimal;padding-left:1.4rem}.kr-facts li{padding:.8rem 0;border-bottom:1px solid var(--kr-border)}.kr-facts li strong{font-weight:700}.kr-facts li p{margin-block:.35rem;font-size:.875rem}.kr-media-pair{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;margin-block:2rem}.kr-media-pair img{width:100%;aspect-ratio:4/3;object-fit:contain;background:var(--kr-surface);border-radius:.5rem}.kr-media-pair figcaption{font-size:.875rem;padding-top:.65rem}.kr-theme :where(.lb-cart-summary,.lb-customer-account,.lb-customer-addresses,.lb-customer-orders,.lb-customer-order-detail,.lb-customer-settings,.lb-page-content,.lb-policy-content){max-width:min(75rem,calc(100% - 4rem));margin-inline:auto;padding-block:2rem}.kr-theme .lb-header,.kr-theme .lb-footer{background:var(--kr-canvas);color:var(--kr-text);border-color:var(--kr-border)}.kr-theme .lb-header__brand{font-family:var(--font-heading,Georgia,serif);font-size:2rem;font-weight:400}.kr-theme .lb-announcement-bar{background:var(--kr-action);color:var(--lb-color-primary-cta-text,#fff)}\n@media(max-width:70rem){.kr-wrap{width:calc(100% - 4rem)}.kr-intro{gap:1.5rem}.kr-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.kr-filter-form{grid-template-columns:1fr 1fr}.kr-filter-form>.kr-budget{grid-column:1/-1}.kr-help-grid{gap:1.3rem}.kr-theme .lb-product-detail__layout{gap:2rem}.kr-occasions{grid-template-columns:1fr 1fr}.kr-occasion:nth-child(3){border-inline-start:0;border-top:1px solid var(--kr-border)}.kr-occasion:nth-child(4){border-top:1px solid var(--kr-border)}}\n@media(max-width:40rem){.kr-wrap{width:calc(100% - 2.5rem)}.kr-section{padding-block:2.2rem}.kr-intro{display:flex;flex-direction:column;padding-top:2rem;gap:1.5rem}.kr-intro-image{order:1}.kr-intro-copy{order:0}.kr-finder-panel{order:2;width:100%;padding:1.4rem}.kr-intro-image img{aspect-ratio:4/3;height:auto;max-height:none}.kr-grid{grid-template-columns:1fr;gap:2rem}.kr-heading{display:block}.kr-occasions{grid-template-columns:1fr 1fr}.kr-occasion{padding:1.3rem .8rem}.kr-occasion h3{font-size:1.3rem}.kr-split,.kr-help-grid{grid-template-columns:1fr;gap:1.8rem}.kr-budget{grid-